-- ─────────────────────────────────────────────────────────────────────────────
-- Vim's HMS — Phase 3: diagnostics (LIS, analyzer interfacing, lab quality,
-- radiology, PACS index, investigation console)
--
-- `docs/prompts/phase-03-diagnostics.md` in tables. 100 of them, in six schemas,
-- **two of which are new** — and that is the dangerous part of this migration,
-- for the reason the Phase-1 migration learned the hard way and §B.1 repeats:
--
--   mdm            7  EN-027's diagnostics catalogue. `OP-004 §4` marks the test
--                     catalogue `lab_tests (mdm)` — the only entry in its own
--                     data model that is not in `lab` — and `EN-035 §4` does the
--                     same for `mdm_rad_procedures`. Specimen types, containers,
--                     tests, their analytes, panel membership, imaging
--                     procedures and the OP-022 investigation services.
--   lab     NEW   41  the laboratory. `docs/03 §Schemas` reserves it: "lab / rad
--                     / pharmacy / blood / ot / ip / er … one schema per bounded
--                     context". Orders, samples, labels, custody, transport,
--                     rejection, results and their versions, microbiology,
--                     histopathology, the critical-value loop, reports and
--                     deliveries; and the EN-031 quality estate — QC materials,
--                     targets, schedules, Westgard configuration, runs, actions,
--                     lockouts, the analyte QC state, EQA, calibration,
--                     competency, method validation and accreditation scope.
--   rad     NEW   36  radiology and the PACS index. OP-008 owns orders, items,
--                     rooms, appointments, exams, repeats, contrast, dose,
--                     reports, critical findings, follow-ups, peer review,
--                     teleradiology and the PC-PNDT Form F register; EN-008 owns
--                     the `pacs_*` index of what is in Orthanc — studies,
--                     series, instances, MWL, MPPS, corrections, tokens, the
--                     view audit, share links, media, retention and purge.
--   integration    9  EN-004's analyzer interfacing, prefix `lab_`, exactly
--                     where `EN-004 §4` puts it: instruments, code maps, the
--                     message log, the unmatched-result queue, the host-query
--                     worklist cache, auto-validation rule sets and their
--                     decisions, downtime and interface verification.
--   clinical       7  OP-022's investigation console — studies, media,
--                     annotations, reports and their versions, deliveries and
--                     the watch-folder agents.
--
-- Generated by `prisma migrate diff --from-url`, then post-processed by
-- `packages/db/scripts/apply-partitioning-phase3.mjs` BEFORE first application
-- to add declarative monthly partitioning to six high-write tables, to strip the
-- twenty-nine DropIndex statements Prisma emits for hand-written SQL it cannot
-- represent, and to strip one cosmetic AlterTable. Everything after the
-- Prisma-generated section is hand-written.
--
-- Read the four sections at the foot of this file in this order:
--   §A  monthly partitions, the writable-partition helper this phase needs that
--       Phase 2 did not, and why every partition key here is `timestamptz(3)`
--   §B  row-level security — **the coverage views are widened FIRST**, because
--       `lab` and `rad` are new schemas and a table in a schema the monitor does
--       not know about is unmonitored rather than safe
--   §C  the constraints and triggers that carry the safety guarantees:
--         C.4  the QC release gate, where `never_evaluated` is not `passed`
--         C.5  the append-only, hash-chained, typed result
--         C.6  the critical-value loop that is never withheld and never
--              undocumented
--         C.7  PC-PNDT: Form F completeness, and the assertion that no column
--              anywhere could hold a foetal sex
--   §D  least-privilege grants and append-only enforcement
--
-- ROLLBACK: see the block at the foot of this file.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE SCHEMA IF NOT EXISTS "lab";

-- CreateSchema
