)
PARTITION BY RANGE ("received_at");
-- Partitioned monthly: EN-004 §4 specifies monthly partitioning: one row per HL7/ASTM frame in each direction, with the raw bytes purged at 90 days and the parsed metadata kept two years.
-- A month must be droppable in < 1 s (docs/07 §4), which DELETE can never be.
-- "received_at" is timestamptz(3): a microsecond value read into a JS Date and
-- written back as half of this table's composite key would match no rows (D-31).


