    "sequence_no" INTEGER,
    "shift" VARCHAR(24),
    "operator_id" UUID,
    "entry_mode" "lab"."LabQcEntryMode" NOT NULL DEFAULT 'manual',
    "reagent_lot" VARCHAR(64),
    "calibration_id" UUID,
    "status" "lab"."LabQcRunStatus" NOT NULL DEFAULT 'in_control',
