    "created_by" UUID,

    CONSTRAINT "labq_qc_runs_pkey" PRIMARY KEY ("id","run_at")
)
PARTITION BY RANGE ("run_at");
-- Partitioned monthly: EN-031 §4 specifies monthly partitioning: two or three control levels per analyte per instrument per shift, retained five years for NABL.
-- A month must be droppable in < 1 s (docs/07 §4), which DELETE can never be.
-- "run_at" is timestamptz(3): a microsecond value read into a JS Date and
-- written back as half of this table's composite key would match no rows (D-31).


