-- ═════════════════════════════════════════════════════════════════════════════
-- §A. MONTHLY PARTITIONS
--
-- `core.ensure_month_partition()` (defined in ..._partitions_and_indexes,
-- extended in ..._rls_policies) creates one month, enables RLS on it, attaches
-- the tenant policies, grants and storage parameters — so a partition the worker
-- creates in 2032 is protected exactly like one created here.
--
-- ── Why this phase needs a second helper ────────────────────────────────────
--
-- `core.ensure_month_partition()` grants `SELECT, INSERT` and nothing else.
-- That was right for every Phase-0/1/2 partitioned table, because all of them —
-- the audit log, vitals, alert events, scores, the mobile sync ledger — are pure
-- append. Five of the six tables here are not:
--
--   `lab.lab_results`            its head projection (`current_version`,
--                                `current_status`, `current_flag`) is maintained
--                                by trigger on every new version.
--   `lab.lab_result_versions`    the review trail is stamped forward on the same
--                                row (entered → verified → authorised), and a
--                                superseded version is marked as such — the same
--                                narrow UPDATE `clinical.document_versions`
--                                keeps. The measured value never changes; §C.5
--                                is what makes that true.
--   `lab.labq_qc_runs`           `EN-031 §5`: a mistaken QC entry is *voided*
--                                with a reason and stays on the chart. Voiding
--                                is an UPDATE.
--   `integration.lab_if_messages` status moves received → parsed → matched →
--                                applied → acked, and `raw` is nulled at 90 days.
--   `rad.pacs_instances`         `is_key_image` is set when a radiologist picks
--                                a key image.
--
-- Granting UPDATE on the partitions this migration creates would work today and
-- fail in three months, when the worker creates April's partition through
-- `core.ensure_month_partition()` and it arrives read-append-only. Every INSERT
-- would succeed and every verification would fail, on the first day of a month,
-- in production. So the helper is the fix rather than the grants:
-- `core.ensure_month_partition_writable()` delegates to the existing function
-- and adds the one privilege, and the worker calls it for these five tables.
--
-- `rad.pacs_view_audit` deliberately uses the original: an audit row is written
-- once and never touched, which is the whole point of an audit row.
--
-- ── Why every partition key in this phase is `timestamptz(3)` ────────────────
--
-- Identical reasoning to Phase 2 §A, and it has not become less true. A
-- partitioned table's primary key must contain its partitioning column, so all
-- six carry a composite key `(id, <timestamp>)`. At `timestamptz(6)` PostgreSQL
-- stores microseconds and a JavaScript `Date` holds milliseconds, so a key read
-- into an application object and written back matches **zero rows** — silently,
-- because an UPDATE that affects nothing is not an error. D-31 answers that with
-- a rule every caller must remember; millisecond precision removes the trap
-- instead. Nothing here is measured to the microsecond: an analyzer result, a
-- QC point, a stored DICOM object and a viewer open are all events whose
-- ordering within a millisecond comes from the time-ordered UUIDv7 in `id`.
--
-- Premake the current month, three ahead and one behind: a back-dated result
-- from the downtime protocol (docs/01 §7) — or a 30-minute analyzer outage
-- replaying across a month boundary (`phase-03` exit gate 7) — must have
-- somewhere to land.
-- ═════════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION core.ensure_month_partition_writable(
  p_schema      text,
  p_table       text,
  p_month_start date
) RETURNS text
LANGUAGE plpgsql
AS $$
DECLARE
  v_partition text;
BEGIN
  v_partition := core.ensure_month_partition(p_schema, p_table, p_month_start);
  -- The one privilege the base helper withholds. DELETE is still never granted:
  -- a clinical or financial row is never hard-deleted (CLAUDE.md §4), and a
  -- month is removed by DETACH + DROP under an explicit release procedure, by
  -- `hms_migrator`, never by the application.
  EXECUTE format('GRANT UPDATE ON %I.%I TO hms_app', p_schema, v_partition);
  RETURN v_partition;
END;
$$;

COMMENT ON FUNCTION core.ensure_month_partition_writable IS
  'core.ensure_month_partition() plus GRANT UPDATE. Phase 3 is the first phase with partitioned tables that are not pure append: a result version is stamped verified and then authorised on the same row, a QC run is voided rather than deleted, and an interface message moves through its status ladder. Without this the partition the worker creates next month would arrive insert-only and every verification would fail on the first of the month. DELETE is still never granted.';

GRANT EXECUTE ON FUNCTION core.ensure_month_partition_writable(text, text, date) TO hms_retention;

DO $$
DECLARE
  v_writable text[][] := ARRAY[
    ['lab', 'lab_results'],
    ['lab', 'lab_result_versions'],
    ['lab', 'labq_qc_runs'],
    ['integration', 'lab_if_messages'],
    ['rad', 'pacs_instances']
  ];
  i int;
  m int;
BEGIN
  FOR i IN 1 .. array_length(v_writable, 1) LOOP
    FOR m IN -1 .. 3 LOOP
      PERFORM core.ensure_month_partition_writable(
        v_writable[i][1],
        v_writable[i][2],
        (date_trunc('month', now()) + (m || ' month')::interval)::date
      );
    END LOOP;
  END LOOP;

  -- Append-only: the base helper, which grants SELECT and INSERT only.
  FOR m IN -1 .. 3 LOOP
    PERFORM core.ensure_month_partition(
      'rad', 'pacs_view_audit',
      (date_trunc('month', now()) + (m || ' month')::interval)::date
    );
  END LOOP;
END
$$;

-- ── DEFAULT partitions ───────────────────────────────────────────────────────
-- Without one, an INSERT whose timestamp falls outside every declared range
-- fails. For `lab.lab_result_versions` that failure would refuse to store a
-- measured value that already exists on a bench — the worst possible way for a
-- laboratory system to fail, because the number is real whether or not the
-- database will hold it. For `rad.pacs_view_audit` it would refuse to record
-- that somebody opened a study, which turns a missed maintenance run into an
-- audit gap. A default partition turns both into a monitored anomaly: a
-- non-empty default partition is alertable, never normal.
DO $$
DECLARE
  v_tables text[][] := ARRAY[
    ['lab', 'lab_results', 'rw'],
    ['lab', 'lab_result_versions', 'rw'],
    ['lab', 'labq_qc_runs', 'rw'],
    ['integration', 'lab_if_messages', 'rw'],
    ['rad', 'pacs_instances', 'rw'],
    ['rad', 'pacs_view_audit', 'ro']
  ];
  i int;
  v_schema     text;
  v_table      text;
  v_mode       text;
  v_default    text;
  v_qualified  text;
  v_using      text;
  v_has_branch boolean;
  v_branch_null boolean;
BEGIN
  FOR i IN 1 .. array_length(v_tables, 1) LOOP
    v_schema  := v_tables[i][1];
    v_table   := v_tables[i][2];
    v_mode    := v_tables[i][3];
    v_default := v_table || '_default';
    v_qualified := format('%I.%I', v_schema, v_default);

    IF NOT EXISTS (
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = v_schema AND c.relname = v_default
    ) THEN
      EXECUTE format('CREATE TABLE %s PARTITION OF %I.%I DEFAULT', v_qualified, v_schema, v_table);
    END IF;

    SELECT count(*) FILTER (WHERE column_name = 'branch_id') > 0,
           bool_or(column_name = 'branch_id' AND is_nullable = 'YES')
    INTO v_has_branch, v_branch_null
    FROM information_schema.columns
    WHERE table_schema = v_schema AND table_name = v_table;

    v_using := 'hospital_id = ANY (core.accessible_hospital_ids())';
    IF v_has_branch THEN
      v_using := v_using || ' AND (branch_id IS NULL OR branch_id = ANY (core.current_branch_ids()))';
    END IF;

    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', v_qualified);
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %s', v_qualified);
    EXECUTE format('CREATE POLICY tenant_isolation ON %s FOR ALL TO hms_app USING (%s) WITH CHECK (%s)',
                   v_qualified, v_using, v_using);
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation_ro ON %s', v_qualified);
    EXECUTE format('CREATE POLICY tenant_isolation_ro ON %s FOR SELECT TO hms_readonly USING (%s)',
                   v_qualified, v_using);

    IF v_mode = 'rw' THEN
      EXECUTE format('GRANT SELECT, INSERT, UPDATE ON %s TO hms_app', v_qualified);
    ELSE
      EXECUTE format('GRANT SELECT, INSERT ON %s TO hms_app', v_qualified);
    END IF;
    EXECUTE format('GRANT SELECT ON %s TO hms_readonly', v_qualified);

    EXECUTE format(
      'COMMENT ON TABLE %s IS %L',
      v_qualified,
      'Safety net only. A non-empty default partition is an alertable anomaly (docs/07 §6), never a normal state.'
    );
  END LOOP;
END
$$;


-- ═════════════════════════════════════════════════════════════════════════════
-- §B. ROW-LEVEL SECURITY
--
-- **Phase 3 adds two schemas**, and `docs/prompts/phase-03 §Non-negotiables 6`
-- says exactly what that costs: "RLS on every new table, asserted inside the
-- migration as Phase 2 does. If you add a NEW schema, widen the coverage views
-- *before* generating policies, or your tables are invisible to the monitor that
-- exists to catch them."
--
-- Phase 1 is where that lesson was paid for. `core.v_rls_coverage`,
-- `core.v_rls_open_policies` and `core.v_grant_coverage` were written against
-- `('core','mdm','integration')`, and ninety-three new tables in five new
-- schemas would have been invisible to the monitor — the integration suite would
-- have gone on reporting "zero unprotected tables" while the patient master sat
-- wide open. Phase 2 added no schema and asserted that rather than assuming it.
--
-- Phase 3 adds `lab` and `rad`. So the views are widened first, before a single
-- policy is written, and B.4 then asserts the result through the widened views —
-- which is the only way the assertion can fail on a table somebody forgot.
-- ═════════════════════════════════════════════════════════════════════════════

-- ── 1. widen the coverage monitors to the two new schemas ────────────────────
-- Column lists are unchanged; only the schema list moves. `CREATE OR REPLACE
-- VIEW` requires that, which is a useful accident: it means this cannot quietly
-- become a different view.
CREATE OR REPLACE VIEW core.v_rls_coverage AS
SELECT
  n.nspname                                        AS schema_name,
  c.relname                                        AS table_name,
  c.relrowsecurity                                 AS rls_enabled,
  c.relforcerowsecurity                            AS rls_forced,
  count(p.polname) FILTER (WHERE p.polname IS NOT NULL) AS policy_count,
  bool_or(p.polname = 'tenant_isolation')          AS has_tenant_policy,
  bool_or(p.polname = 'tenant_isolation' AND p.polwithcheck IS NOT NULL) AS has_write_check,
  EXISTS (
    SELECT 1 FROM information_schema.columns col
    WHERE col.table_schema = n.nspname AND col.table_name = c.relname
      AND col.column_name = 'hospital_id'
  )                                                AS is_tenant_scoped
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
LEFT JOIN pg_policy p ON p.polrelid = c.oid
WHERE n.nspname IN ('core', 'mdm', 'patient', 'clinical', 'lab', 'rad', 'queue', 'engage', 'billing', 'integration')
  AND c.relkind IN ('r', 'p')
  AND c.relispartition = false
  AND c.relname NOT LIKE '\_prisma%'
GROUP BY n.nspname, c.relname, c.relrowsecurity, c.relforcerowsecurity, c.oid;

COMMENT ON VIEW core.v_rls_coverage IS
  'One row per application table with its RLS status. `has_tenant_policy` false or `has_write_check` false on a tenant-scoped table is a release-blocking defect (docs/09 §3.1). The schema list must be widened by the migration that adds a schema — a table in a schema this view does not know about is unmonitored, not safe. Widened for `lab` and `rad` in the Phase-3 migration.';

GRANT SELECT ON core.v_rls_coverage TO hms_app, hms_readonly;

CREATE OR REPLACE VIEW core.v_rls_open_policies AS
SELECT
  n.nspname                          AS schema_name,
  c.relname                          AS table_name,
  p.polname                          AS policy_name,
  pg_get_expr(p.polqual, p.polrelid) AS using_expr,
  ARRAY(
    SELECT r.rolname FROM pg_roles r WHERE r.oid = ANY (p.polroles) ORDER BY r.rolname
  )                                  AS granted_to
FROM pg_policy p
JOIN pg_class c ON c.oid = p.polrelid
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE n.nspname IN ('core', 'mdm', 'patient', 'clinical', 'lab', 'rad', 'queue', 'engage', 'billing', 'integration')
  AND pg_get_expr(p.polqual, p.polrelid) = 'true'
  -- `hms_retention` is excluded by design; `hms_migrator` owns the tables and
  -- bypasses RLS anyway.
  AND EXISTS (
    SELECT 1 FROM pg_roles r
    WHERE r.oid = ANY (p.polroles) AND r.rolname IN ('hms_app', 'hms_readonly')
  );

COMMENT ON VIEW core.v_rls_open_policies IS
  'Policies granting unrestricted reads to a request-serving role (hms_app / hms_readonly). The integration suite asserts this equals exactly {permissions, setting_definitions}; anything else is a cross-tenant leak. hms_retention is deliberately excluded — it spans tenants to archive partitions and holds no privilege on business tables. Widened for `lab` and `rad` in the Phase-3 migration.';

GRANT SELECT ON core.v_rls_open_policies TO hms_app, hms_readonly;

CREATE OR REPLACE VIEW core.v_grant_coverage AS
SELECT
  t.table_schema,
  t.table_name,
  bool_or(g.privilege_type = 'SELECT' AND g.grantee = 'hms_app') AS app_can_select,
  bool_or(g.privilege_type = 'INSERT' AND g.grantee = 'hms_app') AS app_can_insert,
  bool_or(g.privilege_type = 'UPDATE' AND g.grantee = 'hms_app') AS app_can_update,
  bool_or(g.privilege_type = 'DELETE' AND g.grantee = 'hms_app') AS app_can_delete,
  bool_or(g.grantee = 'hms_readonly' AND g.privilege_type <> 'SELECT') AS readonly_has_write
FROM information_schema.tables t
LEFT JOIN information_schema.role_table_grants g
  ON g.table_schema = t.table_schema AND g.table_name = t.table_name
WHERE t.table_schema IN ('core', 'mdm', 'patient', 'clinical', 'lab', 'rad', 'queue', 'engage', 'billing', 'integration')
  AND t.table_type = 'BASE TABLE'
GROUP BY t.table_schema, t.table_name;

COMMENT ON VIEW core.v_grant_coverage IS
  'Effective privileges per table. `readonly_has_write` true anywhere, or `app_can_update` true on core.audit_log, is a release-blocking defect (docs/04 §6, EN-024 §3.4.4). Widened for `lab` and `rad` in the Phase-3 migration.';

GRANT SELECT ON core.v_grant_coverage TO hms_app, hms_readonly;

-- The widening is only useful if it actually reached the two new schemas, and a
-- `CREATE OR REPLACE` that silently no-oped would leave the same hole Phase 1
-- had. Assert it before anything depends on it.
DO $$
DECLARE
  v_schema text;
  v_view   text;
BEGIN
  FOREACH v_view IN ARRAY ARRAY['v_rls_coverage', 'v_rls_open_policies', 'v_grant_coverage'] LOOP
    FOREACH v_schema IN ARRAY ARRAY['core', 'mdm', 'patient', 'clinical', 'lab', 'rad', 'queue', 'engage', 'billing', 'integration'] LOOP
      IF NOT EXISTS (
        SELECT 1 FROM pg_views v
        WHERE v.schemaname = 'core' AND v.viewname = v_view
          AND v.definition LIKE '%''' || v_schema || '''%'
      ) THEN
        RAISE EXCEPTION 'core.% does not cover schema % — widen it before generating policies, not after', v_view, v_schema;
      END IF;
    END LOOP;
  END LOOP;
END
$$;

-- ── 2. schema-level privileges for the two new schemas ───────────────────────
-- Phase 1 did this for `patient`, `clinical`, `queue`, `engage` and `billing`.
-- The `ALTER DEFAULT PRIVILEGES` is what means a Phase-6 migration adding
-- `lab.blood_bank_units` does not have to remember to grant anything; the tables
-- created *by this migration* predate it, and are picked up by the loop in §D.
GRANT USAGE ON SCHEMA lab, rad TO hms_app;
GRANT USAGE ON SCHEMA lab, rad TO hms_readonly;
GRANT USAGE ON SCHEMA lab, rad TO hms_retention;

-- The app role cannot DDL. An application-level SQL injection can no more
-- CREATE TABLE in `lab` than it can in `core`.
REVOKE CREATE ON SCHEMA lab, rad FROM PUBLIC;
REVOKE CREATE ON SCHEMA lab, rad FROM hms_app, hms_readonly, hms_retention;

ALTER DEFAULT PRIVILEGES FOR ROLE hms_migrator IN SCHEMA lab, rad
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO hms_app;
ALTER DEFAULT PRIVILEGES FOR ROLE hms_migrator IN SCHEMA lab, rad
  GRANT SELECT ON TABLES TO hms_readonly;
ALTER DEFAULT PRIVILEGES FOR ROLE hms_migrator IN SCHEMA lab, rad
  GRANT USAGE, SELECT ON SEQUENCES TO hms_app;

-- ── 3. the policy generator ──────────────────────────────────────────────────
-- Identical in shape to the Phase-0, Phase-1 and Phase-2 generators, and
-- narrowed the same way to tables that do not already carry a `tenant_isolation`
-- policy, so it cannot clobber the explicit tenant-key exceptions or the
-- global-catalogue policies.
--
-- Every Phase-3 table carries `hospital_id NOT NULL`. There is no shipped
-- content in this phase: a test catalogue, a rejection list, a Westgard rule set
-- and a DRL are all things a laboratory or an imaging department authors under
-- its own accreditation, and shipping a "product default" reference range would
-- be exactly the guessing `CLAUDE.md §0.1` forbids. Seeds create them per
-- hospital instead.
DO $$
DECLARE
  r                record;
  v_has_hospital   boolean;
  v_hospital_null  boolean;
  v_has_branch     boolean;
  v_using          text;
  v_check          text;
  v_count          int := 0;
BEGIN
  FOR r IN
    SELECT n.nspname AS schema_name, c.relname AS table_name
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname IN ('core', 'mdm', 'patient', 'clinical', 'lab', 'rad', 'queue', 'engage', 'billing', 'integration')
      AND c.relkind IN ('r', 'p')
      AND c.relispartition = false
      AND c.relname NOT LIKE '\_prisma%'
      AND c.relname <> 'cdss_safety_floor'
      AND NOT EXISTS (
        SELECT 1 FROM pg_policy p
        WHERE p.polrelid = c.oid AND p.polname = 'tenant_isolation'
      )
    ORDER BY n.nspname, c.relname
  LOOP
    SELECT
      count(*) FILTER (WHERE column_name = 'hospital_id') > 0,
      bool_or(column_name = 'hospital_id' AND is_nullable = 'YES'),
      count(*) FILTER (WHERE column_name = 'branch_id') > 0
    INTO v_has_hospital, v_hospital_null, v_has_branch
    FROM information_schema.columns
    WHERE table_schema = r.schema_name AND table_name = r.table_name;

    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', r.schema_name, r.table_name);

    IF v_has_hospital AND NOT v_hospital_null THEN
      v_using := 'hospital_id = ANY (core.accessible_hospital_ids())';
      IF v_has_branch THEN
        v_using := v_using || ' AND (branch_id IS NULL OR branch_id = ANY (core.current_branch_ids()))';
      END IF;
      v_check := v_using;

    ELSIF v_has_hospital AND v_hospital_null THEN
      v_using := '(hospital_id IS NULL OR hospital_id = ANY (core.accessible_hospital_ids()))';
      IF v_has_branch THEN
        v_using := v_using || ' AND (branch_id IS NULL OR branch_id = ANY (core.current_branch_ids()))';
      END IF;
      v_check := 'hospital_id = ANY (core.accessible_hospital_ids())';
      IF v_has_branch THEN
        v_check := v_check || ' AND (branch_id IS NULL OR branch_id = ANY (core.current_branch_ids()))';
      END IF;

    ELSE
      -- Deliberately NOT `USING (true)`: a table with no tenant column that
      -- nobody classified fails loudly at first use rather than leaking.
      v_using := 'false';
      v_check := 'false';
    END IF;

    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I.%I', r.schema_name, r.table_name);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I.%I FOR ALL TO hms_app USING (%s) WITH CHECK (%s)',
      r.schema_name, r.table_name, v_using, v_check
    );

    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation_ro ON %I.%I', r.schema_name, r.table_name);
    EXECUTE format(
      'CREATE POLICY tenant_isolation_ro ON %I.%I FOR SELECT TO hms_readonly USING (%s)',
      r.schema_name, r.table_name, v_using
    );

    v_count := v_count + 1;
  END LOOP;

  RAISE NOTICE 'Row-level security enabled with tenant policies on % new tables', v_count;
END
$$;

-- ── 4. assert, in the migration itself, what the integration suite asserts ──
-- A migration that half-applied its own security is worse than one that failed,
-- because it looks finished.
DO $$
DECLARE
  v_unprotected text;
  v_lab_rad     bigint;
BEGIN
  SELECT string_agg(format('%s.%s', schema_name, table_name), ', ' ORDER BY schema_name, table_name)
  INTO v_unprotected
  FROM core.v_rls_coverage
  WHERE NOT rls_enabled OR NOT has_tenant_policy OR (is_tenant_scoped AND NOT has_write_check);

  IF v_unprotected IS NOT NULL THEN
    RAISE EXCEPTION 'Phase 3 migration left table(s) without complete row-level security: %', v_unprotected;
  END IF;

  -- And the widened view must actually be seeing the new schemas' tables, not
  -- merely mentioning their names. A widening that matched nothing would pass
  -- the assertion above vacuously.
  SELECT count(*) INTO v_lab_rad
  FROM core.v_rls_coverage WHERE schema_name IN ('lab', 'rad');

  IF v_lab_rad < 70 THEN
    RAISE EXCEPTION
      'core.v_rls_coverage reports only % table(s) in lab/rad; Phase 3 created 77. The view is not seeing them, which is the Phase-1 defect all over again.',
      v_lab_rad;
  END IF;

  -- `core.v_rls_open_policies` must still be exactly the two Phase-0 catalogues.
  SELECT string_agg(DISTINCT table_name, ', ' ORDER BY table_name)
  INTO v_unprotected
  FROM core.v_rls_open_policies
  WHERE table_name NOT IN ('permissions', 'setting_definitions');

  IF v_unprotected IS NOT NULL THEN
    RAISE EXCEPTION 'Phase 3 migration introduced an unrestricted read policy on: %', v_unprotected;
  END IF;
END
$$;


-- ═════════════════════════════════════════════════════════════════════════════
-- §C. THE CONSTRAINTS AND TRIGGERS THAT CARRY THE SAFETY GUARANTEES
--
-- Each of these encodes a rule a spec, an accreditation standard or an Act of
-- Parliament states as non-negotiable. They are constraints and triggers rather
-- than service checks for the reason Phase 2 gave and this phase makes sharper:
-- a laboratory result can arrive through the web app, through an HL7 listener,
-- through an ASTM serial reader, through a downtime replay, through a referral
-- lab's file import and through a data migration. Six code paths, of which
-- exactly one is the one everybody remembers to guard.
-- ═════════════════════════════════════════════════════════════════════════════

-- ── C.1 the effective-dated masters ──────────────────────────────────────────
-- EN-027 §5: "Effective ranges per `record_key` must not overlap (enforced by a
-- btree_gist exclusion constraint, not just application code)." Twelve more
-- masters join the nineteen that already carry it.
DO $$
DECLARE
  v_tables text[][] := ARRAY[
    ['mdm', 'mdm_lab_specimen_types'],
    ['mdm', 'mdm_lab_containers'],
    ['mdm', 'mdm_lab_tests'],
    ['mdm', 'mdm_lab_test_parameters'],
    ['mdm', 'mdm_lab_panel_members'],
    ['mdm', 'mdm_rad_procedures'],
    ['mdm', 'mdm_investigation_services'],
    ['lab', 'lab_rejection_reasons'],
    ['lab', 'lab_tat_targets'],
    ['lab', 'lab_referral_labs'],
    ['lab', 'lab_reference_ranges'],
    ['lab', 'lab_delta_check_rules']
  ];
  i int;
BEGIN
  FOR i IN 1 .. array_length(v_tables, 1) LOOP
    EXECUTE format(
      'ALTER TABLE %I.%I ADD CONSTRAINT %I EXCLUDE USING gist ('
        || 'record_key WITH =, '
        || 'tstzrange(effective_from, COALESCE(effective_to, ''infinity''::timestamptz)) WITH &&'
        || ') WHERE (status IN (''active'', ''superseded''))',
      v_tables[i][1], v_tables[i][2], v_tables[i][2] || '_no_overlap'
    );
  END LOOP;
END
$$;

-- ── C.2 the diagnostics catalogue ────────────────────────────────────────────

-- A container with no cap colour cannot guide anybody, and a hex that is not a
-- hex renders as nothing on both the label and the screen.
ALTER TABLE mdm.mdm_lab_containers
  ADD CONSTRAINT mdm_lab_containers_cap_colour_present CHECK (length(btrim(cap_colour)) > 0);
ALTER TABLE mdm.mdm_lab_containers
  ADD CONSTRAINT mdm_lab_containers_cap_hex_shape
  CHECK (cap_colour_hex IS NULL OR cap_colour_hex ~ '^#[0-9a-fA-F]{6}$');
ALTER TABLE mdm.mdm_lab_containers
  ADD CONSTRAINT mdm_lab_containers_volumes_positive
  CHECK ((draw_volume_ml IS NULL OR draw_volume_ml > 0) AND (min_volume_ml IS NULL OR min_volume_ml > 0));
-- CLSI GP41: the order of draw is an ordering, and two containers claiming the
-- same position leave the phlebotomist's screen non-deterministic.
CREATE UNIQUE INDEX IF NOT EXISTS uq_mdm_lab_containers_order_of_draw
  ON mdm.mdm_lab_containers (hospital_id, order_of_draw)
  WHERE status = 'active' AND order_of_draw IS NOT NULL;

ALTER TABLE mdm.mdm_lab_specimen_types
  ADD CONSTRAINT mdm_lab_specimen_types_stability_positive
  CHECK (stability_hours IS NULL OR stability_hours > 0);
ALTER TABLE mdm.mdm_lab_specimen_types
  ADD CONSTRAINT mdm_lab_specimen_types_retention_positive
  CHECK (retention_days IS NULL OR retention_days > 0);

-- A panel has members and no result type of its own; a non-panel test resolves
-- to something measurable. Getting this backwards produces an order line nobody
-- can result.
ALTER TABLE mdm.mdm_lab_tests
  ADD CONSTRAINT mdm_lab_tests_volume_positive
  CHECK (volume_ml IS NULL OR volume_ml > 0);
ALTER TABLE mdm.mdm_lab_tests
  ADD CONSTRAINT mdm_lab_tests_decimals_range
  CHECK (decimals IS NULL OR (decimals >= 0 AND decimals <= 8));
ALTER TABLE mdm.mdm_lab_tests
  ADD CONSTRAINT mdm_lab_tests_tat_positive
  CHECK (
    (tat_routine_minutes IS NULL OR tat_routine_minutes > 0)
    AND (tat_urgent_minutes IS NULL OR tat_urgent_minutes > 0)
    AND (tat_stat_minutes IS NULL OR tat_stat_minutes > 0)
  );
-- A STAT target slower than a routine one is a configuration error that makes
-- every SLA dashboard lie.
ALTER TABLE mdm.mdm_lab_tests
  ADD CONSTRAINT mdm_lab_tests_tat_ordering
  CHECK (
    (tat_stat_minutes IS NULL OR tat_urgent_minutes IS NULL OR tat_stat_minutes <= tat_urgent_minutes)
    AND (tat_urgent_minutes IS NULL OR tat_routine_minutes IS NULL OR tat_urgent_minutes <= tat_routine_minutes)
  );
-- An outsourced-by-default test names the partner it goes to.
ALTER TABLE mdm.mdm_lab_tests
  ADD CONSTRAINT mdm_lab_tests_outsource_partner
  CHECK (is_outsourced_default = false OR referral_lab_key IS NOT NULL);
-- A calculated test names the formula that computes it; a formula on a test
-- nobody calculates is a note in the wrong column.
ALTER TABLE mdm.mdm_lab_tests
  ADD CONSTRAINT mdm_lab_tests_calc_pairing
  CHECK (is_calculated = (calc_formula_key IS NOT NULL));
-- Absurd bounds are a range, not two numbers.
ALTER TABLE mdm.mdm_lab_tests
  ADD CONSTRAINT mdm_lab_tests_absurd_order
  CHECK (absurd_low IS NULL OR absurd_high IS NULL OR absurd_low < absurd_high);
-- A fasting requirement with no duration cannot be messaged to a patient.
ALTER TABLE mdm.mdm_lab_tests
  ADD CONSTRAINT mdm_lab_tests_fasting_hours
  CHECK (requires_fasting = false OR fasting_hours IS NOT NULL);
ALTER TABLE mdm.mdm_lab_tests
  ADD CONSTRAINT mdm_lab_tests_panel_result_type
  CHECK (is_panel = false OR result_type = 'numeric');

ALTER TABLE mdm.mdm_lab_test_parameters
  ADD CONSTRAINT mdm_lab_test_parameters_decimals_range
  CHECK (decimals IS NULL OR (decimals >= 0 AND decimals <= 8));
ALTER TABLE mdm.mdm_lab_test_parameters
  ADD CONSTRAINT mdm_lab_test_parameters_calc_pairing
  CHECK (is_calculated = (calc_formula_key IS NOT NULL));
ALTER TABLE mdm.mdm_lab_test_parameters
  ADD CONSTRAINT mdm_lab_test_parameters_absurd_order
  CHECK (absurd_low IS NULL OR absurd_high IS NULL OR absurd_low < absurd_high);

-- A panel cannot contain itself, directly. (Deeper cycles are refused by the
-- expansion service; a self-reference is the one a CHECK can catch and is by
-- far the most common.)
ALTER TABLE mdm.mdm_lab_panel_members
  ADD CONSTRAINT mdm_lab_panel_members_not_self
  CHECK (panel_key <> member_test_key);

-- Imaging: a laterality-required procedure and a DRL that is a positive number.
ALTER TABLE mdm.mdm_rad_procedures
  ADD CONSTRAINT mdm_rad_procedures_duration_positive
  CHECK (duration_minutes IS NULL OR duration_minutes > 0);
ALTER TABLE mdm.mdm_rad_procedures
  ADD CONSTRAINT mdm_rad_procedures_drl_positive
  CHECK (
    (drl_ctdivol_mgy IS NULL OR drl_ctdivol_mgy > 0)
    AND (drl_dlp_mgycm IS NULL OR drl_dlp_mgycm > 0)
    AND (drl_dap_gycm2 IS NULL OR drl_dap_gycm2 > 0)
  );
-- `OP-008 §3.6`: a diagnostic reference level is only meaningful for an ionising
-- procedure, and an ionising procedure needs a k-factor to estimate a dose from.
ALTER TABLE mdm.mdm_rad_procedures
  ADD CONSTRAINT mdm_rad_procedures_drl_requires_ionising
  CHECK (is_ionising OR (drl_ctdivol_mgy IS NULL AND drl_dlp_mgycm IS NULL AND drl_dap_gycm2 IS NULL));
-- **PC-PNDT.** Sex selection is an offence under the Act regardless of modality,
-- but Form F attaches to ultrasound and imaging techniques used on a pregnant
-- woman. A CT flagged `is_pcpndt` is a configuration mistake that would demand a
-- Form F for a head scan; an ultrasound is what the Act contemplates.
ALTER TABLE mdm.mdm_rad_procedures
  ADD CONSTRAINT mdm_rad_procedures_pcpndt_modality
  CHECK (is_pcpndt = false OR modality IN ('US', 'MR', 'OT'));
-- An ultrasound is not ionising. Flagging one as such would demand a dose record
-- that no machine can produce and would block every obstetric scan at sign-off.
ALTER TABLE mdm.mdm_rad_procedures
  ADD CONSTRAINT mdm_rad_procedures_ionising_modality
  CHECK (is_ionising = false OR modality NOT IN ('US', 'MR'));
ALTER TABLE mdm.mdm_rad_procedures
  ADD CONSTRAINT mdm_rad_procedures_tat_ordering
  CHECK (
    (tat_stat_minutes IS NULL OR tat_urgent_minutes IS NULL OR tat_stat_minutes <= tat_urgent_minutes)
    AND (tat_urgent_minutes IS NULL OR tat_routine_minutes IS NULL OR tat_urgent_minutes <= tat_routine_minutes)
  );

ALTER TABLE mdm.mdm_investigation_services
  ADD CONSTRAINT mdm_investigation_services_tat_positive
  CHECK (tat_report_minutes IS NULL OR tat_report_minutes > 0);


-- ── C.3 the pre-analytical phase: the rejected sample, and its recollection ──
--
-- `docs/prompts/phase-03 §Non-negotiables 2`: "A rejected sample must carry a
-- reason, and recollection must be trackable to the original order."
-- `phase-03` exit gate 3 is the test: "A hemolysed sample is rejected with
-- reason; the doctor and patient are notified; recollection is tracked."
--
-- Four mechanisms, because each closes a different hole.

-- 1. The reason and the rejection are the same fact, in both directions. A
--    rejected sample with no reason cannot be stored — and neither can a reason
--    attached to a sample nobody rejected, which is how a rejection rate becomes
--    uncountable.
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_rejection_reason_pairing
  CHECK ((status = 'rejected') = (rejection_reason_key IS NOT NULL));
-- 2. And it is attributed. "The sample was rejected" with no name and no time is
--    not a NABL record, it is a rumour.
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_rejection_attributed
  CHECK (status <> 'rejected' OR (rejected_by IS NOT NULL AND rejected_at IS NOT NULL));
-- 3. The coded reason travels with its code, snapshotted, so a later edit of the
--    master cannot rewrite why a specimen was thrown away.
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_rejection_code_snapshot
  CHECK ((rejection_reason_key IS NULL) = (rejection_reason_code IS NULL));
-- 4. A sample is not its own recollection, and not its own aliquot.
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_recollection_not_self
  CHECK (recollection_of_sample_id IS NULL OR recollection_of_sample_id <> id);
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_parent_not_self
  CHECK (parent_sample_id IS NULL OR parent_sample_id <> id);

-- `OP-004 §5`: "label must be scanned to mark collected (no manual 'collected'
-- without scan unless printer failure override, audited)". Two scans, or a named
-- override with a reason. There is no third option, and "collected" with neither
-- cannot be stored.
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_two_identifier_check
  CHECK (
    collected_at IS NULL
    OR (patient_scan_verified AND container_scan_verified)
    OR (identity_override_reason IS NOT NULL AND identity_override_by IS NOT NULL)
  );
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_override_pairing
  CHECK ((identity_override_reason IS NULL) = (identity_override_by IS NULL));
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_collection_attributed
  CHECK ((collected_at IS NULL) = (collected_by IS NULL));
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_receipt_attributed
  CHECK ((received_at IS NULL) = (received_by IS NULL));
-- Time runs forwards. A specimen received before it was drawn is a data-entry
-- error that makes the transport-time KPI negative.
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_time_order
  CHECK (
    (collected_at IS NULL OR received_at IS NULL OR received_at >= collected_at)
    AND (received_at IS NULL OR accessioned_at IS NULL OR accessioned_at >= received_at)
  );
-- `OP-004 §3.2.4`: a medico-legal specimen carries a tamper-evident seal.
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_custody_seal
  CHECK (is_chain_of_custody = false OR seal_no IS NOT NULL);
ALTER TABLE lab.lab_samples
  ADD CONSTRAINT lab_samples_barcode_present CHECK (length(btrim(barcode)) > 0);

-- The relational half a CHECK cannot express: the recollection must lead back to
-- the order that was rejected.
CREATE OR REPLACE FUNCTION lab.enforce_recollection_trace()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_orig record;
  v_linked boolean;
BEGIN
  IF NEW.recollection_of_sample_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT id, order_id, patient_id, status, hospital_id
  INTO v_orig
  FROM lab.lab_samples
  WHERE id = NEW.recollection_of_sample_id;

  IF v_orig.id IS NULL THEN
    RAISE EXCEPTION
      'lab.lab_samples: recollection names sample % which does not exist. A recollection that cannot be traced to what it replaces is an untracked specimen.',
      NEW.recollection_of_sample_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  IF v_orig.hospital_id <> NEW.hospital_id THEN
    RAISE EXCEPTION 'lab.lab_samples: a recollection cannot cross tenants'
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  -- Only a rejected specimen is recollected. Re-drawing a satisfactory sample is
  -- an add-on or a repeat, and calling it a recollection would corrupt the NABL
  -- rejection indicator in the flattering direction.
  IF v_orig.status <> 'rejected' THEN
    RAISE EXCEPTION
      'lab.lab_samples: sample % is % and not rejected, so this is not a recollection. Record a repeat draw as a new sample on the order instead.',
      v_orig.id, v_orig.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_orig.patient_id <> NEW.patient_id THEN
    RAISE EXCEPTION
      'lab.lab_samples: recollection is for a different patient than the sample it replaces'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Traceable to the original *order*, which is what exit gate 3 asks for. Two
  -- shapes are legitimate and both are traceable: the recollection sits on the
  -- same lab order, or it sits on a new zero-charge order whose lines chain back
  -- through `recollection_of_order_test_id`. Anything else is a new specimen
  -- wearing a recollection's label.
  IF NEW.order_id <> v_orig.order_id THEN
    SELECT EXISTS (
      SELECT 1
      FROM lab.lab_order_tests newt
      JOIN lab.lab_order_tests oldt ON oldt.id = newt.recollection_of_order_test_id
      WHERE newt.order_id = NEW.order_id
        AND oldt.order_id = v_orig.order_id
    ) INTO v_linked;

    IF NOT v_linked THEN
      RAISE EXCEPTION
        'lab.lab_samples: recollection of sample % is on order % but nothing links that order back to the original order %. Set lab_order_tests.recollection_of_order_test_id on the replacement line, or put the recollection on the original order.',
        v_orig.id, NEW.order_id, v_orig.order_id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION lab.enforce_recollection_trace IS
  'phase-03 exit gate 3: a recollection is traceable to the original order. Accepts the two legitimate shapes — same order, or a new order whose lines chain back through recollection_of_order_test_id — and refuses everything else, including a "recollection" of a specimen that was never rejected, which would flatter the NABL rejection indicator.';

DROP TRIGGER IF EXISTS trg_lab_samples_recollection_trace ON lab.lab_samples;
CREATE TRIGGER trg_lab_samples_recollection_trace
  BEFORE INSERT OR UPDATE OF recollection_of_sample_id, order_id ON lab.lab_samples
  FOR EACH ROW EXECUTE FUNCTION lab.enforce_recollection_trace();

-- The recollection worklist: rejected specimens whose replacement has not been
-- drawn. Partial, so it stays a live query on a phlebotomist's tablet.
CREATE INDEX IF NOT EXISTS idx_lab_samples_awaiting_recollection
  ON lab.lab_samples (hospital_id, branch_id, rejected_at DESC)
  WHERE status = 'rejected';

-- The rejection reason must resolve to an active reason belonging to this
-- hospital. A foreign key cannot say "active", and an inactive reason silently
-- accepted is how a retired code keeps appearing on a quality report.
CREATE OR REPLACE FUNCTION lab.enforce_rejection_reason()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_code text;
BEGIN
  IF NEW.rejection_reason_key IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT r.code INTO v_code
  FROM lab.lab_rejection_reasons r
  WHERE r.record_key = NEW.rejection_reason_key
    AND r.hospital_id = NEW.hospital_id
    AND r.status = 'active'
    AND r.effective_from <= now()
    AND (r.effective_to IS NULL OR r.effective_to > now())
  ORDER BY r.effective_from DESC
  LIMIT 1;

  IF v_code IS NULL THEN
    RAISE EXCEPTION
      'lab.lab_samples: rejection reason % is not an active reason for this hospital. OP-004 §3.2.3 makes the rejection rate a NABL indicator, and an indicator computed over unresolvable codes is a word cloud.',
      NEW.rejection_reason_key
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  -- Snapshot the code so the master can be retired without rewriting history.
  NEW.rejection_reason_code := v_code;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_lab_samples_rejection_reason ON lab.lab_samples;
CREATE TRIGGER trg_lab_samples_rejection_reason
  BEFORE INSERT OR UPDATE OF rejection_reason_key ON lab.lab_samples
  FOR EACH ROW EXECUTE FUNCTION lab.enforce_rejection_reason();

-- Custody: an aliquot inherits chain of custody from its parent, and a
-- chain-of-custody specimen keeps a contiguous, numbered hand-over log.
ALTER TABLE lab.lab_sample_custody_events
  ADD CONSTRAINT lab_sample_custody_events_sequence_positive CHECK (sequence >= 1);
ALTER TABLE lab.lab_sample_custody_events
  ADD CONSTRAINT lab_sample_custody_events_handover_named
  CHECK (action <> 'handed_over' OR (to_name IS NOT NULL OR to_user_id IS NOT NULL));

ALTER TABLE lab.lab_sample_labels
  ADD CONSTRAINT lab_sample_labels_reprint_reason
  CHECK (is_reprint = false OR reprint_reason IS NOT NULL);
ALTER TABLE lab.lab_sample_labels
  ADD CONSTRAINT lab_sample_labels_copy_positive CHECK (copy_no >= 1);

-- Orders and lines.
ALTER TABLE lab.lab_orders
  ADD CONSTRAINT lab_orders_accession_present CHECK (length(btrim(accession_no)) > 0);
ALTER TABLE lab.lab_orders
  ADD CONSTRAINT lab_orders_cancel_reason
  CHECK (status <> 'cancelled' OR cancel_reason IS NOT NULL);
ALTER TABLE lab.lab_orders
  ADD CONSTRAINT lab_orders_cancel_pairing
  CHECK ((status = 'cancelled') = (cancelled_at IS NOT NULL));
-- An order is for a visit, an admission, an ER attendance — or it is a walk-in,
-- which OP-004 §3.1.1 describes as a real workflow with its own lab-only visit.
ALTER TABLE lab.lab_orders
  ADD CONSTRAINT lab_orders_episode
  CHECK (
    visit_id IS NOT NULL OR admission_id IS NOT NULL OR er_visit_id IS NOT NULL
    OR source IN ('walkin', 'referred_in', 'camp', 'home_collection')
  );
-- A medico-legal order names the MLC it belongs to.
ALTER TABLE lab.lab_orders
  ADD CONSTRAINT lab_orders_mlc_ref CHECK (is_mlc = false OR mlc_ref IS NOT NULL);

CREATE UNIQUE INDEX IF NOT EXISTS uq_lab_orders_idempotency
  ON lab.lab_orders (hospital_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;

ALTER TABLE lab.lab_order_tests
  ADD CONSTRAINT lab_order_tests_cancel_reason
  CHECK (status <> 'cancelled' OR cancel_reason IS NOT NULL);
-- A reflex test came from a parent; a parent-less reflex is an orphan nobody
-- ordered, which `OP-004 §3.3.4` would bill to somebody.
ALTER TABLE lab.lab_order_tests
  ADD CONSTRAINT lab_order_tests_reflex_parent
  CHECK (is_reflex = false OR parent_order_test_id IS NOT NULL);
ALTER TABLE lab.lab_order_tests
  ADD CONSTRAINT lab_order_tests_parent_not_self
  CHECK (parent_order_test_id IS NULL OR parent_order_test_id <> id);
ALTER TABLE lab.lab_order_tests
  ADD CONSTRAINT lab_order_tests_recollection_not_self
  CHECK (recollection_of_order_test_id IS NULL OR recollection_of_order_test_id <> id);
-- `OP-004 §5`: "sample rejection triggers recollection order at zero charge".
-- A recollection line that is chargeable is the hospital billing a patient for
-- its own pre-analytical failure.
ALTER TABLE lab.lab_order_tests
  ADD CONSTRAINT lab_order_tests_recollection_free
  CHECK (recollection_of_order_test_id IS NULL OR is_chargeable = false);
ALTER TABLE lab.lab_order_tests
  ADD CONSTRAINT lab_order_tests_outsource_partner
  CHECK (is_outsourced = false OR referral_lab_id IS NOT NULL);

-- The pending-work and SLA-breach worklists, both of which are opened every few
-- seconds on a bench screen.
CREATE INDEX IF NOT EXISTS idx_lab_order_tests_pending
  ON lab.lab_order_tests (hospital_id, discipline, tat_due_at)
  WHERE status IN ('pending', 'collected', 'received', 'in_progress');
CREATE INDEX IF NOT EXISTS idx_lab_order_tests_awaiting_release
  ON lab.lab_order_tests (hospital_id, discipline, resulted_at)
  WHERE status IN ('resulted', 'verified');

ALTER TABLE lab.lab_transport_batches
  ADD CONSTRAINT lab_transport_batches_time_order
  CHECK (dispatched_at IS NULL OR received_at IS NULL OR received_at >= dispatched_at);
ALTER TABLE lab.lab_transport_batches
  ADD CONSTRAINT lab_transport_batches_count_non_negative CHECK (sample_count >= 0);

ALTER TABLE lab.lab_rejection_reasons
  ADD CONSTRAINT lab_rejection_reasons_label_present CHECK (length(btrim(label)) > 0);
ALTER TABLE lab.lab_tat_targets
  ADD CONSTRAINT lab_tat_targets_positive CHECK (target_minutes > 0);
ALTER TABLE lab.lab_tat_targets
  ADD CONSTRAINT lab_tat_targets_warn_range CHECK (warn_at_percent BETWEEN 1 AND 100);
ALTER TABLE lab.lab_tat_targets
  ADD CONSTRAINT lab_tat_targets_scope
  CHECK (test_key IS NOT NULL OR discipline IS NOT NULL);
ALTER TABLE lab.lab_referral_labs
  ADD CONSTRAINT lab_referral_labs_tat_positive
  CHECK (default_tat_hours IS NULL OR default_tat_hours > 0);
ALTER TABLE lab.lab_outsource_dispatches
  ADD CONSTRAINT lab_outsource_dispatches_status
  CHECK (status IN ('draft', 'dispatched', 'acknowledged', 'partially_received', 'received', 'cancelled'));
ALTER TABLE lab.lab_outsource_dispatches
  ADD CONSTRAINT lab_outsource_dispatches_cost_non_negative
  CHECK (partner_cost IS NULL OR partner_cost >= 0);
ALTER TABLE lab.lab_collection_rounds
  ADD CONSTRAINT lab_collection_rounds_status
  CHECK (status IN ('planned', 'in_progress', 'completed', 'abandoned'));
ALTER TABLE lab.lab_collection_rounds
  ADD CONSTRAINT lab_collection_rounds_counts_non_negative
  CHECK (stop_count >= 0 AND collected_count >= 0);


-- ── C.4 the QC release gate: `never_evaluated` is not `passed` ──────────────
--
-- `docs/prompts/phase-03 §Non-negotiables 3`: "Westgard violations block release
-- (exit gate 4). A QC state that permits release must be distinguishable from
-- one that has never been evaluated — the same class of defect as Phase 1's
-- allergy statement. `unknown` is not `passed`."
--
-- That defect class has now appeared three times in this repository. Phase 1:
-- zero allergy rows meant *nobody asked*, *asked and could not establish* and
-- *asked, there are none*, and the code read all three as "no allergies". Phase
-- 2: a null dosing weight had to be distinguishable from a weight of zero, so
-- `dosing_weight_source` got four arms and a default of `unknown`. Here the
-- question is "may this analyte's results be released?", and the three answers
-- that must never collapse into one are *QC passed*, *QC failed* and *no QC has
-- ever run*.
--
-- Three mechanisms:
--
--   1. `lab."LabQcState"` has no value meaning "unknown but probably fine", and
--      its DEFAULT is `never_evaluated`, so an analyte × instrument pairing
--      nobody configured fails closed.
--   2. `lab.qc_permits_release()` is the single place that decides, and it is
--      written as an explicit whitelist rather than a blacklist: a seventh state
--      added by a future phase is refused until somebody classifies it.
--   3. The migration asserts, here, at migration time, that the function
--      answers `false` for `never_evaluated` and for every other non-releasing
--      state — the same shape of assertion as the Phase-2 `cdss_safety_floor`
--      guard, and for the same reason: a test somebody can mark `skip` is a
--      weaker guarantee than a migration that will not apply.

CREATE OR REPLACE FUNCTION lab.qc_permits_release(p_state lab."LabQcState")
RETURNS boolean
LANGUAGE sql
IMMUTABLE
AS $$
  -- A whitelist, deliberately. `in_control` is QC that ran and passed.
  -- `warning` is QC that ran and fired a warning-action rule — EN-031 §5 is
  -- explicit that treating 1-2s as a rejection is the classic false-rejection
  -- error, so a warning flags the run and does not stop the laboratory.
  --
  -- Everything else is false, including `never_evaluated`, which is the arm this
  -- whole function exists for: no QC has run, so there is no evidence the
  -- instrument is measuring anything correctly, and "we have no information" is
  -- not "it is fine".
  SELECT p_state IN ('in_control', 'warning');
$$;

COMMENT ON FUNCTION lab.qc_permits_release IS
  'The single place that decides whether an analyte''s QC state permits releasing patient results. A whitelist, so a state added later is refused until it is classified. `never_evaluated` is false — docs/prompts/phase-03 §Non-negotiables 3: "unknown is not passed".';

GRANT EXECUTE ON FUNCTION lab.qc_permits_release(lab."LabQcState") TO hms_app, hms_readonly;

-- The state for an analyte, taking the **most restrictive** row when several
-- instruments run it, and `never_evaluated` when there is no row at all. There is
-- no reading of this function under which absence of information becomes
-- permission.
CREATE OR REPLACE FUNCTION lab.qc_state_for(
  p_hospital_id   uuid,
  p_instrument_id uuid,
  p_test_key      uuid,
  p_parameter_key uuid
) RETURNS lab."LabQcState"
LANGUAGE sql
STABLE
AS $$
  SELECT COALESCE(
    (
      SELECT s.state
      FROM lab.labq_analyte_qc_state s
      WHERE s.hospital_id = p_hospital_id
        AND s.test_key = p_test_key
        AND s.parameter_key IS NOT DISTINCT FROM p_parameter_key
        AND (p_instrument_id IS NULL OR s.instrument_id = p_instrument_id)
      ORDER BY
        -- Worst first. A single out-of-control instrument stops the analyte.
        CASE s.state
          WHEN 'suspended'       THEN 0
          WHEN 'out_of_control'  THEN 1
          WHEN 'overdue'         THEN 2
          WHEN 'never_evaluated' THEN 3
          WHEN 'warning'         THEN 4
          WHEN 'in_control'      THEN 5
        END
      LIMIT 1
    ),
    'never_evaluated'::lab."LabQcState"
  );
$$;

COMMENT ON FUNCTION lab.qc_state_for IS
  'The QC state governing an analyte, worst-first across instruments, and `never_evaluated` when no row exists. Absence of a row means exactly what an explicit `never_evaluated` means: no QC has run. Returning NULL here would let a caller''s COALESCE decide, which is how "unknown" becomes "passed".';

GRANT EXECUTE ON FUNCTION lab.qc_state_for(uuid, uuid, uuid, uuid) TO hms_app, hms_readonly;

-- Whether the gate applies at all. It does whenever the result came off an
-- instrument, and also whenever the laboratory has declared the analyte to be
-- under QC by giving it an active schedule — which closes the hole a purely
-- instrument-keyed gate would leave for a manual bench analyte that is
-- nonetheless controlled. It does not apply to histopathology sign-out or a
-- microbiology narrative, which have no control material to run.
CREATE OR REPLACE FUNCTION lab.qc_gate_applies(
  p_hospital_id   uuid,
  p_instrument_id uuid,
  p_test_key      uuid,
  p_parameter_key uuid
) RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT p_instrument_id IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM lab.labq_qc_schedules s
       WHERE s.hospital_id = p_hospital_id
         AND s.test_key = p_test_key
         AND s.parameter_key IS NOT DISTINCT FROM p_parameter_key
         AND s.is_active
     );
$$;

GRANT EXECUTE ON FUNCTION lab.qc_gate_applies(uuid, uuid, uuid, uuid) TO hms_app, hms_readonly;

-- **The assertion.** If a later phase adds a state and forgets to classify it,
-- or "fixes" `qc_permits_release` to be permissive, this migration is the last
-- thing that will have been true and the next one fails here.
DO $$
DECLARE
  v_state    text;
  v_expected boolean;
  v_actual   boolean;
  v_missing  text;
BEGIN
  -- 1. Every enum label must have a decided answer, and the answers must be
  --    these. `never_evaluated` first, because it is the one that matters.
  FOR v_state, v_expected IN
    SELECT * FROM (VALUES
      ('never_evaluated', false),
      ('out_of_control',  false),
      ('overdue',         false),
      ('suspended',       false),
      ('in_control',      true),
      ('warning',         true)
    ) AS t(s, e)
  LOOP
    EXECUTE format('SELECT lab.qc_permits_release(%L::lab."LabQcState")', v_state) INTO v_actual;
    IF v_actual IS DISTINCT FROM v_expected THEN
      RAISE EXCEPTION
        'lab.qc_permits_release(%) returns % but must return %. docs/prompts/phase-03 §Non-negotiables 3: a QC state that permits release must be distinguishable from one that has never been evaluated — "unknown" is not "passed". Changing this is a clinical-safety change, not a refactor.',
        v_state, v_actual, v_expected;
    END IF;
  END LOOP;

  -- 2. And no label may exist that the list above does not name, because an
  --    unclassified state is exactly the ambiguity this guards against.
  SELECT string_agg(e.enumlabel, ', ' ORDER BY e.enumlabel)
  INTO v_missing
  FROM pg_enum e
  JOIN pg_type t ON t.oid = e.enumtypid
  JOIN pg_namespace n ON n.oid = t.typnamespace
  WHERE n.nspname = 'lab' AND t.typname = 'LabQcState'
    AND e.enumlabel NOT IN ('never_evaluated', 'out_of_control', 'overdue', 'suspended', 'in_control', 'warning');

  IF v_missing IS NOT NULL THEN
    RAISE EXCEPTION
      'lab."LabQcState" has gained the value(s) % which nothing classifies as releasing or not. Add them to lab.qc_permits_release() AND to this assertion, in the same migration, reviewed as a clinical-safety change.',
      v_missing;
  END IF;

  -- 3. The column default must be the closed arm. A default of `in_control`
  --    would make every unconfigured pairing releasable and no test would fail.
  IF (
    SELECT column_default FROM information_schema.columns
    WHERE table_schema = 'lab' AND table_name = 'labq_analyte_qc_state' AND column_name = 'state'
  ) NOT LIKE '%never_evaluated%' THEN
    RAISE EXCEPTION
      'lab.labq_analyte_qc_state.state no longer defaults to never_evaluated. The default IS the guarantee: an analyte nobody configured must fail closed.';
  END IF;
END
$$;

-- `never_evaluated` and "we know when it was last looked at" are the same fact,
-- in both directions. A state claiming to have been evaluated with no timestamp
-- would sail past any staleness check; a timestamp on `never_evaluated` would
-- sail past any check written against the state.
ALTER TABLE lab.labq_analyte_qc_state
  ADD CONSTRAINT labq_analyte_qc_state_evaluated_pairing
  CHECK ((state = 'never_evaluated') = (last_evaluated_at IS NULL));
ALTER TABLE lab.labq_analyte_qc_state
  ADD CONSTRAINT labq_analyte_qc_state_blocked_reason
  CHECK (lab.qc_permits_release(state) OR state = 'never_evaluated' OR reason IS NOT NULL);
ALTER TABLE lab.labq_analyte_qc_state
  ADD CONSTRAINT labq_analyte_qc_state_held_non_negative CHECK (held_result_count >= 0);

-- Uniqueness with NULLS NOT DISTINCT: `parameter_key` is null for a
-- single-analyte test, and PostgreSQL treats NULLs as distinct in a plain unique
-- index — so without this a second "no parameter" row could exist and "which
-- state gates this analyte" would depend on row order.
CREATE UNIQUE INDEX IF NOT EXISTS uq_labq_analyte_qc_state_key
  ON lab.labq_analyte_qc_state (hospital_id, instrument_id, test_key, parameter_key) NULLS NOT DISTINCT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_labq_qc_schedules_key
  ON lab.labq_qc_schedules (hospital_id, instrument_id, test_key, parameter_key) NULLS NOT DISTINCT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_labq_eqa_results_key
  ON lab.labq_eqa_results (cycle_id, test_key, parameter_key) NULLS NOT DISTINCT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_labq_scope_tests_key
  ON lab.labq_scope_tests (accreditation_id, test_key, parameter_key) NULLS NOT DISTINCT;

-- The blocked-analyte dashboard: which analytes cannot release right now.
CREATE INDEX IF NOT EXISTS idx_labq_analyte_qc_state_blocked
  ON lab.labq_analyte_qc_state (hospital_id, branch_id, state)
  WHERE state IN ('never_evaluated', 'out_of_control', 'overdue', 'suspended');

-- ── Westgard configuration ───────────────────────────────────────────────────
-- `EN-031 §5`: "**`1-2s` is a warning, never a rejection** (using it as a
-- rejection rule is a classic false-rejection error)". At two standard
-- deviations roughly one run in twenty fails by chance; a laboratory that
-- repeats one run in twenty stops believing its own QC, which is a worse outcome
-- than the false rejections themselves. The rule is not a default here, it is a
-- constraint.
ALTER TABLE lab.labq_westgard_config
  ADD CONSTRAINT labq_westgard_config_1_2s_is_warning
  CHECK (rule_code <> 'r_1_2s' OR action = 'warning');
ALTER TABLE lab.labq_westgard_config
  ADD CONSTRAINT labq_westgard_config_n_positive
  CHECK ((n IS NULL OR n > 0) AND (r IS NULL OR r > 0));
ALTER TABLE lab.labq_westgard_config
  ADD CONSTRAINT labq_westgard_config_effective_order
  CHECK (effective_to IS NULL OR effective_to > effective_from);
ALTER TABLE lab.labq_westgard_config
  ADD CONSTRAINT labq_westgard_config_tea_positive
  CHECK (tea_percent IS NULL OR tea_percent > 0);

-- ── QC runs ──────────────────────────────────────────────────────────────────
-- `EN-031 §5`: "QC results cannot be deleted; a mistaken entry is voided with a
-- reason and remains visible on the chart as a voided point." Voiding is
-- therefore a state with attribution, and §D revokes DELETE so it is the only
-- way out.
ALTER TABLE lab.labq_qc_runs
  ADD CONSTRAINT labq_qc_runs_void_attributed
  CHECK ((status = 'void') = (voided_at IS NOT NULL));
ALTER TABLE lab.labq_qc_runs
  ADD CONSTRAINT labq_qc_runs_void_reason
  CHECK (voided_at IS NULL OR (voided_by IS NOT NULL AND void_reason IS NOT NULL));
-- `has_rejection` is what the release gate and the dashboards read, so it must
-- agree with the status it summarises rather than drifting from it.
ALTER TABLE lab.labq_qc_runs
  ADD CONSTRAINT labq_qc_runs_rejection_agrees
  CHECK (has_rejection = (status = 'out_of_control'));
-- A violated-rules list with no violation, or a violation with no rules, is a
-- Levey-Jennings point nobody can explain.
ALTER TABLE lab.labq_qc_runs
  ADD CONSTRAINT labq_qc_runs_violations_agree
  CHECK (
    (status IN ('in_control', 'void') AND cardinality(violated_rules) = 0)
    OR (status IN ('warning', 'out_of_control') AND cardinality(violated_rules) > 0)
  );
ALTER TABLE lab.labq_qc_runs
  ADD CONSTRAINT labq_qc_runs_sd_positive
  CHECK (target_sd IS NULL OR target_sd > 0);

-- ── lockouts ─────────────────────────────────────────────────────────────────
-- `EN-004 §5`: "unlock only after passing QC and corrective action note". Three
-- things at once — a person, a passing run and a documented action. Two of the
-- three is how a lockout gets cleared by clicking.
ALTER TABLE lab.labq_qc_lockouts
  ADD CONSTRAINT labq_qc_lockouts_unlock_evidence
  CHECK (
    unlocked_at IS NULL
    OR (unlocked_by IS NOT NULL AND unlock_qc_run_id IS NOT NULL AND corrective_action_id IS NOT NULL)
  );
ALTER TABLE lab.labq_qc_lockouts
  ADD CONSTRAINT labq_qc_lockouts_time_order
  CHECK (unlocked_at IS NULL OR unlocked_at >= locked_at);
ALTER TABLE lab.labq_qc_lockouts
  ADD CONSTRAINT labq_qc_lockouts_held_non_negative CHECK (held_result_count >= 0);

CREATE INDEX IF NOT EXISTS idx_labq_qc_lockouts_open
  ON lab.labq_qc_lockouts (hospital_id, branch_id, locked_at DESC)
  WHERE unlocked_at IS NULL;

-- ── the one lawful route around the gate ─────────────────────────────────────
-- `EN-031 §5`: "The only exception is an explicit Director authorisation
-- recorded in `labq_qc_actions` with `patient_impact = released_with_authorisation`
-- and a reason — this is audited and reported monthly." So the exception exists,
-- it is narrow, and it cannot be recorded without both the authoriser and the
-- reason.
ALTER TABLE lab.labq_qc_actions
  ADD CONSTRAINT labq_qc_actions_patient_impact
  CHECK (patient_impact IN ('none', 'retest_all', 'retest_selected', 'released_with_authorisation'));
ALTER TABLE lab.labq_qc_actions
  ADD CONSTRAINT labq_qc_actions_release_authorised
  CHECK (
    patient_impact <> 'released_with_authorisation'
    OR (authorised_by IS NOT NULL AND authorised_at IS NOT NULL AND authorisation_reason IS NOT NULL)
  );
ALTER TABLE lab.labq_qc_actions
  ADD CONSTRAINT labq_qc_actions_cause_present
  CHECK (length(btrim(cause_code)) > 0 AND length(btrim(action_code)) > 0);
ALTER TABLE lab.labq_qc_actions
  ADD CONSTRAINT labq_qc_actions_affected_non_negative CHECK (affected_result_count >= 0);
ALTER TABLE lab.labq_qc_actions
  ADD CONSTRAINT labq_qc_actions_subject
  CHECK (qc_run_id IS NOT NULL OR lockout_id IS NOT NULL);

-- ── the rest of the quality estate ───────────────────────────────────────────
ALTER TABLE lab.labq_qc_materials
  ADD CONSTRAINT labq_qc_materials_status
  CHECK (status IN ('active', 'quarantine', 'expired', 'exhausted'));
-- A control opened after it expired is not a control.
ALTER TABLE lab.labq_qc_materials
  ADD CONSTRAINT labq_qc_materials_open_before_expiry
  CHECK (opened_on IS NULL OR opened_on <= expiry_date);
ALTER TABLE lab.labq_qc_materials
  ADD CONSTRAINT labq_qc_materials_parallel_non_negative CHECK (parallel_runs_completed >= 0);
-- `EN-031 §5`: "Lot changeover requires parallel testing (≥10 paired runs) with a
-- documented comparison before the new lot becomes active."
ALTER TABLE lab.labq_qc_materials
  ADD CONSTRAINT labq_qc_materials_lot_changeover
  CHECK (
    replaces_material_id IS NULL
    OR status <> 'active'
    OR (parallel_runs_completed >= 10 AND parallel_comparison_file_id IS NOT NULL)
  );

ALTER TABLE lab.labq_qc_targets
  ADD CONSTRAINT labq_qc_targets_source
  CHECK (source IN ('insert', 'lab_derived', 'peer_group'));
ALTER TABLE lab.labq_qc_targets
  ADD CONSTRAINT labq_qc_targets_sd_positive CHECK (sd > 0);
-- `EN-031 §5`: "laboratory-derived mean/SD from ≥20 runs over ≥20 days must
-- replace them and require Director approval".
ALTER TABLE lab.labq_qc_targets
  ADD CONSTRAINT labq_qc_targets_lab_derived_evidence
  CHECK (source <> 'lab_derived' OR (n_runs IS NOT NULL AND n_runs >= 20 AND approved_by IS NOT NULL));
ALTER TABLE lab.labq_qc_targets
  ADD CONSTRAINT labq_qc_targets_effective_order
  CHECK (effective_to IS NULL OR effective_to > effective_from);
ALTER TABLE lab.labq_qc_targets
  ADD CONSTRAINT labq_qc_targets_approval_pairing
  CHECK ((approved_by IS NULL) = (approved_at IS NULL));

ALTER TABLE lab.labq_qc_schedules
  ADD CONSTRAINT labq_qc_schedules_frequency
  CHECK (frequency IN ('per_shift', 'per_run', 'every_n_samples', 'daily', 'after_calibration', 'after_maintenance'));
ALTER TABLE lab.labq_qc_schedules
  ADD CONSTRAINT labq_qc_schedules_n_samples
  CHECK (frequency <> 'every_n_samples' OR (n_samples IS NOT NULL AND n_samples > 0));
ALTER TABLE lab.labq_qc_schedules
  ADD CONSTRAINT labq_qc_schedules_levels_positive CHECK (levels >= 1);
ALTER TABLE lab.labq_qc_schedules
  ADD CONSTRAINT labq_qc_schedules_grace_non_negative CHECK (grace_minutes >= 0);

ALTER TABLE lab.labq_eqa_cycles
  ADD CONSTRAINT labq_eqa_cycles_status
  CHECK (status IN ('pending', 'tested', 'submitted', 'reported', 'missed'));
ALTER TABLE lab.labq_eqa_results
  ADD CONSTRAINT labq_eqa_results_performance
  CHECK (performance IS NULL OR performance IN ('satisfactory', 'questionable', 'unsatisfactory'));
-- `EN-031 §5`: "Unsatisfactory EQA (|Z|>3) … force a non-conformity with root
-- cause, CAPA and effectiveness verification." Until NC-015 exists the CAPA is a
-- reference, but an unsatisfactory result with no reference at all is a finding
-- nobody owns.
ALTER TABLE lab.labq_eqa_results
  ADD CONSTRAINT labq_eqa_results_suspension_attributed
  CHECK (suspended_from_reporting = false OR (suspended_by IS NOT NULL AND suspended_at IS NOT NULL));

ALTER TABLE lab.labq_calibrations
  ADD CONSTRAINT labq_calibrations_result CHECK (result IN ('pass', 'fail'));
ALTER TABLE lab.labq_calibrations
  ADD CONSTRAINT labq_calibrations_next_due_forward
  CHECK (next_due_at IS NULL OR next_due_at > calibrated_at);
-- A calibrator used past its expiry invalidates the calibration.
ALTER TABLE lab.labq_calibrations
  ADD CONSTRAINT labq_calibrations_calibrator_in_date
  CHECK (calibrator_expiry IS NULL OR calibrated_at::date <= calibrator_expiry);

ALTER TABLE lab.labq_competencies
  ADD CONSTRAINT labq_competencies_element
  CHECK (element IN ('training', 'direct_observation', 'result_monitoring', 'blind_sample', 'problem_solving', 'maintenance_troubleshooting'));
ALTER TABLE lab.labq_competencies
  ADD CONSTRAINT labq_competencies_outcome
  CHECK (outcome IN ('competent', 'needs_retraining'));
-- An authorisation is granted only on a competent assessment, and it expires.
ALTER TABLE lab.labq_competencies
  ADD CONSTRAINT labq_competencies_authorisation_requires_competence
  CHECK (authorised = false OR (outcome = 'competent' AND valid_until IS NOT NULL));
ALTER TABLE lab.labq_competencies
  ADD CONSTRAINT labq_competencies_scope
  CHECK (test_key IS NOT NULL OR discipline IS NOT NULL);

ALTER TABLE lab.labq_method_validations
  ADD CONSTRAINT labq_method_validations_type
  CHECK (type IN ('validation', 'verification', 'revalidation'));
ALTER TABLE lab.labq_method_validations
  ADD CONSTRAINT labq_method_validations_status
  CHECK (status IN ('draft', 'in_progress', 'completed', 'approved', 'rejected'));
ALTER TABLE lab.labq_method_validations
  ADD CONSTRAINT labq_method_validations_approval_pairing
  CHECK ((approved_by IS NULL) = (approved_at IS NULL));
ALTER TABLE lab.labq_method_validations
  ADD CONSTRAINT labq_method_validations_approved_evidence
  CHECK (status <> 'approved' OR (approved_by IS NOT NULL AND report_file_id IS NOT NULL));
-- `EN-031 §5`: uncertainty is expanded from the standard uncertainty by a
-- coverage factor; one without the others is a number with no interpretation.
ALTER TABLE lab.labq_method_validations
  ADD CONSTRAINT labq_method_validations_uncertainty_complete
  CHECK (
    uncertainty_u IS NULL
    OR (uncertainty_k IS NOT NULL AND uncertainty_expanded IS NOT NULL AND uncertainty_computed_at IS NOT NULL)
  );

ALTER TABLE lab.labq_accreditation
  ADD CONSTRAINT labq_accreditation_body CHECK (body IN ('nabl', 'cap', 'jci_lab', 'other'));
ALTER TABLE lab.labq_accreditation
  ADD CONSTRAINT labq_accreditation_validity_order CHECK (valid_to > valid_from);
ALTER TABLE lab.labq_scope_tests
  ADD CONSTRAINT labq_scope_tests_removal_order
  CHECK (removed_on IS NULL OR added_on IS NULL OR removed_on >= added_on);
ALTER TABLE lab.labq_scope_tests
  ADD CONSTRAINT labq_scope_tests_in_scope_pairing
  CHECK (in_scope = (removed_on IS NULL));


-- ── C.5 the append-only, typed, hash-chained result ─────────────────────────
--
-- `docs/prompts/phase-03 §Non-negotiables 5`: "Results are append-only and
-- versioned. An amended result creates a new version with a reason; the original
-- stays. Follow the `clinical.documents`/`document_versions` pattern Phase 2
-- established."
--
-- The same four mechanisms as `clinical.document_versions`, because each closes
-- a different hole:
--
--   1. The digest is computed by the database from the measured value, so a
--      caller cannot present one that does not describe what it stored.
--   2. `prev_sha256` is taken from the actual preceding version, so the chain
--      cannot be re-linked to hide a removed one.
--   3. A trigger refuses any UPDATE that would change the *value* — ever, not
--      merely after signing — and refuses every DELETE.
--   4. §D revokes DELETE from `hms_app`, so a bug that bypassed the trigger has
--      nothing left to bypass it with.
--
-- ── Where this differs from a clinical document, and why ────────────────────
--
-- A note is drafted and then signed, so `document_versions` lets a draft change
-- freely and freezes at `final`. A laboratory result is different: the number
-- exists the moment the analyser produces it, and the two-level release
-- (`OP-004 §3.4`) stamps *the same row* as it is technically verified and then
-- medically authorised. So the immutability line is drawn around the measurement
-- rather than around a status:
--
--   * the value, its unit, its flag, the reference interval it was read against,
--     the instrument, the run and the raw message are frozen from INSERT;
--   * the review trail (status, verified_by/at, authorised_by/at, the signature,
--     the supersession stamp) moves forward and is write-once per field;
--   * an amendment is a new version with a reason, exactly as the prompt says.
--
-- The digest covers only the frozen half, so stamping a verification does not
-- invalidate the chain — which is what makes the chain verifiable at all.

-- ── the typed value ──────────────────────────────────────────────────────────
-- `docs/prompts/phase-03 §Constraints`: "Result values are typed (numeric with
-- units, coded, text) — do not store everything as strings." A numeric potassium
-- stored as the text "6.8" cannot be compared against a critical bound, and a
-- critical bound that cannot fire is the defect this phase exists to prevent.
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_value_typed
  CHECK (
    CASE result_type
      WHEN 'numeric'           THEN value_numeric IS NOT NULL
      WHEN 'semi_quantitative' THEN value_numeric IS NOT NULL OR value_coded IS NOT NULL
      WHEN 'calculated'        THEN value_numeric IS NOT NULL
      WHEN 'qualitative'       THEN value_coded IS NOT NULL
      WHEN 'coded'             THEN value_coded IS NOT NULL
      WHEN 'multiselect'       THEN cardinality(value_multi) > 0
      WHEN 'text'              THEN value_text IS NOT NULL
      WHEN 'microbiology'      THEN true
      WHEN 'histopathology'    THEN true
    END
    -- A cancelled version carries no value: the measurement was withdrawn.
    OR status = 'cancelled'
  );
-- A numeric result has a unit unless it is genuinely dimensionless (a ratio, an
-- index, an INR). Expressed as "a numeric value and a unit travel together
-- unless the test master says otherwise", which the service enforces; what the
-- database refuses is the impossible combination of a unit with no number.
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_unit_needs_value
  CHECK (unit IS NULL OR value_numeric IS NOT NULL);
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_operator_shape
  CHECK (value_operator IS NULL OR value_operator IN ('<', '>', '<=', '>=', '~'));
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_operator_needs_value
  CHECK (value_operator IS NULL OR value_numeric IS NOT NULL);
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_dilution_positive
  CHECK (dilution_factor IS NULL OR dilution_factor > 0);

-- **`is_critical` must agree with `flag`.** The boolean is what the partial index
-- and the auto-raise trigger read; the enum is what the report prints. A boolean
-- that has to agree with an enum is a boolean that eventually does not — unless a
-- CHECK makes disagreement unstorable.
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_critical_agrees
  CHECK (is_critical = (flag IN ('critical_low', 'critical_high')));

-- The reference interval is ordered, and a critical bound sits outside the
-- normal one. An inverted pair silently flags every result, which trains a
-- technician to ignore the colour — the same failure `clinical.vitals_reference_ranges`
-- guards against.
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_ref_order
  CHECK (
    (ref_low IS NULL OR ref_high IS NULL OR ref_low <= ref_high)
    AND (ref_critical_low IS NULL OR ref_low IS NULL OR ref_critical_low <= ref_low)
    AND (ref_critical_high IS NULL OR ref_high IS NULL OR ref_critical_high >= ref_high)
  );

ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_version_positive CHECK (version >= 1);
-- An amendment with no reason is an overwrite wearing a version number.
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_amendment_reason
  CHECK (version = 1 OR amendment_reason IS NOT NULL);
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_chain_root
  CHECK ((version = 1) = (prev_sha256 IS NULL));
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_sha_shape
  CHECK (content_sha256 ~ '^[0-9a-f]{64}$');
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_cancel_reason
  CHECK (status <> 'cancelled' OR cancelled_reason IS NOT NULL);
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_superseded_pairing
  CHECK ((superseded_by_version IS NULL) = (superseded_at IS NULL));
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_superseded_forward
  CHECK (superseded_by_version IS NULL OR superseded_by_version > version);
-- The two-level release: each level is attributed, and authorisation implies
-- verification happened. `OP-004 §3.4`.
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_verify_pairing
  CHECK ((verified_by IS NULL) = (verified_at IS NULL));
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_authorise_pairing
  CHECK ((authorised_by IS NULL) = (authorised_at IS NULL));
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_status_evidence
  CHECK (
    (status <> 'verified'   OR verified_by IS NOT NULL)
    AND (status <> 'authorised' OR (authorised_by IS NOT NULL AND verified_by IS NOT NULL))
  );
-- `OP-004 §5`: "enterer ≠ verifier for manual results (segregation of duty)".
-- Only for manual entry: an analyzer is not a person and cannot be the same
-- person as the verifier.
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_segregation_of_duty
  CHECK (
    source <> 'manual'
    OR verified_by IS NULL
    OR entered_by IS NULL
    OR verified_by <> entered_by
  );
-- A rerun names what it is a rerun of, and why (`OP-004 §3.3.3`).
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_rerun_evidence
  CHECK (is_rerun = false OR (rerun_reason IS NOT NULL AND rerun_of_version IS NOT NULL));
-- An auto-verified result names the signed rule-set version that verified it —
-- `EN-004 §5`: "every auto decision recorded (NABL traceability)".
ALTER TABLE lab.lab_result_versions
  ADD CONSTRAINT lab_result_versions_autoval_traceable
  CHECK ((autoval_decision_id IS NULL) = (autoval_ruleset_version IS NULL));

ALTER TABLE lab.lab_results
  ADD CONSTRAINT lab_results_current_version_non_negative CHECK (current_version >= 0);
ALTER TABLE lab.lab_results
  ADD CONSTRAINT lab_results_analyte_name_present CHECK (length(btrim(analyte_name)) > 0);

-- ── the sealer ───────────────────────────────────────────────────────────────
-- Computes the digest over the *measured* half of the row, links the chain, and
-- refuses a version that claims a predecessor it does not have, a duplicate
-- version number, or a parent result that does not exist.
--
-- `lab.lab_results` is partitioned, so `result_id` cannot be a declared foreign
-- key (a foreign key would have to carry the parent's partition key, and an
-- amendment written in March to a result created in January would then have to
-- store January's timestamp in a March-partitioned row). This is where that
-- integrity is enforced instead — and the same applies to the "one version
-- number per result" uniqueness, which a partitioned unique index cannot express
-- because it must include `recorded_at`.
CREATE OR REPLACE FUNCTION lab.seal_result_version()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_parent_exists boolean;
  v_prev_hash     text;
  v_prev_found    boolean;
  v_max_version   int;
BEGIN
  -- 1. The parent must exist. An orphan result version is a measured value
  --    attached to nothing, which is worse than no value at all.
  SELECT true INTO v_parent_exists
  FROM lab.lab_results r
  WHERE r.id = NEW.result_id
  LIMIT 1;

  IF NOT COALESCE(v_parent_exists, false) THEN
    RAISE EXCEPTION
      'lab.lab_result_versions: result % does not exist. lab.lab_results is partitioned, so this is a trigger rather than a foreign key — the integrity requirement is identical.',
      NEW.result_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  -- 2. The digest is ours, not the caller's, and it covers only what can never
  --    change: the measurement and its interpretation. Stamping a verification
  --    later must not invalidate the chain, or the chain becomes unverifiable
  --    and therefore worthless.
  NEW.content_sha256 := encode(
    sha256(convert_to(
      jsonb_build_object(
        'result_id',        NEW.result_id,
        'version',          NEW.version,
        'result_type',      NEW.result_type::text,
        'value_numeric',    NEW.value_numeric,
        'value_coded',      NEW.value_coded,
        'value_multi',      to_jsonb(NEW.value_multi),
        'value_text',       NEW.value_text,
        'value_operator',   NEW.value_operator,
        'unit',             NEW.unit,
        'flag',             NEW.flag::text,
        'ref_low',          NEW.ref_low,
        'ref_high',         NEW.ref_high,
        'ref_critical_low', NEW.ref_critical_low,
        'ref_critical_high',NEW.ref_critical_high,
        'dilution_factor',  NEW.dilution_factor,
        'instrument_id',    NEW.instrument_id,
        'run_id',           NEW.run_id,
        'raw_message_id',   NEW.raw_message_id,
        'amendment_reason', NEW.amendment_reason
      )::text, 'UTF8')),
    'hex');

  IF TG_OP = 'INSERT' THEN
    -- 3. Versions are contiguous and unique per result. A partitioned unique
    --    index must contain `recorded_at`, which would permit a second version 3
    --    a millisecond later — precisely the duplicate it was meant to stop.
    SELECT max(version) INTO v_max_version
    FROM lab.lab_result_versions
    WHERE result_id = NEW.result_id;

    IF NEW.version <> COALESCE(v_max_version, 0) + 1 THEN
      RAISE EXCEPTION
        'lab.lab_result_versions: result % is at version %, so the next version is % and not %. Versions are contiguous by construction; an amendment is the next number, never a rewrite of an old one.',
        NEW.result_id, COALESCE(v_max_version, 0), COALESCE(v_max_version, 0) + 1, NEW.version
        USING ERRCODE = 'unique_violation';
    END IF;

    IF NEW.version > 1 THEN
      SELECT content_sha256, true
      INTO v_prev_hash, v_prev_found
      FROM lab.lab_result_versions
      WHERE result_id = NEW.result_id AND version = NEW.version - 1;

      IF NOT COALESCE(v_prev_found, false) THEN
        RAISE EXCEPTION
          'lab.lab_result_versions: version % of result % has no version % to chain to',
          NEW.version, NEW.result_id, NEW.version - 1
          USING ERRCODE = 'foreign_key_violation';
      END IF;

      -- 4. The link is ours too. A caller that supplied the wrong predecessor
      --    hash is either confused or detaching a version; the database knows
      --    the right answer and uses it.
      NEW.prev_sha256 := v_prev_hash;
    ELSE
      NEW.prev_sha256 := NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION lab.seal_result_version IS
  'Computes content_sha256 over the measured half of a result version and links prev_sha256 to the preceding version, taking both from the database rather than from the caller. Also enforces the parent-result reference and the contiguous, unique version number, neither of which a partitioned table can express as a constraint.';

DROP TRIGGER IF EXISTS trg_lab_result_versions_seal ON lab.lab_result_versions;
CREATE TRIGGER trg_lab_result_versions_seal
  BEFORE INSERT OR UPDATE ON lab.lab_result_versions
  FOR EACH ROW EXECUTE FUNCTION lab.seal_result_version();

-- ── the immutability guard ───────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION lab.enforce_result_version_immutability()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION
      'lab.lab_result_versions is append-only: version % of result % cannot be deleted. A withdrawal is a status of cancelled with a reason; a correction is a new version.',
      OLD.version, OLD.result_id
      USING ERRCODE = 'restrict_violation';
  END IF;

  -- The measurement is frozen from the moment it is stored — not from the moment
  -- it is signed. A number that changed between entry and authorisation is not a
  -- correction, it is a different measurement, and it deserves its own version.
  IF NEW.value_numeric     IS DISTINCT FROM OLD.value_numeric
     OR NEW.value_coded    IS DISTINCT FROM OLD.value_coded
     OR NEW.value_multi    IS DISTINCT FROM OLD.value_multi
     OR NEW.value_text     IS DISTINCT FROM OLD.value_text
     OR NEW.value_operator IS DISTINCT FROM OLD.value_operator
     OR NEW.unit           IS DISTINCT FROM OLD.unit
     OR NEW.result_type    IS DISTINCT FROM OLD.result_type
     OR NEW.flag           IS DISTINCT FROM OLD.flag
     OR NEW.is_critical    IS DISTINCT FROM OLD.is_critical
     OR NEW.ref_low        IS DISTINCT FROM OLD.ref_low
     OR NEW.ref_high       IS DISTINCT FROM OLD.ref_high
     OR NEW.ref_critical_low  IS DISTINCT FROM OLD.ref_critical_low
     OR NEW.ref_critical_high IS DISTINCT FROM OLD.ref_critical_high
     OR NEW.dilution_factor   IS DISTINCT FROM OLD.dilution_factor
     OR NEW.instrument_id  IS DISTINCT FROM OLD.instrument_id
     OR NEW.run_id         IS DISTINCT FROM OLD.run_id
     OR NEW.raw_message_id IS DISTINCT FROM OLD.raw_message_id
     OR NEW.version        IS DISTINCT FROM OLD.version
     OR NEW.result_id      IS DISTINCT FROM OLD.result_id
     OR NEW.hospital_id    IS DISTINCT FROM OLD.hospital_id
     OR NEW.content_sha256 IS DISTINCT FROM OLD.content_sha256
     OR NEW.prev_sha256    IS DISTINCT FROM OLD.prev_sha256
     OR NEW.amendment_reason IS DISTINCT FROM OLD.amendment_reason
     OR NEW.recorded_at    IS DISTINCT FROM OLD.recorded_at
  THEN
    RAISE EXCEPTION
      'lab.lab_result_versions: version % of result % is immutable. Amend it by writing version % with a reason; the original stays.',
      OLD.version, OLD.result_id, OLD.version + 1
      USING ERRCODE = 'restrict_violation';
  END IF;

  -- The review trail moves forward only. Un-verifying and re-verifying with a
  -- different name is how an audit trail is rewritten one field at a time.
  IF (OLD.verified_by IS NOT NULL AND NEW.verified_by IS DISTINCT FROM OLD.verified_by)
     OR (OLD.verified_at IS NOT NULL AND NEW.verified_at IS DISTINCT FROM OLD.verified_at)
     OR (OLD.authorised_by IS NOT NULL AND NEW.authorised_by IS DISTINCT FROM OLD.authorised_by)
     OR (OLD.authorised_at IS NOT NULL AND NEW.authorised_at IS DISTINCT FROM OLD.authorised_at)
  THEN
    RAISE EXCEPTION
      'lab.lab_result_versions: the verification and authorisation of version % of result % are write-once. Re-releasing a result is a new version.',
      OLD.version, OLD.result_id
      USING ERRCODE = 'restrict_violation';
  END IF;

  -- A released result cannot go back to being unreleased.
  IF OLD.status IN ('authorised', 'amended', 'cancelled')
     AND NEW.status IS DISTINCT FROM OLD.status
     AND NOT (OLD.status = 'authorised' AND NEW.status IN ('amended', 'cancelled'))
  THEN
    RAISE EXCEPTION
      'lab.lab_result_versions: % cannot become % (only authorised → amended and authorised → cancelled are permitted after release)',
      OLD.status, NEW.status
      USING ERRCODE = 'restrict_violation';
  END IF;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION lab.enforce_result_version_immutability IS
  'The measured value is frozen from INSERT, not from signature — a number that changes between entry and authorisation is a different measurement and deserves its own version. The review trail is write-once per field and moves forward only. DELETE is refused unconditionally.';

DROP TRIGGER IF EXISTS trg_lab_result_versions_immutable ON lab.lab_result_versions;
CREATE TRIGGER trg_lab_result_versions_immutable
  BEFORE UPDATE OR DELETE ON lab.lab_result_versions
  FOR EACH ROW EXECUTE FUNCTION lab.enforce_result_version_immutability();

-- ── the head projection ──────────────────────────────────────────────────────
-- `lab.lab_results.current_*` is a projection, and a projection a caller
-- maintains is a projection that drifts. `ever_critical` is set and never
-- cleared: a value that was critical was critical, whatever a later amendment
-- says, and the communication record must stay reachable from the result.
CREATE OR REPLACE FUNCTION lab.sync_result_head()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  UPDATE lab.lab_results r
  SET current_version = head.version,
      current_status  = head.status,
      current_flag    = head.flag,
      ever_critical   = r.ever_critical OR head.ever_critical,
      updated_at      = now()
  FROM (
    SELECT v.version, v.status, v.flag,
           bool_or(v.is_critical) OVER () AS ever_critical
    FROM lab.lab_result_versions v
    WHERE v.result_id = NEW.result_id
    ORDER BY v.version DESC
    LIMIT 1
  ) AS head
  WHERE r.id = NEW.result_id
    AND (
      r.current_version IS DISTINCT FROM head.version
      OR r.current_status IS DISTINCT FROM head.status
      OR r.current_flag IS DISTINCT FROM head.flag
      OR (head.ever_critical AND NOT r.ever_critical)
    );

  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_lab_result_versions_sync_head ON lab.lab_result_versions;
CREATE TRIGGER trg_lab_result_versions_sync_head
  AFTER INSERT OR UPDATE ON lab.lab_result_versions
  FOR EACH ROW EXECUTE FUNCTION lab.sync_result_head();

-- ── one result per analyte per order line ────────────────────────────────────
-- A partitioned unique index must contain `created_at`, which would permit a
-- duplicate a millisecond later; and `parameter_key` is null for a single-analyte
-- test, where NULLs are distinct. Both are enforced here instead.
CREATE OR REPLACE FUNCTION lab.enforce_result_identity()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM lab.lab_results r
    WHERE r.order_test_id = NEW.order_test_id
      AND r.parameter_key IS NOT DISTINCT FROM NEW.parameter_key
      AND r.id <> NEW.id
  ) THEN
    RAISE EXCEPTION
      'lab.lab_results: order line % already has a result for this analyte. A repeat measurement is a new version of that result, not a second result — two results for one analyte make "what is the potassium" ambiguous.',
      NEW.order_test_id
      USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_lab_results_identity ON lab.lab_results;
CREATE TRIGGER trg_lab_results_identity
  BEFORE INSERT OR UPDATE OF order_test_id, parameter_key ON lab.lab_results
  FOR EACH ROW EXECUTE FUNCTION lab.enforce_result_identity();

-- ── a rejected sample can never carry a result ──────────────────────────────
-- `OP-004 §5`: "rejected samples cannot be resulted." `EN-004 §5`: results
-- arriving for one go to the error queue. This makes the error queue the only
-- possible destination rather than the intended one.
CREATE OR REPLACE FUNCTION lab.refuse_result_on_rejected_sample()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_sample_status lab."LabSampleStatus";
  v_sample_no     text;
BEGIN
  SELECT s.status, s.sample_no
  INTO v_sample_status, v_sample_no
  FROM lab.lab_order_tests t
  JOIN lab.lab_samples s ON s.id = t.sample_id
  WHERE t.id = NEW.order_test_id;

  IF v_sample_status = 'rejected' THEN
    RAISE EXCEPTION
      'lab.lab_result_versions: sample % was rejected, so it cannot produce a result. An analyzer message for a rejected specimen belongs in integration.lab_if_error_queue (EN-004 §5), never on a patient''s report.',
      v_sample_no
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_lab_result_versions_reject_guard ON lab.lab_result_versions;
CREATE TRIGGER trg_lab_result_versions_reject_guard
  BEFORE INSERT ON lab.lab_result_versions
  FOR EACH ROW EXECUTE FUNCTION lab.refuse_result_on_rejected_sample();

-- ── the QC gate, applied ─────────────────────────────────────────────────────
-- `EN-031 §5`: "Result-release gating is absolute … The only exception is an
-- explicit Director authorisation recorded in `labq_qc_actions` with
-- `patient_impact = released_with_authorisation` and a reason."
--
-- Note what is NOT gated: storing the result. A number that exists is stored,
-- always. What the gate refuses is *releasing* it — moving it to `verified` or
-- `authorised` — which is the same principle as the critical-value rule in C.6
-- read from the other direction.
-- The gate needs the analyte's identity, which lives on `lab.lab_results` rather
-- than on the version row. Rather than denormalise two more columns onto every
-- one of ~36 M version rows a year, a small stable helper resolves them, which
-- also keeps the trigger readable.
CREATE OR REPLACE FUNCTION lab.result_analyte(p_result_id uuid, OUT test_key uuid, OUT parameter_key uuid)
LANGUAGE sql
STABLE
AS $$
  SELECT r.test_key, r.parameter_key FROM lab.lab_results r WHERE r.id = p_result_id;
$$;

GRANT EXECUTE ON FUNCTION lab.result_analyte(uuid) TO hms_app, hms_readonly;

CREATE OR REPLACE FUNCTION lab.enforce_result_qc_gate()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_state    lab."LabQcState";
  v_analyte  record;
  v_override record;
BEGIN
  IF NEW.status NOT IN ('verified', 'authorised') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_analyte FROM lab.result_analyte(NEW.result_id);

  IF NOT lab.qc_gate_applies(NEW.hospital_id, NEW.instrument_id, v_analyte.test_key, v_analyte.parameter_key) THEN
    RETURN NEW;
  END IF;

  v_state := lab.qc_state_for(NEW.hospital_id, NEW.instrument_id, v_analyte.test_key, v_analyte.parameter_key);
  NEW.qc_state_at_release := v_state;

  IF lab.qc_permits_release(v_state) THEN
    RETURN NEW;
  END IF;

  IF NEW.qc_override_action_id IS NULL THEN
    RAISE EXCEPTION
      'lab.lab_result_versions: the QC state for this analyte is "%" and does not permit release (EN-031 §5, phase-03 exit gate 4). Release it only under a Director authorisation recorded in lab.labq_qc_actions with patient_impact = released_with_authorisation, and name that action in qc_override_action_id.',
      v_state
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT patient_impact, authorised_by, authorisation_reason
  INTO v_override
  FROM lab.labq_qc_actions
  WHERE id = NEW.qc_override_action_id AND hospital_id = NEW.hospital_id;

  IF v_override.patient_impact IS DISTINCT FROM 'released_with_authorisation'
     OR v_override.authorised_by IS NULL
     OR v_override.authorisation_reason IS NULL
  THEN
    RAISE EXCEPTION
      'lab.lab_result_versions: qc_override_action_id % is not a Director authorisation to release (it must be a lab.labq_qc_actions row with patient_impact = released_with_authorisation, an authoriser and a reason)',
      NEW.qc_override_action_id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_lab_result_versions_qc_gate ON lab.lab_result_versions;
CREATE TRIGGER trg_lab_result_versions_qc_gate
  BEFORE INSERT OR UPDATE OF status ON lab.lab_result_versions
  FOR EACH ROW EXECUTE FUNCTION lab.enforce_result_qc_gate();

-- ── the chain verifier ───────────────────────────────────────────────────────
-- The one a NABL assessor asks for, and the one the integration suite asserts.
CREATE OR REPLACE FUNCTION lab.verify_result_chain(p_result_id uuid)
RETURNS TABLE (
  version      int,
  status       text,
  hash_matches boolean,
  link_matches boolean
)
LANGUAGE sql
STABLE
AS $$
  SELECT
    v.version,
    v.status::text,
    v.content_sha256 = encode(
      sha256(convert_to(
        jsonb_build_object(
          'result_id',        v.result_id,
          'version',          v.version,
          'result_type',      v.result_type::text,
          'value_numeric',    v.value_numeric,
          'value_coded',      v.value_coded,
          'value_multi',      to_jsonb(v.value_multi),
          'value_text',       v.value_text,
          'value_operator',   v.value_operator,
          'unit',             v.unit,
          'flag',             v.flag::text,
          'ref_low',          v.ref_low,
          'ref_high',         v.ref_high,
          'ref_critical_low', v.ref_critical_low,
          'ref_critical_high',v.ref_critical_high,
          'dilution_factor',  v.dilution_factor,
          'instrument_id',    v.instrument_id,
          'run_id',           v.run_id,
          'raw_message_id',   v.raw_message_id,
          'amendment_reason', v.amendment_reason
        )::text, 'UTF8')),
      'hex') AS hash_matches,
    COALESCE(
      v.prev_sha256 IS NOT DISTINCT FROM lag(v.content_sha256) OVER (ORDER BY v.version),
      false
    ) AS link_matches
  FROM lab.lab_result_versions v
  WHERE v.result_id = p_result_id
  ORDER BY v.version;
$$;

COMMENT ON FUNCTION lab.verify_result_chain IS
  'One row per version with its digest and link re-derived from scratch. `hash_matches = false` means a value was changed under its hash; `link_matches = false` means a version was removed or re-parented. Both should be impossible; the point of a verifier is not to trust that.';

GRANT EXECUTE ON FUNCTION lab.verify_result_chain(uuid) TO hms_app, hms_readonly;

-- The head version of a result, which is what every report and every worklist
-- reads.
CREATE INDEX IF NOT EXISTS idx_lab_result_versions_head
  ON lab.lab_result_versions (hospital_id, result_id, version DESC)
  WHERE superseded_by_version IS NULL;
-- The pathologist's authorisation queue.
CREATE INDEX IF NOT EXISTS idx_lab_result_versions_awaiting_authorisation
  ON lab.lab_result_versions (hospital_id, branch_id, recorded_at)
  WHERE status IN ('unverified', 'qc_hold', 'delta_hold', 'verified');
-- The criticals still outstanding, which is the screen `OP-004 §3.5` is about.
CREATE INDEX IF NOT EXISTS idx_lab_result_versions_critical
  ON lab.lab_result_versions (hospital_id, branch_id, recorded_at DESC)
  WHERE is_critical;

-- ── microbiology and histopathology ─────────────────────────────────────────
-- No growth is a result, and an important one — but it is not an organism.
ALTER TABLE lab.lab_micro_results
  ADD CONSTRAINT lab_micro_results_no_growth_exclusive
  CHECK (
    no_growth = false
    OR (organism_snomed IS NULL AND organism_name IS NULL AND colony_count IS NULL)
  );
ALTER TABLE lab.lab_micro_results
  ADD CONSTRAINT lab_micro_results_growth_named
  CHECK (no_growth OR organism_name IS NOT NULL);
ALTER TABLE lab.lab_micro_results
  ADD CONSTRAINT lab_micro_results_isolate_positive CHECK (isolate_no >= 1);
ALTER TABLE lab.lab_micro_results
  ADD CONSTRAINT lab_micro_results_colony_non_negative
  CHECK (colony_count IS NULL OR colony_count >= 0);

-- An S/I/R interpretation with neither an MIC nor a zone diameter has no
-- evidence behind it, and the antibiogram would inherit the guess.
ALTER TABLE lab.lab_micro_susceptibilities
  ADD CONSTRAINT lab_micro_susceptibilities_evidence
  CHECK (mic_value IS NOT NULL OR zone_mm IS NOT NULL);
ALTER TABLE lab.lab_micro_susceptibilities
  ADD CONSTRAINT lab_micro_susceptibilities_interpretation
  CHECK (interpretation IN ('S', 'I', 'R', 'SDD', 'NS'));
ALTER TABLE lab.lab_micro_susceptibilities
  ADD CONSTRAINT lab_micro_susceptibilities_suppression_reason
  CHECK (is_reported OR suppression_reason IS NOT NULL);
ALTER TABLE lab.lab_micro_susceptibilities
  ADD CONSTRAINT lab_micro_susceptibilities_values_positive
  CHECK ((mic_value IS NULL OR mic_value > 0) AND (zone_mm IS NULL OR zone_mm >= 0));

ALTER TABLE lab.lab_histo_results
  ADD CONSTRAINT lab_histo_results_counts_non_negative
  CHECK ((blocks_count IS NULL OR blocks_count >= 0) AND (slides_count IS NULL OR slides_count >= 0));
ALTER TABLE lab.lab_histo_results
  ADD CONSTRAINT lab_histo_results_signoff_pairing
  CHECK ((signed_out_by IS NULL) = (signed_out_at IS NULL));
-- `OP-004 §5`: histopathology blocks and slides are retained ten years, and a
-- signed-out case that names no retention date is one nobody will keep.
ALTER TABLE lab.lab_histo_results
  ADD CONSTRAINT lab_histo_results_retention_on_signoff
  CHECK (signed_out_at IS NULL OR (block_retention_until IS NOT NULL AND slide_retention_until IS NOT NULL));


-- ── C.6 the critical value: never withheld, never undocumented ─────────────
--
-- `docs/DECISIONS.md D-10` resolved a contradiction between `OP-004 §5` and its
-- own acceptance criteria: **release is never withheld, but authorisation
-- requires a documented read-back or a documented "clinician unreachable —
-- escalated" entry.** `docs/prompts/phase-03 §Non-negotiables 1` restates it and
-- adds the part that makes it a schema problem rather than a service problem:
-- "Encode both paths; make it impossible to record an acknowledgement with
-- neither."
--
-- Withholding a critical result to force paperwork is itself a hazard. Somebody
-- with a potassium of 7.1 does not become safer because the pathologist has not
-- yet reached the ward. So the two halves are separated:
--
--   **Release** is unconditional. The value is stored, the flag is on it, and
--   the alert obligation is raised by a database trigger in the same transaction
--   — before any service runs, and whether or not one remembers to. There is no
--   code path in which a critical value is stored and no alert exists.
--
--   **Authorisation** is conditional. Moving that version to `authorised`
--   requires at least one callback row, and a callback row cannot exist without
--   evidence: either a confirmed read-back naming a person, or a documented
--   escalation naming a tier. The CHECK makes "neither" unstorable and "both"
--   unstorable too, because a read-back from a clinician you could not reach is
--   not a fact.
--
-- The escalation arm is deliberately as easy to record as the read-back arm.
-- `D-10` calls it "a tracked exception on the NABL critical-value KPI, not a
-- silent bypass" — if it were harder, the pressure would fall back onto
-- withholding, which is the hazard the whole decision exists to remove.

-- **The evidence rule.** This single CHECK is `§Non-negotiables 1` in SQL.
ALTER TABLE lab.lab_critical_value_callbacks
  ADD CONSTRAINT lab_critical_value_callbacks_evidence
  CHECK (
    -- Arm one: somebody was told, and repeated it back.
    (read_back_confirmed
      AND NOT clinician_unreachable
      AND notified_to_name IS NOT NULL
      AND read_back_value IS NOT NULL)
    OR
    -- Arm two: nobody could be reached, and the alert was escalated to a named
    -- tier. `escalated_to_role` is required, not optional: "escalated" with no
    -- destination is the silent bypass D-10 forbids.
    (clinician_unreachable
      AND NOT read_back_confirmed
      AND escalated_to_level IS NOT NULL
      AND escalated_to_role IS NOT NULL)
  );

COMMENT ON CONSTRAINT lab_critical_value_callbacks_evidence ON lab.lab_critical_value_callbacks IS
  'docs/DECISIONS.md D-10 and phase-03 §Non-negotiables 1: a critical-value communication is either a confirmed read-back from a named clinician, or a documented "unreachable — escalated to <tier>". Neither is unstorable; both at once is unstorable; there is no third state and no way to click through this.';

ALTER TABLE lab.lab_critical_value_callbacks
  ADD CONSTRAINT lab_critical_value_callbacks_sequence_positive CHECK (sequence >= 1);
ALTER TABLE lab.lab_critical_value_callbacks
  ADD CONSTRAINT lab_critical_value_callbacks_attempts_positive CHECK (attempt_count >= 1);
ALTER TABLE lab.lab_critical_value_callbacks
  ADD CONSTRAINT lab_critical_value_callbacks_latency_non_negative
  CHECK (latency_seconds IS NULL OR latency_seconds >= 0);

-- The same rule, the same shape, for a critical radiology finding. `OP-008 §5`:
-- "the report cannot be marked 'communicated' without a name."
ALTER TABLE rad.rad_critical_callbacks
  ADD CONSTRAINT rad_critical_callbacks_evidence
  CHECK (
    (read_back_confirmed
      AND NOT clinician_unreachable
      AND notified_to_name IS NOT NULL
      AND read_back_value IS NOT NULL)
    OR
    (clinician_unreachable
      AND NOT read_back_confirmed
      AND escalated_to_level IS NOT NULL
      AND escalated_to_role IS NOT NULL)
  );

COMMENT ON CONSTRAINT rad_critical_callbacks_evidence ON rad.rad_critical_callbacks IS
  'The radiology twin of lab_critical_value_callbacks_evidence. EN-035 §2 says the critical-finding contract "mirrors the lab critical-value contract"; mirroring it in prose and not in the constraint would be how the two drift.';

ALTER TABLE rad.rad_critical_callbacks
  ADD CONSTRAINT rad_critical_callbacks_sequence_positive CHECK (sequence >= 1);
ALTER TABLE rad.rad_critical_callbacks
  ADD CONSTRAINT rad_critical_callbacks_attempts_positive CHECK (attempt_count >= 1);

-- Alert invariants, both families.
ALTER TABLE lab.lab_critical_value_alerts
  ADD CONSTRAINT lab_critical_value_alerts_flag_is_critical
  CHECK (flag IN ('critical_low', 'critical_high'));
ALTER TABLE lab.lab_critical_value_alerts
  ADD CONSTRAINT lab_critical_value_alerts_escalation_non_negative
  CHECK (escalation_level >= 0);
ALTER TABLE lab.lab_critical_value_alerts
  ADD CONSTRAINT lab_critical_value_alerts_ack_pairing
  CHECK ((acknowledged_by IS NULL) = (acknowledged_at IS NULL));
ALTER TABLE lab.lab_critical_value_alerts
  ADD CONSTRAINT lab_critical_value_alerts_retraction_reason
  CHECK ((status = 'retracted') = (retracted_at IS NOT NULL));
ALTER TABLE lab.lab_critical_value_alerts
  ADD CONSTRAINT lab_critical_value_alerts_retraction_attributed
  CHECK (retracted_at IS NULL OR retracted_reason IS NOT NULL);
-- An alert that says it was communicated must have a communication behind it.
-- The trigger below is what maintains these; the CHECK is what stops anything
-- else from setting them.
ALTER TABLE lab.lab_critical_value_alerts
  ADD CONSTRAINT lab_critical_value_alerts_communicated_pairing
  CHECK ((status IN ('communicated', 'escalated', 'acknowledged')) = (first_communicated_at IS NOT NULL));

ALTER TABLE rad.rad_critical_findings
  ADD CONSTRAINT rad_critical_findings_level
  CHECK (level IN ('incidental', 'urgent', 'critical'));
ALTER TABLE rad.rad_critical_findings
  ADD CONSTRAINT rad_critical_findings_escalation_non_negative
  CHECK (escalation_level >= 0);
ALTER TABLE rad.rad_critical_findings
  ADD CONSTRAINT rad_critical_findings_ack_pairing
  CHECK ((acknowledged_by IS NULL) = (acknowledged_at IS NULL));
ALTER TABLE rad.rad_critical_findings
  ADD CONSTRAINT rad_critical_findings_retraction_attributed
  CHECK (retracted_at IS NULL OR retracted_reason IS NOT NULL);
ALTER TABLE rad.rad_critical_findings
  ADD CONSTRAINT rad_critical_findings_communicated_pairing
  CHECK ((status IN ('communicated', 'escalated', 'acknowledged')) = (first_communicated_at IS NOT NULL));

-- ── the obligation raises itself ────────────────────────────────────────────
-- This is the mechanical half of "release is never withheld". The alert is
-- created by the database, in the transaction that stores the value, so the
-- storing and the alerting cannot come apart. A service that forgot to raise one
-- cannot exist; a downtime replay that skipped the service layer still raises
-- one; a data migration that inserted a critical potassium raises one.
CREATE OR REPLACE FUNCTION lab.raise_critical_value_alert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_ctx    record;
  v_due    interval;
  v_value  text;
BEGIN
  IF NOT NEW.is_critical THEN
    RETURN NULL;
  END IF;

  SELECT t.order_id, r.analyte_name, r.branch_id
  INTO v_ctx
  FROM lab.lab_order_tests t
  JOIN lab.lab_results r ON r.id = NEW.result_id
  WHERE t.id = NEW.order_test_id;

  -- The NABL indicator is "% criticals communicated ≤ 30 min", so 30 minutes is
  -- the default window. It is a hospital setting in EN-037's escalation ladder;
  -- this is the floor the database applies when nothing overrides it.
  v_due := interval '30 minutes';

  v_value := COALESCE(
    NEW.value_operator || ' ' || NEW.value_numeric::text,
    NEW.value_numeric::text,
    NEW.value_coded,
    left(COALESCE(NEW.value_text, ''), 120)
  );

  INSERT INTO lab.lab_critical_value_alerts (
    id, hospital_id, branch_id,
    result_id, result_version_id, result_version,
    order_id, order_test_id, patient_id,
    analyte_name, flag, value_display, unit,
    ref_critical_low, ref_critical_high,
    detected_at, due_by, status, escalation_level,
    created_at, created_by, updated_at
  )
  VALUES (
    gen_random_uuid(), NEW.hospital_id, COALESCE(v_ctx.branch_id, NEW.branch_id),
    NEW.result_id, NEW.id, NEW.version,
    v_ctx.order_id, NEW.order_test_id, NEW.patient_id,
    COALESCE(v_ctx.analyte_name, 'unknown analyte'), NEW.flag, COALESCE(v_value, 'n/a'), NEW.unit,
    NEW.ref_critical_low, NEW.ref_critical_high,
    NEW.recorded_at, NEW.recorded_at + v_due, 'open', 0,
    now(), NEW.created_by, now()
  )
  ON CONFLICT (result_version_id) DO NOTHING;

  RETURN NULL;
END;
$$;

COMMENT ON FUNCTION lab.raise_critical_value_alert IS
  'docs/DECISIONS.md D-10, the mechanical half: the alert obligation is created by the database in the same transaction as the critical value, so storing a critical result and raising its alert cannot come apart. Release is therefore never withheld — the value is already stored — while the obligation to communicate it already exists. Idempotent on result_version_id.';

DROP TRIGGER IF EXISTS trg_lab_result_versions_raise_critical ON lab.lab_result_versions;
CREATE TRIGGER trg_lab_result_versions_raise_critical
  AFTER INSERT ON lab.lab_result_versions
  FOR EACH ROW EXECUTE FUNCTION lab.raise_critical_value_alert();

-- ── authorisation requires the documentation ────────────────────────────────
-- The other half of D-10. Note the asymmetry, which is the whole point: this
-- trigger fires on the transition to `authorised` and on nothing else. Storing
-- the value, flagging it, showing it on a ward screen, sending it to the doctor's
-- inbox and printing it on an interim report are all unaffected.
CREATE OR REPLACE FUNCTION lab.enforce_critical_authorisation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_evidence boolean;
BEGIN
  IF NEW.status <> 'authorised' OR NOT NEW.is_critical THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'authorised' THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM lab.lab_critical_value_alerts a
    JOIN lab.lab_critical_value_callbacks c ON c.alert_id = a.id
    WHERE a.result_version_id = NEW.id
  ) INTO v_evidence;

  IF NOT v_evidence THEN
    RAISE EXCEPTION
      'lab.lab_result_versions: this result is critical and cannot be authorised until the communication is documented — a lab.lab_critical_value_callbacks row with a confirmed read-back, OR one recording "clinician unreachable" with the tier it was escalated to (docs/DECISIONS.md D-10). The result itself is already released and visible; what is blocked is the authorisation, never the value.'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION lab.enforce_critical_authorisation IS
  'docs/DECISIONS.md D-10, the documentary half. Fires only on the transition to authorised: the value is stored, flagged and visible regardless. Withholding a critical result to force paperwork is itself a hazard, so the block is placed on the signature and not on the number.';

DROP TRIGGER IF EXISTS trg_lab_result_versions_critical_authorisation ON lab.lab_result_versions;
CREATE TRIGGER trg_lab_result_versions_critical_authorisation
  BEFORE INSERT OR UPDATE OF status ON lab.lab_result_versions
  FOR EACH ROW EXECUTE FUNCTION lab.enforce_critical_authorisation();

-- ── the alert closes itself when the evidence arrives ───────────────────────
-- `first_communicated_at` and `status` are a projection of the callback rows, and
-- a projection a caller maintains is a projection that drifts — the same reason
-- `lab.sync_result_head()` exists.
CREATE OR REPLACE FUNCTION lab.sync_critical_alert_status()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  UPDATE lab.lab_critical_value_alerts a
  SET first_communicated_at = LEAST(COALESCE(a.first_communicated_at, NEW.notified_at), NEW.notified_at),
      status = CASE
                 WHEN a.status = 'acknowledged' THEN a.status
                 WHEN a.status = 'retracted'    THEN a.status
                 WHEN NEW.read_back_confirmed   THEN 'communicated'::lab."LabCriticalAlertStatus"
                 ELSE 'escalated'::lab."LabCriticalAlertStatus"
               END,
      escalation_level = GREATEST(a.escalation_level, COALESCE(NEW.escalated_to_level, 0)),
      updated_at = now()
  WHERE a.id = NEW.alert_id;

  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_lab_critical_callbacks_sync ON lab.lab_critical_value_callbacks;
CREATE TRIGGER trg_lab_critical_callbacks_sync
  AFTER INSERT ON lab.lab_critical_value_callbacks
  FOR EACH ROW EXECUTE FUNCTION lab.sync_critical_alert_status();

CREATE OR REPLACE FUNCTION rad.sync_critical_finding_status()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  UPDATE rad.rad_critical_findings f
  SET first_communicated_at = LEAST(COALESCE(f.first_communicated_at, NEW.notified_at), NEW.notified_at),
      status = CASE
                 WHEN f.status = 'acknowledged' THEN f.status
                 WHEN f.status = 'retracted'    THEN f.status
                 WHEN NEW.read_back_confirmed   THEN 'communicated'::lab."LabCriticalAlertStatus"
                 ELSE 'escalated'::lab."LabCriticalAlertStatus"
               END,
      escalation_level = GREATEST(f.escalation_level, COALESCE(NEW.escalated_to_level, 0)),
      updated_at = now()
  WHERE f.id = NEW.finding_id;

  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_rad_critical_callbacks_sync ON rad.rad_critical_callbacks;
CREATE TRIGGER trg_rad_critical_callbacks_sync
  AFTER INSERT ON rad.rad_critical_callbacks
  FOR EACH ROW EXECUTE FUNCTION rad.sync_critical_finding_status();

-- ── an order cannot close over an open critical ─────────────────────────────
-- `OP-004 §5`: "the lab order cannot move to `reported`/closed while any critical
-- alert on it is unacknowledged."
CREATE OR REPLACE FUNCTION lab.enforce_order_close_criticals()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_open int;
BEGIN
  IF NEW.status <> 'reported' OR OLD.status = 'reported' THEN
    RETURN NEW;
  END IF;

  SELECT count(*) INTO v_open
  FROM lab.lab_critical_value_alerts a
  WHERE a.order_id = NEW.id
    AND a.status IN ('open', 'communicated', 'escalated');

  IF v_open > 0 THEN
    RAISE EXCEPTION
      'lab.lab_orders: % critical alert(s) on this order are not yet acknowledged by the ordering clinician (OP-004 §5). The results are released and the report is available; what cannot happen is the order being marked reported and disappearing from the follow-up list.',
      v_open
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_lab_orders_close_criticals ON lab.lab_orders;
CREATE TRIGGER trg_lab_orders_close_criticals
  BEFORE UPDATE OF status ON lab.lab_orders
  FOR EACH ROW EXECUTE FUNCTION lab.enforce_order_close_criticals();

-- The screens this loop lives on: everything still owed a phone call, and
-- everything communicated but not yet acknowledged.
CREATE INDEX IF NOT EXISTS idx_lab_critical_alerts_open
  ON lab.lab_critical_value_alerts (hospital_id, branch_id, due_by)
  WHERE status IN ('open', 'communicated', 'escalated');
CREATE INDEX IF NOT EXISTS idx_rad_critical_findings_open
  ON rad.rad_critical_findings (hospital_id, branch_id, due_by)
  WHERE status IN ('open', 'communicated', 'escalated');


-- ── C.7 radiology, dose, and PC-PNDT ────────────────────────────────────────

-- `OP-008 §5`: "Clinical indication mandatory." An imaging request with no
-- question is an exposure with no justification, and AERB asks for the
-- justification.
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_indication_present
  CHECK (length(btrim(clinical_indication)) > 0);
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_cancel_reason
  CHECK (status <> 'cancelled' OR cancel_reason IS NOT NULL);
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_cancel_pairing
  CHECK ((status = 'cancelled') = (cancelled_at IS NOT NULL));
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_egfr_pairing CHECK ((egfr IS NULL) = (egfr_at IS NULL));
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_egfr_range CHECK (egfr IS NULL OR (egfr >= 0 AND egfr <= 250));
-- The pregnancy check is a fact somebody established, at a time. A status with
-- neither is a screen nobody did.
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_pregnancy_attributed
  CHECK (
    pregnancy_status IS NULL
    OR pregnancy_status = 'unknown'
    OR (pregnancy_checked_by IS NOT NULL AND pregnancy_checked_at IS NOT NULL)
  );
-- An override is a named person with a reason, in both directions, in both
-- places `OP-008 §5` allows one.
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_mri_override_pairing
  CHECK ((mri_override_by IS NULL) = (mri_override_reason IS NULL));
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_contrast_override_pairing
  CHECK ((contrast_approved_by IS NULL) = (contrast_approval_reason IS NULL));
-- `OP-008 §5`: "MRI: safety checklist mandatory … blocked if unsafe device
-- without radiologist override." An unsafe implant with no override cannot reach
-- a scheduled state.
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_mri_unsafe_needs_override
  CHECK (
    mri_unsafe_implant = false
    OR status IN ('placed', 'on_hold_safety', 'cancelled', 'rejected')
    OR mri_override_by IS NOT NULL
  );
-- `OP-008 §5`: a documented iodinated-contrast allergy needs premedication or a
-- radiologist's approval before the study is scheduled.
ALTER TABLE rad.rad_orders
  ADD CONSTRAINT rad_orders_contrast_allergy_managed
  CHECK (
    contrast_allergy_known = false
    OR contrast_required = false
    OR status IN ('placed', 'on_hold_safety', 'cancelled', 'rejected')
    OR premed_protocol_key IS NOT NULL
    OR contrast_approved_by IS NOT NULL
  );

CREATE UNIQUE INDEX IF NOT EXISTS uq_rad_orders_idempotency
  ON rad.rad_orders (hospital_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;

-- `OP-008 §5`: a laterality-required procedure without one is the classic
-- wrong-side error. The procedure master says which; the trigger reads it,
-- because a CHECK cannot span two tables.
ALTER TABLE rad.rad_order_items
  ADD CONSTRAINT rad_order_items_cancel_reason
  CHECK (status <> 'cancelled' OR cancel_reason IS NOT NULL);
ALTER TABLE rad.rad_order_items
  ADD CONSTRAINT rad_order_items_uid_shape
  CHECK (study_instance_uid IS NULL OR study_instance_uid ~ '^[0-9]+(\.[0-9]+)+$');

CREATE OR REPLACE FUNCTION rad.enforce_procedure_safety_flags()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_proc record;
BEGIN
  SELECT p.laterality_required, p.is_pcpndt, p.is_ionising, p.name
  INTO v_proc
  FROM mdm.mdm_rad_procedures p
  WHERE p.record_key = NEW.procedure_key
    AND p.status = 'active'
    AND p.effective_from <= now()
    AND (p.effective_to IS NULL OR p.effective_to > now())
  ORDER BY p.effective_from DESC
  LIMIT 1;

  IF v_proc IS NULL THEN
    RETURN NEW;  -- an inactive or future-dated master is the service's problem, not a data-integrity one
  END IF;

  IF v_proc.laterality_required AND NEW.laterality = 'not_applicable' THEN
    RAISE EXCEPTION
      'rad.rad_order_items: "%" requires a laterality. Wrong-side imaging is a never-event, and "not applicable" on a procedure the master says has sides is how one starts.',
      v_proc.name
      USING ERRCODE = 'check_violation';
  END IF;

  -- Snapshot the statutory flags so a later master edit cannot lift a Form F or
  -- a dose obligation from a study that was performed under it.
  IF TG_OP = 'INSERT' THEN
    NEW.is_pcpndt := v_proc.is_pcpndt;
    NEW.is_ionising := v_proc.is_ionising;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_rad_order_items_safety_flags ON rad.rad_order_items;
CREATE TRIGGER trg_rad_order_items_safety_flags
  BEFORE INSERT OR UPDATE OF procedure_key, laterality ON rad.rad_order_items
  FOR EACH ROW EXECUTE FUNCTION rad.enforce_procedure_safety_flags();

-- Rooms, exams, repeats, contrast.
ALTER TABLE rad.rad_modality_rooms
  ADD CONSTRAINT rad_modality_rooms_ae_present CHECK (length(btrim(ae_title)) > 0);
ALTER TABLE rad.rad_modality_rooms
  ADD CONSTRAINT rad_modality_rooms_block_reason
  CHECK (scheduling_blocked = false OR scheduling_block_reason IS NOT NULL);
ALTER TABLE rad.rad_modality_rooms
  ADD CONSTRAINT rad_modality_rooms_override_pairing
  CHECK ((scheduling_override_by IS NULL) = (scheduling_override_reason IS NULL));
-- **PC-PNDT**: an ultrasound room that performs obstetric scans must be
-- registered under the Act, and the registration number prints on the report.
-- A room with a registration number must also have its validity, or the block
-- cannot be applied when it lapses.
ALTER TABLE rad.rad_modality_rooms
  ADD CONSTRAINT rad_modality_rooms_pcpndt_pairing
  CHECK ((pcpndt_registration_no IS NULL) = (pcpndt_registration_valid_to IS NULL));

ALTER TABLE rad.rad_exams
  ADD CONSTRAINT rad_exams_time_order
  CHECK (started_at IS NULL OR completed_at IS NULL OR completed_at >= started_at);
ALTER TABLE rad.rad_exams
  ADD CONSTRAINT rad_exams_completion_pairing
  CHECK ((status = 'completed') = (completed_at IS NOT NULL));
ALTER TABLE rad.rad_exams
  ADD CONSTRAINT rad_exams_discontinued_reason
  CHECK (status <> 'discontinued' OR discontinued_reason IS NOT NULL);
ALTER TABLE rad.rad_exams
  ADD CONSTRAINT rad_exams_repeat_non_negative CHECK (repeat_count >= 0);
-- `OP-008 §3.3.2`: identity two-check and safety checklist before acquisition.
ALTER TABLE rad.rad_exams
  ADD CONSTRAINT rad_exams_identity_before_start
  CHECK (started_at IS NULL OR identity_verified);
ALTER TABLE rad.rad_exams
  ADD CONSTRAINT rad_exams_checklist_before_start
  CHECK (started_at IS NULL OR safety_checklist_completed);
-- `EN-035 §5`: a "trauma unknown" placeholder must be reconciled within 24 hours,
-- so it carries a deadline from the moment it is created.
ALTER TABLE rad.rad_exams
  ADD CONSTRAINT rad_exams_placeholder_deadline
  CHECK (is_emergency_placeholder = false OR reconciliation_due_at IS NOT NULL);
ALTER TABLE rad.rad_exams
  ADD CONSTRAINT rad_exams_reconciled_pairing
  CHECK ((reconciled_at IS NULL) = (reconciled_by IS NULL));

CREATE INDEX IF NOT EXISTS idx_rad_exams_unreconciled
  ON rad.rad_exams (hospital_id, branch_id, reconciliation_due_at)
  WHERE is_emergency_placeholder AND reconciled_at IS NULL;

ALTER TABLE rad.rad_repeat_reject_events
  ADD CONSTRAINT rad_repeat_reject_events_kind CHECK (kind IN ('repeat', 'reject'));
ALTER TABLE rad.rad_repeat_reject_events
  ADD CONSTRAINT rad_repeat_reject_events_reason
  CHECK (reason_code IN ('positioning', 'exposure', 'motion', 'artefact', 'equipment', 'patient', 'other'));
ALTER TABLE rad.rad_repeat_reject_events
  ADD CONSTRAINT rad_repeat_reject_events_other_note
  CHECK (reason_code <> 'other' OR reason_note IS NOT NULL);

ALTER TABLE rad.rad_contrast_events
  ADD CONSTRAINT rad_contrast_events_volume_positive
  CHECK (volume_ml IS NULL OR volume_ml > 0);
-- `OP-008 §3.3.2`: "contrast lot recorded". A recall that cannot name the lot is
-- a recall of every patient.
ALTER TABLE rad.rad_contrast_events
  ADD CONSTRAINT rad_contrast_events_lot_present
  CHECK (length(btrim(COALESCE(lot_no, ''))) > 0);
ALTER TABLE rad.rad_contrast_events
  ADD CONSTRAINT rad_contrast_events_reaction_described
  CHECK (reaction_observed = false OR (reaction_severity IS NOT NULL AND reaction_description IS NOT NULL));

-- ── dose ─────────────────────────────────────────────────────────────────────
ALTER TABLE rad.rad_dose_records
  ADD CONSTRAINT rad_dose_records_source
  CHECK (source IN ('rdsr', 'header', 'mpps', 'ocr', 'manual'));
ALTER TABLE rad.rad_dose_records
  ADD CONSTRAINT rad_dose_records_values_non_negative
  CHECK (
    (ctdivol_mgy IS NULL OR ctdivol_mgy >= 0)
    AND (dlp_mgycm IS NULL OR dlp_mgycm >= 0)
    AND (dap_gycm2 IS NULL OR dap_gycm2 >= 0)
    AND (fluoro_time_s IS NULL OR fluoro_time_s >= 0)
    AND (effective_dose_msv IS NULL OR effective_dose_msv >= 0)
  );
-- A dose record with no dose in it is a form somebody clicked through.
ALTER TABLE rad.rad_dose_records
  ADD CONSTRAINT rad_dose_records_has_a_figure
  CHECK (
    ctdivol_mgy IS NOT NULL OR dlp_mgycm IS NOT NULL OR dap_gycm2 IS NOT NULL
    OR effective_dose_msv IS NOT NULL OR exposure_count IS NOT NULL
  );
-- An estimated effective dose names the factor it was computed with, or it
-- cannot be reproduced when the factor is revised.
ALTER TABLE rad.rad_dose_records
  ADD CONSTRAINT rad_dose_records_k_factor_pairing
  CHECK (effective_dose_msv IS NULL OR k_factor_used IS NOT NULL);
-- `EN-035 §5`: "a modality without RDSR requires a documented manual-entry
-- procedure". Manual is legitimate; anonymous manual is not.
ALTER TABLE rad.rad_dose_records
  ADD CONSTRAINT rad_dose_records_manual_attributed
  CHECK (source NOT IN ('manual', 'ocr') OR entered_by IS NOT NULL);
ALTER TABLE rad.rad_dose_records
  ADD CONSTRAINT rad_dose_records_rdsr_uid
  CHECK (source <> 'rdsr' OR rdsr_instance_uid IS NOT NULL);

ALTER TABLE rad.rad_patient_dose_summary
  ADD CONSTRAINT rad_patient_dose_summary_non_negative
  CHECK (cumulative_msv_lifetime >= 0 AND msv_12m >= 0 AND ct_count_12m >= 0 AND study_count_12m >= 0);
-- A twelve-month figure cannot exceed a lifetime one.
ALTER TABLE rad.rad_patient_dose_summary
  ADD CONSTRAINT rad_patient_dose_summary_12m_within_lifetime
  CHECK (msv_12m <= cumulative_msv_lifetime);
ALTER TABLE rad.rad_dose_k_factors
  ADD CONSTRAINT rad_dose_k_factors_positive CHECK (k_factor > 0);
ALTER TABLE rad.rad_dose_k_factors
  ADD CONSTRAINT rad_dose_k_factors_age_order CHECK (age_max_days >= age_min_days);

-- ═══════════════════════════════════════════════════════════════════════════
-- PC-PNDT
--
-- The Pre-Conception and Pre-Natal Diagnostic Techniques (Prohibition of Sex
-- Selection) Act 1994. Section 6 prohibits conducting a prenatal diagnostic
-- technique for determining the sex of the foetus; Section 5 prohibits
-- communicating it "in any manner"; Section 23 makes both punishable with
-- imprisonment up to three years for the medical professional and for the person
-- who sought it, rising on a subsequent conviction, with the doctor's name
-- reported to the State Medical Council for suspension of registration.
--
-- `docs/prompts/phase-03 §Non-negotiables 4`: "an obstetric ultrasound cannot be
-- saved without Form F fields, and **no sex-determination field may exist
-- anywhere in the schema**. This is criminal law in India, not a preference."
--
-- Two enforcements, and the second is the one that has to survive future phases.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── Form F completeness ─────────────────────────────────────────────────────
-- Most of the statutory fields are NOT NULL columns, so a Form F missing them
-- cannot be inserted at all. What NOT NULL cannot express is the rest:
ALTER TABLE rad.rad_form_f
  ADD CONSTRAINT rad_form_f_indication_present
  CHECK (cardinality(indication_codes) > 0);
COMMENT ON CONSTRAINT rad_form_f_indication_present ON rad.rad_form_f IS
  'The Form prescribes a list of indications for which a prenatal diagnostic procedure may lawfully be conducted. "Routine" is not among them, and an empty list is how a register becomes unauditable.';
ALTER TABLE rad.rad_form_f
  ADD CONSTRAINT rad_form_f_procedures_present
  CHECK (cardinality(procedures_performed) > 0);
ALTER TABLE rad.rad_form_f
  ADD CONSTRAINT rad_form_f_age_plausible
  CHECK (patient_age_years BETWEEN 10 AND 70);
ALTER TABLE rad.rad_form_f
  ADD CONSTRAINT rad_form_f_obstetric_history_non_negative
  CHECK (
    (gravida IS NULL OR gravida >= 0)
    AND (para IS NULL OR para >= 0)
    AND (living_children IS NULL OR living_children >= 0)
    AND (previous_abortions IS NULL OR previous_abortions >= 0)
  );
ALTER TABLE rad.rad_form_f
  ADD CONSTRAINT rad_form_f_gestational_age_plausible
  CHECK (gestational_age_weeks IS NULL OR (gestational_age_weeks > 0 AND gestational_age_weeks <= 45));
-- A declaration that is signed carries the signed document and the moment it was
-- signed. A tick with neither is not a declaration.
ALTER TABLE rad.rad_form_f
  ADD CONSTRAINT rad_form_f_woman_declaration_evidence
  CHECK (
    woman_declaration_signed = false
    OR (woman_declaration_doc_id IS NOT NULL AND woman_declaration_at IS NOT NULL)
  );
ALTER TABLE rad.rad_form_f
  ADD CONSTRAINT rad_form_f_doctor_declaration_evidence
  CHECK (
    doctor_declaration_signed = false
    OR (doctor_declaration_doc_id IS NOT NULL AND doctor_declaration_at IS NOT NULL)
  );
ALTER TABLE rad.rad_form_f
  ADD CONSTRAINT rad_form_f_return_period
  CHECK (return_month BETWEEN 1 AND 12 AND return_year BETWEEN 1994 AND 2200);
ALTER TABLE rad.rad_form_f
  ADD CONSTRAINT rad_form_f_registrations_present
  CHECK (
    length(btrim(facility_registration_no)) > 0
    AND length(btrim(machine_registration_no)) > 0
    AND length(btrim(performed_by_registration_no)) > 0
  );

ALTER TABLE rad.rad_form_f_monthly_returns
  ADD CONSTRAINT rad_form_f_monthly_returns_status
  CHECK (status IN ('draft', 'submitted', 'acknowledged'));
ALTER TABLE rad.rad_form_f_monthly_returns
  ADD CONSTRAINT rad_form_f_monthly_returns_period
  CHECK (return_month BETWEEN 1 AND 12 AND return_year BETWEEN 1994 AND 2200);
ALTER TABLE rad.rad_form_f_monthly_returns
  ADD CONSTRAINT rad_form_f_monthly_returns_submission
  CHECK (status = 'draft' OR (submitted_by IS NOT NULL AND submitted_at IS NOT NULL));

-- ── no obstetric ultrasound completes or signs without a complete Form F ────
CREATE OR REPLACE FUNCTION rad.enforce_form_f()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_order_item_id uuid;
  v_is_pcpndt     boolean;
  v_room_reg      text;
  v_room_valid    date;
  v_form          record;
BEGIN
  IF TG_TABLE_NAME = 'rad_exams' THEN
    IF NEW.status <> 'completed' THEN RETURN NEW; END IF;
    v_order_item_id := NEW.order_item_id;
  ELSE
    -- rad_report_versions
    IF NEW.status NOT IN ('final', 'amended') THEN RETURN NEW; END IF;
    SELECT r.order_item_id INTO v_order_item_id
    FROM rad.rad_reports r WHERE r.id = NEW.report_id;
  END IF;

  SELECT i.is_pcpndt INTO v_is_pcpndt
  FROM rad.rad_order_items i WHERE i.id = v_order_item_id;

  IF NOT COALESCE(v_is_pcpndt, false) THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_form FROM rad.rad_form_f f WHERE f.order_item_id = v_order_item_id;

  IF v_form.id IS NULL THEN
    RAISE EXCEPTION
      'PC-PNDT: this is an obstetric ultrasound and no Form F exists for it. The Pre-Conception and Pre-Natal Diagnostic Techniques (Prohibition of Sex Selection) Act 1994 makes Form F a statutory record for every such procedure — it is not paperwork that can follow later.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT v_form.woman_declaration_signed OR NOT v_form.doctor_declaration_signed THEN
    RAISE EXCEPTION
      'PC-PNDT: Form F % is incomplete — the declaration of the pregnant woman (%) and the declaration of the medical practitioner (%) are both mandatory before the procedure may be recorded as performed.',
      v_form.form_serial_no,
      CASE WHEN v_form.woman_declaration_signed THEN 'signed' ELSE 'NOT SIGNED' END,
      CASE WHEN v_form.doctor_declaration_signed THEN 'signed' ELSE 'NOT SIGNED' END
      USING ERRCODE = 'check_violation';
  END IF;

  -- The machine must be registered under the Act, and its registration current.
  IF TG_TABLE_NAME = 'rad_exams' AND NEW.room_id IS NOT NULL THEN
    SELECT pcpndt_registration_no, pcpndt_registration_valid_to
    INTO v_room_reg, v_room_valid
    FROM rad.rad_modality_rooms WHERE id = NEW.room_id;

    IF v_room_reg IS NULL THEN
      RAISE EXCEPTION
        'PC-PNDT: this ultrasound machine has no registration under the Act. Section 3 permits a prenatal diagnostic procedure only at a registered Genetic Clinic / Ultrasound Clinic / Imaging Centre, on registered equipment.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF v_room_valid < current_date THEN
      RAISE EXCEPTION
        'PC-PNDT: the registration of this ultrasound machine expired on %.', v_room_valid
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION rad.enforce_form_f IS
  'phase-03 exit gate 6: "Obstetric ultrasound cannot be saved without Form F fields." Enforced at both points where the record becomes real — completing the exam and signing the report — and additionally checks that the machine is registered under the Act and its registration current. A trigger and not a service check, because the Act does not care which code path the hospital used.';

DROP TRIGGER IF EXISTS trg_rad_exams_form_f ON rad.rad_exams;
CREATE TRIGGER trg_rad_exams_form_f
  BEFORE INSERT OR UPDATE OF status ON rad.rad_exams
  FOR EACH ROW EXECUTE FUNCTION rad.enforce_form_f();

DROP TRIGGER IF EXISTS trg_rad_report_versions_form_f ON rad.rad_report_versions;
CREATE TRIGGER trg_rad_report_versions_form_f
  BEFORE INSERT OR UPDATE OF status ON rad.rad_report_versions
  FOR EACH ROW EXECUTE FUNCTION rad.enforce_form_f();

-- ── the assertion: no column anywhere could hold a foetal sex ───────────────
--
-- Modelled on the Phase-2 `cdss_safety_floor` guard, and for the same reason:
-- the absence of the column IS the guarantee, and a test somebody can mark
-- `skip` is a weaker one than a migration that will not apply.
--
-- The pattern deliberately matches *foetal* sex and sex *selection*, not the
-- word "sex" alone. `patient.patients.gender`, `lab.lab_reference_ranges.sex`
-- and `rad.pacs_mwl_entries.patient_sex_dicom` are all legitimate and, in the
-- last case, mandated by the DICOM standard for every worklist entry — a guard
-- that caught them would be deleted within a week, and a deleted guard protects
-- nothing.
DO $$
DECLARE
  v_offending text;
  -- Every alternative is anchored at a word boundary (`(^|_)`), which is not
  -- decoration. The first draft of this pattern was not, and it matched
  -- `rad.pacs_mwl_entries.patient_sex_dicom` — because "patie**nt_sex**" ends in
  -- a token the pattern accepted — which would have failed the migration over
  -- the one field DICOM PS3.3 (0010,0040) requires on every worklist entry. A
  -- guard that blocks lawful, standard-mandated data is a guard somebody
  -- removes, and a removed guard protects nothing.
  v_pattern   text :=
    '(^|_)(foetal|fetal|foetus|fetus|unborn|baby|child|prenatal|antenatal|gestational)_?(sex|gender)'
    || '|(^|_)(sex|gender)_?(of)?_?(foetus|fetus|baby|child|unborn|embryo)'
    || '|(^|_)sex_?(determination|selection|prediction|reveal|disclosure)'
    || '|(^|_)(determin|select|predict|reveal|disclos)[a-z]*_?sex'
    || '|(^|_)gender_?(determination|selection|prediction|reveal|disclosure)';
BEGIN
  -- 1. columns
  SELECT string_agg(format('%s.%s.%s', table_schema, table_name, column_name), ', '
                    ORDER BY table_schema, table_name, column_name)
  INTO v_offending
  FROM information_schema.columns
  WHERE table_schema IN ('rad', 'lab', 'mdm', 'clinical', 'patient', 'integration')
    AND lower(column_name) ~ v_pattern;

  IF v_offending IS NOT NULL THEN
    RAISE EXCEPTION
      'PC-PNDT: the schema has acquired column(s) that could record or communicate the sex of a foetus: %. Section 5 and Section 6 of the Pre-Conception and Pre-Natal Diagnostic Techniques (Prohibition of Sex Selection) Act 1994 prohibit determining it and communicating it "in any manner"; Section 23 makes both punishable with imprisonment. The absence of the column IS the compliance. Remove it.',
      v_offending;
  END IF;

  -- 2. enum labels, because a value set can carry what a column name does not
  SELECT string_agg(format('%s.%s = %s', n.nspname, t.typname, e.enumlabel), ', ')
  INTO v_offending
  FROM pg_enum e
  JOIN pg_type t ON t.oid = e.enumtypid
  JOIN pg_namespace n ON n.oid = t.typnamespace
  WHERE n.nspname IN ('rad', 'lab', 'mdm', 'clinical', 'patient', 'integration')
    AND lower(e.enumlabel) ~ v_pattern;

  IF v_offending IS NOT NULL THEN
    RAISE EXCEPTION
      'PC-PNDT: an enum value could carry a foetal sex: %. Same Act, same sections, same answer — it does not exist here.',
      v_offending;
  END IF;

  -- 3. and the guard must actually be capable of firing. A regex silently broken
  --    by a future edit would report "nothing found" forever, which is exactly
  --    the failure mode this whole block exists to prevent.
  IF NOT ('foetal_sex' ~ v_pattern
          AND 'fetal_gender' ~ v_pattern
          AND 'sex_of_foetus' ~ v_pattern
          AND 'sex_determination' ~ v_pattern
          AND 'sex_selection' ~ v_pattern
          AND 'baby_sex' ~ v_pattern
          AND 'unborn_gender' ~ v_pattern
          AND 'predicted_sex' ~ v_pattern
          AND 'gender_reveal' ~ v_pattern
          AND 'usg_foetal_sex' ~ v_pattern) THEN
    RAISE EXCEPTION
      'PC-PNDT: the foetal-sex column guard no longer matches the names it exists to catch. A guard that cannot fire is worse than none, because it reports success.';
  END IF;

  -- 4. and it must NOT match the legitimate, standard-mandated fields, or it
  --    will be deleted the first time it blocks a release.
  IF 'sex' ~ v_pattern
     OR 'gender' ~ v_pattern
     OR 'patient_sex_dicom' ~ v_pattern
     OR 'patient_gender' ~ v_pattern
     OR 'sex_at_birth' ~ v_pattern
     OR 'gender_identity' ~ v_pattern THEN
    RAISE EXCEPTION
      'PC-PNDT: the foetal-sex guard now matches the patient''s own recorded sex, which DICOM PS3.3 (0010,0040) requires on every worklist entry and every stored object. Narrow the pattern — a guard that blocks lawful, required data is a guard somebody removes.';
  END IF;
END
$$;

-- ── the radiology report chain ──────────────────────────────────────────────
-- Same shape as `lab.lab_result_versions` and `clinical.document_versions`.
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_version_positive CHECK (version >= 1);
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_amendment_reason
  CHECK (version = 1 OR amendment_reason IS NOT NULL);
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_chain_root
  CHECK ((version = 1) = (prev_sha256 IS NULL));
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_sha_shape
  CHECK (content_sha256 ~ '^[0-9a-f]{64}$');
-- `OP-008 §5`: "Reports signed only by radiologists with valid registration."
-- A signed report names the registration number it was signed under, because
-- that is what prints and what an assessor checks.
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_signed_when_final
  CHECK (
    status IN ('draft', 'draft_for_cosign', 'cancelled')
    OR (signed_by IS NOT NULL AND signed_at IS NOT NULL AND sign_method IS NOT NULL
        AND signer_registration_no IS NOT NULL)
  );
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_cosign_pairing
  CHECK ((cosigner_user_id IS NULL) = (cosigned_at IS NULL));
-- A resident's draft awaiting co-signature cannot also be final.
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_cosign_before_final
  CHECK (status <> 'draft_for_cosign' OR signed_at IS NULL);
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_cancel_reason
  CHECK (status <> 'cancelled' OR cancelled_reason IS NOT NULL);
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_superseded_pairing
  CHECK ((superseded_by_version IS NULL) = (superseded_at IS NULL));
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_superseded_forward
  CHECK (superseded_by_version IS NULL OR superseded_by_version > version);
-- A final report says something. An impression is the part a clinician reads.
ALTER TABLE rad.rad_report_versions
  ADD CONSTRAINT rad_report_versions_impression_when_final
  CHECK (status NOT IN ('final', 'amended') OR length(btrim(COALESCE(impression_text, ''))) > 0);

CREATE OR REPLACE FUNCTION rad.seal_report_version()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_prev_hash  text;
  v_prev_found boolean;
  v_max        int;
BEGIN
  NEW.content_sha256 := encode(
    sha256(convert_to(
      jsonb_build_object(
        'report_id',       NEW.report_id,
        'version',         NEW.version,
        'content',         NEW.content,
        'findings_text',   NEW.findings_text,
        'impression_text', NEW.impression_text,
        'recommendations', NEW.recommendations,
        'finding_level',   NEW.finding_level::text,
        'bi_rads',         NEW.bi_rads,
        'ti_rads',         NEW.ti_rads,
        'li_rads',         NEW.li_rads,
        'pirads',          NEW.pirads,
        'measurements',    NEW.measurements,
        'amendment_reason',NEW.amendment_reason
      )::text, 'UTF8')),
    'hex');

  IF TG_OP = 'INSERT' THEN
    SELECT max(version) INTO v_max FROM rad.rad_report_versions WHERE report_id = NEW.report_id;
    IF NEW.version <> COALESCE(v_max, 0) + 1 THEN
      RAISE EXCEPTION
        'rad.rad_report_versions: report % is at version %, so the next version is % and not %',
        NEW.report_id, COALESCE(v_max, 0), COALESCE(v_max, 0) + 1, NEW.version
        USING ERRCODE = 'unique_violation';
    END IF;

    IF NEW.version > 1 THEN
      SELECT content_sha256, true INTO v_prev_hash, v_prev_found
      FROM rad.rad_report_versions
      WHERE report_id = NEW.report_id AND version = NEW.version - 1;

      IF NOT COALESCE(v_prev_found, false) THEN
        RAISE EXCEPTION 'rad.rad_report_versions: version % has no version % to chain to',
          NEW.version, NEW.version - 1
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      NEW.prev_sha256 := v_prev_hash;
    ELSE
      NEW.prev_sha256 := NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_rad_report_versions_seal ON rad.rad_report_versions;
CREATE TRIGGER trg_rad_report_versions_seal
  BEFORE INSERT OR UPDATE ON rad.rad_report_versions
  FOR EACH ROW EXECUTE FUNCTION rad.seal_report_version();

CREATE OR REPLACE FUNCTION rad.enforce_report_version_immutability()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION
      'rad.rad_report_versions is append-only: version % of report % cannot be deleted. An amendment is the next version, with a reason.',
      OLD.version, OLD.report_id
      USING ERRCODE = 'restrict_violation';
  END IF;

  IF OLD.status IN ('draft', 'draft_for_cosign') THEN
    RETURN NEW;
  END IF;

  IF NEW.content        IS DISTINCT FROM OLD.content
     OR NEW.findings_text   IS DISTINCT FROM OLD.findings_text
     OR NEW.impression_text IS DISTINCT FROM OLD.impression_text
     OR NEW.recommendations IS DISTINCT FROM OLD.recommendations
     OR NEW.finding_level   IS DISTINCT FROM OLD.finding_level
     OR NEW.content_sha256  IS DISTINCT FROM OLD.content_sha256
     OR NEW.prev_sha256     IS DISTINCT FROM OLD.prev_sha256
     OR NEW.version         IS DISTINCT FROM OLD.version
     OR NEW.report_id       IS DISTINCT FROM OLD.report_id
     OR NEW.signed_by       IS DISTINCT FROM OLD.signed_by
     OR NEW.signed_at       IS DISTINCT FROM OLD.signed_at
     OR NEW.signer_registration_no IS DISTINCT FROM OLD.signer_registration_no
     OR NEW.amendment_reason IS DISTINCT FROM OLD.amendment_reason
  THEN
    RAISE EXCEPTION
      'rad.rad_report_versions: version % of report % is % and immutable. Amend it by writing version % with a reason; the original stays.',
      OLD.version, OLD.report_id, OLD.status, OLD.version + 1
      USING ERRCODE = 'restrict_violation';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
     AND NOT (OLD.status IN ('preliminary', 'final') AND NEW.status IN ('final', 'amended', 'cancelled'))
  THEN
    RAISE EXCEPTION
      'rad.rad_report_versions: % cannot become % after signing', OLD.status, NEW.status
      USING ERRCODE = 'restrict_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_rad_report_versions_immutable ON rad.rad_report_versions;
CREATE TRIGGER trg_rad_report_versions_immutable
  BEFORE UPDATE OR DELETE ON rad.rad_report_versions
  FOR EACH ROW EXECUTE FUNCTION rad.enforce_report_version_immutability();

CREATE OR REPLACE FUNCTION rad.sync_report_head()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  UPDATE rad.rad_reports r
  SET current_version = head.version,
      current_status  = head.status,
      highest_finding_level = GREATEST(
        r.highest_finding_level,
        head.finding_level
      ),
      updated_at = now()
  FROM (
    SELECT v.version, v.status, v.finding_level
    FROM rad.rad_report_versions v
    WHERE v.report_id = NEW.report_id
    ORDER BY v.version DESC
    LIMIT 1
  ) AS head
  WHERE r.id = NEW.report_id
    AND (r.current_version IS DISTINCT FROM head.version
         OR r.current_status IS DISTINCT FROM head.status
         OR r.highest_finding_level < head.finding_level);
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_rad_report_versions_sync_head ON rad.rad_report_versions;
CREATE TRIGGER trg_rad_report_versions_sync_head
  AFTER INSERT OR UPDATE ON rad.rad_report_versions
  FOR EACH ROW EXECUTE FUNCTION rad.sync_report_head();

-- ── an ionising study is not signed off without a dose record ───────────────
-- `OP-008 §5`: "every ionising study must have a dose record (RDSR/header/manual)
-- before order closes". `EN-035 §5` repeats it as an AERB expectation. Enforced
-- at signature rather than at exam completion, because an RDSR object often
-- arrives seconds to minutes after the technologist marks the exam done, and a
-- block at the earlier moment would teach the department to enter a fake number.
CREATE OR REPLACE FUNCTION rad.enforce_dose_recorded()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_item      record;
  v_has_dose  boolean;
BEGIN
  IF NEW.status NOT IN ('final', 'amended') THEN RETURN NEW; END IF;

  SELECT i.is_ionising, i.procedure_name, r.exam_id
  INTO v_item
  FROM rad.rad_reports r
  JOIN rad.rad_order_items i ON i.id = r.order_item_id
  WHERE r.id = NEW.report_id;

  IF NOT COALESCE(v_item.is_ionising, false) OR v_item.exam_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM rad.rad_dose_records d WHERE d.exam_id = v_item.exam_id
  ) INTO v_has_dose;

  IF NOT v_has_dose THEN
    RAISE EXCEPTION
      'AERB: "%" is an ionising examination and no dose record exists for it. OP-008 §5 and EN-035 §5 require a dose figure from RDSR, the DICOM header, MPPS or a documented manual entry before the report is signed — the dose register is the evidence the hospital keeps, and a signed report without one is a gap in it.',
      v_item.procedure_name
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_rad_report_versions_dose ON rad.rad_report_versions;
CREATE TRIGGER trg_rad_report_versions_dose
  BEFORE INSERT OR UPDATE OF status ON rad.rad_report_versions
  FOR EACH ROW EXECUTE FUNCTION rad.enforce_dose_recorded();

-- ── critical findings must be communicated at or shortly after signature ────
-- `OP-008 §5`: "Critical findings require documented communication with read-back
-- before (or within 60 min after) sign." The database enforces the half it can:
-- a report version whose finding level is `critical` must have raised the
-- finding row by the time it is signed. The 60-minute grace on the *callback* is
-- an EN-037 escalation matter, not a storage one — and, exactly as with the lab,
-- the report itself is never withheld.
CREATE OR REPLACE FUNCTION rad.enforce_critical_finding_raised()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.status NOT IN ('final', 'amended') OR NEW.finding_level <> 'critical' THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM rad.rad_critical_findings f
    WHERE f.report_id = NEW.report_id AND f.level = 'critical'
  ) THEN
    RAISE EXCEPTION
      'OP-008 §5: this report records a critical finding, so a rad.rad_critical_findings row must exist before it is signed — that row is what the escalation ladder and the 60-minute NABH indicator are measured from. The report is not withheld; the finding must simply be on the board.'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_rad_report_versions_critical ON rad.rad_report_versions;
CREATE TRIGGER trg_rad_report_versions_critical
  BEFORE INSERT OR UPDATE OF status ON rad.rad_report_versions
  FOR EACH ROW EXECUTE FUNCTION rad.enforce_critical_finding_raised();

-- Worklists.
CREATE INDEX IF NOT EXISTS idx_rad_reports_unread
  ON rad.rad_reports (hospital_id, branch_id, created_at)
  WHERE current_status IN ('draft', 'draft_for_cosign', 'preliminary');
CREATE INDEX IF NOT EXISTS idx_rad_orders_awaiting_report
  ON rad.rad_orders (hospital_id, branch_id, priority, tat_due_at)
  WHERE status IN ('acquired', 'awaiting_report', 'preliminary');
CREATE INDEX IF NOT EXISTS idx_rad_follow_ups_open
  ON rad.rad_follow_up_recommendations (hospital_id, branch_id, due_at)
  WHERE status = 'open';

ALTER TABLE rad.rad_peer_reviews
  ADD CONSTRAINT rad_peer_reviews_score_range CHECK (score BETWEEN 1 AND 3);
ALTER TABLE rad.rad_peer_reviews
  ADD CONSTRAINT rad_peer_reviews_discrepancy
  CHECK (discrepancy_type IN ('none', 'minor', 'major'));
ALTER TABLE rad.rad_peer_reviews
  ADD CONSTRAINT rad_peer_reviews_prelim_pairing
  CHECK (is_prelim_final_comparison = false OR (prelim_version IS NOT NULL AND final_version IS NOT NULL));
ALTER TABLE rad.rad_follow_up_recommendations
  ADD CONSTRAINT rad_follow_up_recommendations_status
  CHECK (status IN ('open', 'scheduled', 'completed', 'declined', 'lost_to_followup'));
ALTER TABLE rad.rad_follow_up_recommendations
  ADD CONSTRAINT rad_follow_up_recommendations_close_reason
  CHECK (status = 'open' OR closed_at IS NOT NULL);
ALTER TABLE rad.rad_teleradiology_assignments
  ADD CONSTRAINT rad_teleradiology_assignments_reader
  CHECK (radiologist_user_id IS NOT NULL OR partner_name IS NOT NULL);
-- `EN-035 §5`: "the external provider is a DPDP processor with a DPA … and the
-- reporting radiologist's identity and registration number appear on the signed
-- report." Both are required before a study leaves the hospital's boundary.
ALTER TABLE rad.rad_teleradiology_assignments
  ADD CONSTRAINT rad_teleradiology_assignments_partner_dpa
  CHECK (
    partner_name IS NULL
    OR (partner_dpa_signed_at IS NOT NULL AND partner_registration_no IS NOT NULL)
  );
ALTER TABLE rad.rad_appointments
  ADD CONSTRAINT rad_appointments_time_order CHECK (end_at > start_at);
ALTER TABLE rad.rad_appointments
  ADD CONSTRAINT rad_appointments_status
  CHECK (status IN ('booked', 'confirmed', 'arrived', 'in_progress', 'completed', 'cancelled', 'no_show', 'rescheduled'));
ALTER TABLE rad.rad_order_events
  ADD CONSTRAINT rad_order_events_manual_reason
  CHECK (is_manual_override = false OR reason IS NOT NULL);


-- ── C.8 the PACS index ──────────────────────────────────────────────────────
--
-- `EN-008 §5`: "Study auto-links only when accession matches; fallback match
-- creates `reconciliation_status = needs_review` (**never silently attach to
-- wrong patient**)." That sentence is the whole reason `pacs_studies.patient_id`
-- is nullable and the reconciliation status defaults to `needs_review`: a study
-- that arrives without a confident match has no patient, rather than a guessed
-- one. The same principle as the analyzer unmatched queue in EN-004, and for the
-- same reason — a result on the wrong patient is worse than a result nobody can
-- find.

-- A study matched by anything other than the accession or the study UID must be
-- reviewed by a human. A study with a patient must say how it got one.
ALTER TABLE rad.pacs_studies
  ADD CONSTRAINT pacs_studies_match_requires_review
  CHECK (
    matched_by IN ('accession', 'study_uid', 'mwl', 'manual')
    OR reconciliation_status = 'needs_review'
  );
ALTER TABLE rad.pacs_studies
  ADD CONSTRAINT pacs_studies_patient_requires_basis
  CHECK ((patient_id IS NULL) = (matched_by = 'unmatched'));
ALTER TABLE rad.pacs_studies
  ADD CONSTRAINT pacs_studies_uid_shape
  CHECK (study_instance_uid ~ '^[0-9]+(\.[0-9]+)+$');
ALTER TABLE rad.pacs_studies
  ADD CONSTRAINT pacs_studies_counts_non_negative
  CHECK (series_count >= 0 AND instance_count >= 0 AND size_bytes >= 0);
ALTER TABLE rad.pacs_studies
  ADD CONSTRAINT pacs_studies_legal_hold_reason
  CHECK (legal_hold = false OR legal_hold_reason IS NOT NULL);
-- `EN-008 §5`: "never purge MLC/legal-hold".
ALTER TABLE rad.pacs_studies
  ADD CONSTRAINT pacs_studies_never_purge_protected
  CHECK (purged_at IS NULL OR (is_mlc = false AND legal_hold = false));
ALTER TABLE rad.pacs_studies
  ADD CONSTRAINT pacs_studies_purged_pairing
  CHECK ((status = 'purged') = (purged_at IS NOT NULL));

CREATE INDEX IF NOT EXISTS idx_pacs_studies_needs_review
  ON rad.pacs_studies (hospital_id, branch_id, created_at)
  WHERE reconciliation_status = 'needs_review';

ALTER TABLE rad.pacs_series
  ADD CONSTRAINT pacs_series_uid_shape
  CHECK (series_instance_uid ~ '^[0-9]+(\.[0-9]+)+$');
ALTER TABLE rad.pacs_series
  ADD CONSTRAINT pacs_series_counts_non_negative
  CHECK (instance_count >= 0 AND size_bytes >= 0);
ALTER TABLE rad.pacs_series
  ADD CONSTRAINT pacs_series_rejection_reason
  CHECK (is_rejected = false OR rejection_reason IS NOT NULL);
ALTER TABLE rad.pacs_instances
  ADD CONSTRAINT pacs_instances_uid_shape
  CHECK (sop_instance_uid ~ '^[0-9]+(\.[0-9]+)+$');
ALTER TABLE rad.pacs_instances
  ADD CONSTRAINT pacs_instances_size_non_negative CHECK (size_bytes >= 0);

-- `EN-035 §5`: "Cancelled or rescheduled orders must be withdrawn from MWL
-- within 60 seconds so a patient is never scanned against a cancelled order."
-- The withdrawal is a fact with a time and a reason.
ALTER TABLE rad.pacs_mwl_entries
  ADD CONSTRAINT pacs_mwl_entries_status
  CHECK (status IN ('pending', 'queried', 'in_progress', 'completed', 'cancelled', 'expired'));
ALTER TABLE rad.pacs_mwl_entries
  ADD CONSTRAINT pacs_mwl_entries_withdrawal_pairing
  CHECK ((status IN ('cancelled', 'expired')) = (withdrawn_at IS NOT NULL));
ALTER TABLE rad.pacs_mwl_entries
  ADD CONSTRAINT pacs_mwl_entries_withdrawal_reason
  CHECK (withdrawn_at IS NULL OR withdrawn_reason IS NOT NULL);
ALTER TABLE rad.pacs_mwl_entries
  ADD CONSTRAINT pacs_mwl_entries_query_count_non_negative CHECK (query_count >= 0);
-- DICOM PS3.3 (0010,0040) Patient's Sex: M, F, O or empty. The patient's own
-- recorded sex, required on every worklist entry — see the PC-PNDT guard in C.7,
-- which is written specifically so that this legitimate field is not caught by it.
ALTER TABLE rad.pacs_mwl_entries
  ADD CONSTRAINT pacs_mwl_entries_dicom_sex
  CHECK (patient_sex_dicom IS NULL OR patient_sex_dicom IN ('M', 'F', 'O'));

CREATE INDEX IF NOT EXISTS idx_pacs_mwl_entries_active
  ON rad.pacs_mwl_entries (hospital_id, modality_aet, scheduled_at)
  WHERE status IN ('pending', 'queried', 'in_progress');

ALTER TABLE rad.pacs_mpps_events
  ADD CONSTRAINT pacs_mpps_events_status
  CHECK (status IN ('IN PROGRESS', 'COMPLETED', 'DISCONTINUED'));
ALTER TABLE rad.pacs_mpps_events
  ADD CONSTRAINT pacs_mpps_events_discontinue_reason
  CHECK (status <> 'DISCONTINUED' OR discontinue_reason IS NOT NULL);

-- `EN-008 §3.3`: a correction to a stored study is the most consequential
-- operation in a PACS, and it always carries a reason and a person.
ALTER TABLE rad.pacs_corrections
  ADD CONSTRAINT pacs_corrections_type
  CHECK (type IN ('reassign_patient', 'merge', 'split', 'tag_fix', 'reject', 'accession_fix'));
ALTER TABLE rad.pacs_corrections
  ADD CONSTRAINT pacs_corrections_reason_present CHECK (length(btrim(reason)) > 0);
-- Reassigning a study to a different patient needs a second pair of eyes. It is
-- the operation that, done wrong, puts one patient's imaging in another's chart.
ALTER TABLE rad.pacs_corrections
  ADD CONSTRAINT pacs_corrections_reassign_approved
  CHECK (type NOT IN ('reassign_patient', 'merge') OR approved_by IS NOT NULL);

ALTER TABLE rad.pacs_access_tokens
  ADD CONSTRAINT pacs_access_tokens_scope CHECK (scope IN ('view', 'download'));
ALTER TABLE rad.pacs_access_tokens
  ADD CONSTRAINT pacs_access_tokens_purpose
  CHECK (purpose IN ('care', 'break_glass', 'patient_share', 'telerad', 'audit'));
-- `EN-008 §5`: "break-glass (outside care team) requires reason".
ALTER TABLE rad.pacs_access_tokens
  ADD CONSTRAINT pacs_access_tokens_break_glass_reason
  CHECK ((purpose = 'break_glass') = (break_glass_reason IS NOT NULL));
ALTER TABLE rad.pacs_access_tokens
  ADD CONSTRAINT pacs_access_tokens_subject
  CHECK (user_id IS NOT NULL OR patient_id IS NOT NULL);
-- A token is short-lived by construction. `EN-008 §5`: "signed short-lived
-- tokens" — a token that outlives the episode is a permanent grant with a fancy
-- name.
ALTER TABLE rad.pacs_access_tokens
  ADD CONSTRAINT pacs_access_tokens_expiry_forward CHECK (expires_at > issued_at);
ALTER TABLE rad.pacs_access_tokens
  ADD CONSTRAINT pacs_access_tokens_short_lived
  CHECK (expires_at <= issued_at + interval '24 hours');
ALTER TABLE rad.pacs_access_tokens
  ADD CONSTRAINT pacs_access_tokens_use_non_negative CHECK (use_count >= 0);

ALTER TABLE rad.pacs_view_audit
  ADD CONSTRAINT pacs_view_audit_break_glass_reason
  CHECK (purpose IS DISTINCT FROM 'break_glass' OR break_glass_reason IS NOT NULL);
ALTER TABLE rad.pacs_view_audit
  ADD CONSTRAINT pacs_view_audit_actor
  CHECK (user_id IS NOT NULL OR token_id IS NOT NULL);

-- `EN-008 §5`: "Share links: consent mandatory (patient or guardian), OTP to
-- registered mobile, max 7 days/10 views default, revocable".
ALTER TABLE rad.pacs_share_links
  ADD CONSTRAINT pacs_share_links_channel
  CHECK (channel IN ('patient', 'referrer', 'telerad', 'insurer'));
ALTER TABLE rad.pacs_share_links
  ADD CONSTRAINT pacs_share_links_expiry_forward CHECK (expires_at > created_at);
ALTER TABLE rad.pacs_share_links
  ADD CONSTRAINT pacs_share_links_max_window
  CHECK (expires_at <= created_at + interval '30 days');
ALTER TABLE rad.pacs_share_links
  ADD CONSTRAINT pacs_share_links_views_range CHECK (max_views > 0 AND views >= 0);
ALTER TABLE rad.pacs_share_links
  ADD CONSTRAINT pacs_share_links_revoke_reason
  CHECK ((revoked_at IS NULL) = (revoked_by IS NULL));
ALTER TABLE rad.pacs_share_links
  ADD CONSTRAINT pacs_share_links_studies_present
  CHECK (cardinality(study_ids) > 0);

ALTER TABLE rad.pacs_media_issues
  ADD CONSTRAINT pacs_media_issues_type CHECK (media_type IN ('cd', 'dvd', 'usb', 'iso'));
ALTER TABLE rad.pacs_media_issues
  ADD CONSTRAINT pacs_media_issues_studies_present CHECK (cardinality(study_ids) > 0);

ALTER TABLE rad.pacs_retention_policies
  ADD CONSTRAINT pacs_retention_policies_class
  CHECK (patient_class IN ('adult', 'minor', 'mlc', 'research', 'all'));
ALTER TABLE rad.pacs_retention_policies
  ADD CONSTRAINT pacs_retention_policies_days_order
  CHECK (hot_days >= 0 AND warm_days >= hot_days AND retain_years >= 1);
-- `EN-008 §5`: "never purge MLC/legal-hold". Not a default — a constraint, so a
-- policy that would do it cannot be saved.
ALTER TABLE rad.pacs_retention_policies
  ADD CONSTRAINT pacs_retention_policies_never_purge_mlc
  CHECK (never_purge_mlc = true);
ALTER TABLE rad.pacs_retention_policies
  ADD CONSTRAINT pacs_retention_policies_minor_rule
  CHECK (
    patient_class <> 'minor'
    OR (minor_retain_until_age IS NOT NULL AND minor_extra_years IS NOT NULL)
  );

-- `EN-008 §5`: "purge requires two approvals". Two, and they are two different
-- people — one person clicking twice is one approval.
ALTER TABLE rad.pacs_purge_runs
  ADD CONSTRAINT pacs_purge_runs_status
  CHECK (status IN ('planned', 'approved', 'executing', 'completed', 'aborted'));
ALTER TABLE rad.pacs_purge_runs
  ADD CONSTRAINT pacs_purge_runs_two_approvers
  CHECK (
    status = 'planned'
    OR status = 'aborted'
    OR (approved_by_1 IS NOT NULL AND approved_by_2 IS NOT NULL AND approved_by_1 <> approved_by_2)
  );
ALTER TABLE rad.pacs_purge_runs
  ADD CONSTRAINT pacs_purge_runs_approval_pairing
  CHECK ((approved_by_1 IS NULL) = (approved_at_1 IS NULL) AND (approved_by_2 IS NULL) = (approved_at_2 IS NULL));
ALTER TABLE rad.pacs_purge_runs
  ADD CONSTRAINT pacs_purge_runs_abort_reason
  CHECK (status <> 'aborted' OR abort_reason IS NOT NULL);
ALTER TABLE rad.pacs_purge_runs
  ADD CONSTRAINT pacs_purge_runs_execution_pairing
  CHECK ((status = 'completed') = (executed_at IS NOT NULL));

ALTER TABLE rad.pacs_servers
  ADD CONSTRAINT pacs_servers_role CHECK (role IN ('primary', 'replica', 'central', 'partner'));
ALTER TABLE rad.pacs_modalities
  ADD CONSTRAINT pacs_modalities_dose_capture
  CHECK (dose_capture IN ('rdsr', 'header', 'ocr', 'manual'));
ALTER TABLE rad.pacs_priors_map
  ADD CONSTRAINT pacs_priors_map_lookback_positive
  CHECK (lookback_days > 0 AND max_priors > 0);


-- ── C.9 analyzer interfacing ────────────────────────────────────────────────
--
-- `docs/prompts/phase-03 §Constraints`: "Never let a result exist without a
-- patient identity check. Unmatched analyzer results go to a queue, never
-- auto-assigned by name similarity."

ALTER TABLE integration.lab_instruments
  ADD CONSTRAINT lab_instruments_retention_positive CHECK (raw_retention_days > 0);
ALTER TABLE integration.lab_instruments
  ADD CONSTRAINT lab_instruments_buffering_pairing
  CHECK ((is_buffering = false) OR buffered_since IS NOT NULL);
ALTER TABLE integration.lab_instruments
  ADD CONSTRAINT lab_instruments_buffered_non_negative CHECK (buffered_count >= 0);
-- `EN-004 §5`: "Only `live` instruments receive orders/produce patient results."
-- The status vocabulary is what makes that enforceable at all, and a serial
-- number is what makes an instrument identifiable in a QA record.
ALTER TABLE integration.lab_instruments
  ADD CONSTRAINT lab_instruments_live_needs_serial
  CHECK (status <> 'live' OR (serial IS NOT NULL AND length(btrim(serial)) > 0));

ALTER TABLE integration.lab_instrument_test_maps
  ADD CONSTRAINT lab_instrument_test_maps_factor_non_zero
  CHECK (unit_factor IS NULL OR unit_factor <> 0);
ALTER TABLE integration.lab_instrument_test_maps
  ADD CONSTRAINT lab_instrument_test_maps_precision_range
  CHECK (precision IS NULL OR (precision >= 0 AND precision <= 8));

ALTER TABLE integration.lab_if_messages
  ADD CONSTRAINT lab_if_messages_attempts_non_negative CHECK (attempts >= 0);
ALTER TABLE integration.lab_if_messages
  ADD CONSTRAINT lab_if_messages_error_text
  CHECK (status <> 'error' OR error_text IS NOT NULL);
-- `EN-004 §5`: "Message logs retained 90 days raw (encrypted), 2 years parsed
-- metadata." A purged message keeps its metadata and loses only the bytes.
ALTER TABLE integration.lab_if_messages
  ADD CONSTRAINT lab_if_messages_purge_pairing
  CHECK (raw_purged_at IS NULL OR raw IS NULL);
ALTER TABLE integration.lab_if_messages
  ADD CONSTRAINT lab_if_messages_sha_shape
  CHECK (content_sha256 IS NULL OR content_sha256 ~ '^[0-9a-f]{64}$');

-- The replay path: buffered frames, oldest first. `phase-03` exit gate 7 is
-- exactly this query — 30 minutes of buffered messages, replayed with zero loss.
CREATE INDEX IF NOT EXISTS idx_lab_if_messages_buffered
  ON integration.lab_if_messages (hospital_id, instrument_id, received_at)
  WHERE status = 'buffered';
-- Idempotency on replay: the same frame arriving twice is recognised rather than
-- re-applied. `NULLS NOT DISTINCT` is wrong here — a message with no control id
-- and no digest is genuinely unidentifiable and must not collide with another —
-- so this is a partial index over the rows that can be identified.
CREATE UNIQUE INDEX IF NOT EXISTS uq_lab_if_messages_idempotency
  ON integration.lab_if_messages (hospital_id, instrument_id, direction, control_id, content_sha256, received_at)
  WHERE control_id IS NOT NULL AND content_sha256 IS NOT NULL;

ALTER TABLE integration.lab_if_error_queue
  ADD CONSTRAINT lab_if_error_queue_status
  CHECK (status IN ('open', 'assigned', 'rejected', 'auto_resolved'));
-- A resolution names a person and a moment. "It sorted itself out" is not a
-- state — and the one automatic outcome, `auto_resolved`, is reserved for a
-- duplicate frame whose digest matches one already applied, which is the only
-- case where no judgement was exercised.
ALTER TABLE integration.lab_if_error_queue
  ADD CONSTRAINT lab_if_error_queue_resolution_attributed
  CHECK (
    status IN ('open', 'assigned')
    OR status = 'auto_resolved'
    OR (resolved_by IS NOT NULL AND resolved_at IS NOT NULL AND resolution IS NOT NULL)
  );
-- A resolved-to-sample assignment is the moment a result acquires a patient. It
-- is never automatic: the suggestion is shown, a human accepts it, and the
-- acceptance is recorded.
ALTER TABLE integration.lab_if_error_queue
  ADD CONSTRAINT lab_if_error_queue_assignment_is_human
  CHECK (resolved_sample_id IS NULL OR resolved_by IS NOT NULL);

COMMENT ON CONSTRAINT lab_if_error_queue_assignment_is_human ON integration.lab_if_error_queue IS
  'docs/prompts/phase-03 §Constraints: "Unmatched analyzer results go to a queue, never auto-assigned by name similarity." `suggested_sample_id` may be computed; `resolved_sample_id` may only be set by a person, and this is what makes that a property of the data rather than a property of the code that happens to be running.';

CREATE INDEX IF NOT EXISTS idx_lab_if_error_queue_open
  ON integration.lab_if_error_queue (hospital_id, branch_id, created_at)
  WHERE status IN ('open', 'assigned');

ALTER TABLE integration.lab_if_autoval_rulesets
  ADD CONSTRAINT lab_if_autoval_rulesets_status
  CHECK (status IN ('draft', 'active', 'retired'));
-- `EN-004 §5`: "Auto-validation only for tests with active, signed rule sets …
-- rule set edits require QM approval + pathologist sign."
ALTER TABLE integration.lab_if_autoval_rulesets
  ADD CONSTRAINT lab_if_autoval_rulesets_active_signed
  CHECK (
    status <> 'active'
    OR (approved_by IS NOT NULL AND approved_at IS NOT NULL
        AND signed_by IS NOT NULL AND signed_at IS NOT NULL AND sign_method IS NOT NULL)
  );
ALTER TABLE integration.lab_if_autoval_rulesets
  ADD CONSTRAINT lab_if_autoval_rulesets_checksum_shape
  CHECK (checksum ~ '^[0-9a-f]{64}$');
ALTER TABLE integration.lab_if_autoval_rulesets
  ADD CONSTRAINT lab_if_autoval_rulesets_version_positive CHECK (version >= 1);
ALTER TABLE integration.lab_if_autoval_rulesets
  ADD CONSTRAINT lab_if_autoval_rulesets_effective_order
  CHECK (effective_to IS NULL OR effective_to > effective_from);

ALTER TABLE integration.lab_if_autoval_decisions
  ADD CONSTRAINT lab_if_autoval_decisions_outcome
  CHECK (outcome IN ('auto_verified', 'auto_final', 'exception'));
-- An exception names the rules that refused. "It went to a human and we do not
-- know why" is not the NABL traceability `EN-004 §5` requires.
ALTER TABLE integration.lab_if_autoval_decisions
  ADD CONSTRAINT lab_if_autoval_decisions_exception_explained
  CHECK (outcome <> 'exception' OR failed_rules IS NOT NULL);
ALTER TABLE integration.lab_if_autoval_decisions
  ADD CONSTRAINT lab_if_autoval_decisions_auto_clean
  CHECK (outcome = 'exception' OR failed_rules IS NULL OR failed_rules = '[]'::jsonb);

ALTER TABLE integration.lab_instrument_downtime
  ADD CONSTRAINT lab_instrument_downtime_type
  CHECK (type IN ('comm', 'breakdown', 'pm', 'reagent', 'other'));
ALTER TABLE integration.lab_instrument_downtime
  ADD CONSTRAINT lab_instrument_downtime_source CHECK (source IN ('auto', 'manual'));
ALTER TABLE integration.lab_instrument_downtime
  ADD CONSTRAINT lab_instrument_downtime_time_order
  CHECK (end_at IS NULL OR end_at >= start_at);
ALTER TABLE integration.lab_instrument_downtime
  ADD CONSTRAINT lab_instrument_downtime_counts_non_negative
  CHECK (buffered_count >= 0 AND replayed_count >= 0 AND lost_count >= 0);
-- `phase-03` exit gate 7: "messages buffer and replay with zero loss". The
-- arithmetic has to close — a downtime that replayed more than it buffered, or
-- that lost frames it never counted, is a report nobody can act on.
ALTER TABLE integration.lab_instrument_downtime
  ADD CONSTRAINT lab_instrument_downtime_replay_accounts
  CHECK (end_at IS NULL OR replayed_count + lost_count = buffered_count);

COMMENT ON CONSTRAINT lab_instrument_downtime_replay_accounts ON integration.lab_instrument_downtime IS
  'phase-03 exit gate 7: an analyzer disconnected for 30 minutes buffers and replays with zero loss. Closing a downtime therefore has to account for every buffered frame as replayed or lost — a gap in the arithmetic is a gap in the evidence, and "lost" being explicit is what makes zero loss a claim somebody can check.';

ALTER TABLE integration.lab_interface_verifications
  ADD CONSTRAINT lab_interface_verifications_counts
  CHECK (samples_compared > 0 AND discrepancies >= 0 AND discrepancies <= samples_compared);

-- NULLS NOT DISTINCT uniqueness, for the same reason as the QC tables in C.4.
CREATE UNIQUE INDEX IF NOT EXISTS uq_lab_instrument_test_maps_key
  ON integration.lab_instrument_test_maps (instrument_id, instrument_code, instrument_sample_type_code) NULLS NOT DISTINCT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_lab_if_autoval_rulesets_key
  ON integration.lab_if_autoval_rulesets (hospital_id, test_key, parameter_key, instrument_id, version) NULLS NOT DISTINCT;


-- ── C.10 the investigation console ──────────────────────────────────────────
ALTER TABLE clinical.investigation_studies
  ADD CONSTRAINT investigation_studies_cancel_reason
  CHECK (status <> 'cancelled' OR cancel_reason IS NOT NULL);
-- `OP-022 §5`: "Identity verification (scan/2-identifier) before capture."
ALTER TABLE clinical.investigation_studies
  ADD CONSTRAINT investigation_studies_identity_before_capture
  CHECK (performed_at IS NULL OR identity_verified);
ALTER TABLE clinical.investigation_studies
  ADD CONSTRAINT investigation_studies_repeat_reason
  CHECK (repeat_flag = false OR repeat_reason IS NOT NULL);
-- `OP-022 §5`: "Radiation investigations (dental X-ray, fluoro stills) log dose
-- via OP-008 dose register." A performed ionising study names the dose record.
ALTER TABLE clinical.investigation_studies
  ADD CONSTRAINT investigation_studies_dose_recorded
  CHECK (is_ionising = false OR performed_at IS NULL OR dose_record_ref IS NOT NULL);

ALTER TABLE clinical.investigation_media
  ADD CONSTRAINT investigation_media_size_non_negative CHECK (size_bytes >= 0);
-- `OP-022 §5`: "detach/move requires reason & audit; deletion soft only."
ALTER TABLE clinical.investigation_media
  ADD CONSTRAINT investigation_media_detach_evidence
  CHECK ((detached_at IS NULL) = (detach_reason IS NULL) AND (detached_at IS NULL) = (detached_by IS NULL));
ALTER TABLE clinical.investigation_media
  ADD CONSTRAINT investigation_media_delete_reason
  CHECK ((deleted_at IS NULL) = (delete_reason IS NULL));
-- `OP-022 §5`: "orphan uploads quarantined for matching (24 h) then flagged."
ALTER TABLE clinical.investigation_media
  ADD CONSTRAINT investigation_media_quarantine_deadline
  CHECK ((is_quarantined = false) = (quarantine_until IS NULL));

ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_version_positive CHECK (version >= 1);
ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_amendment_reason
  CHECK (version = 1 OR amendment_reason IS NOT NULL);
ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_chain_root
  CHECK ((version = 1) = (prev_sha256 IS NULL));
ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_sha_shape
  CHECK (content_sha256 ~ '^[0-9a-f]{64}$');
ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_signed_when_final
  CHECK (
    status IN ('draft', 'draft_for_cosign', 'cancelled')
    OR (signed_by IS NOT NULL AND signed_at IS NOT NULL AND sign_method IS NOT NULL)
  );
ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_cosign_pairing
  CHECK ((cosigner_user_id IS NULL) = (cosigned_at IS NULL));
ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_discrepancy
  CHECK (discrepancy IS NULL OR discrepancy IN ('none', 'minor', 'major'));
ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_cancel_reason
  CHECK (status <> 'cancelled' OR cancelled_reason IS NOT NULL);
-- `OP-022 §5`: "critical flag → notification recorded before final (or within
-- 15 min after with ack)". The reference is required at signature; the 15-minute
-- grace is an EN-037 escalation matter and, as everywhere else in this phase,
-- the report is not withheld.
ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_critical_ack
  CHECK (critical = false OR status NOT IN ('final', 'amended') OR critical_ack_ref IS NOT NULL);
-- `OP-022 §5`: the PC-PNDT keyword validator's verdict is recorded, and a
-- failure may only be overridden by a named authorised doctor with a reason.
ALTER TABLE clinical.investigation_report_versions
  ADD CONSTRAINT investigation_report_versions_pcpndt_override
  CHECK ((pcpndt_override_by IS NULL) = (pcpndt_override_reason IS NULL));

CREATE OR REPLACE FUNCTION clinical.seal_investigation_report_version()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_prev text;
  v_found boolean;
  v_max int;
BEGIN
  NEW.content_sha256 := encode(
    sha256(convert_to(
      jsonb_build_object(
        'report_id',        NEW.report_id,
        'version',          NEW.version,
        'body',             NEW.body,
        'impression',       NEW.impression,
        'critical',         NEW.critical,
        'amendment_reason', NEW.amendment_reason
      )::text, 'UTF8')),
    'hex');

  IF TG_OP = 'INSERT' THEN
    SELECT max(version) INTO v_max FROM clinical.investigation_report_versions WHERE report_id = NEW.report_id;
    IF NEW.version <> COALESCE(v_max, 0) + 1 THEN
      RAISE EXCEPTION
        'clinical.investigation_report_versions: report % is at version %, so the next version is % and not %',
        NEW.report_id, COALESCE(v_max, 0), COALESCE(v_max, 0) + 1, NEW.version
        USING ERRCODE = 'unique_violation';
    END IF;
    IF NEW.version > 1 THEN
      SELECT content_sha256, true INTO v_prev, v_found
      FROM clinical.investigation_report_versions
      WHERE report_id = NEW.report_id AND version = NEW.version - 1;
      IF NOT COALESCE(v_found, false) THEN
        RAISE EXCEPTION 'clinical.investigation_report_versions: no version % to chain to', NEW.version - 1
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      NEW.prev_sha256 := v_prev;
    ELSE
      NEW.prev_sha256 := NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_investigation_report_versions_seal ON clinical.investigation_report_versions;
CREATE TRIGGER trg_investigation_report_versions_seal
  BEFORE INSERT OR UPDATE ON clinical.investigation_report_versions
  FOR EACH ROW EXECUTE FUNCTION clinical.seal_investigation_report_version();

CREATE OR REPLACE FUNCTION clinical.enforce_investigation_report_immutability()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION
      'clinical.investigation_report_versions is append-only: version % cannot be deleted', OLD.version
      USING ERRCODE = 'restrict_violation';
  END IF;

  IF OLD.status IN ('draft', 'draft_for_cosign') THEN
    RETURN NEW;
  END IF;

  IF NEW.body IS DISTINCT FROM OLD.body
     OR NEW.impression IS DISTINCT FROM OLD.impression
     OR NEW.critical IS DISTINCT FROM OLD.critical
     OR NEW.content_sha256 IS DISTINCT FROM OLD.content_sha256
     OR NEW.prev_sha256 IS DISTINCT FROM OLD.prev_sha256
     OR NEW.version IS DISTINCT FROM OLD.version
     OR NEW.report_id IS DISTINCT FROM OLD.report_id
     OR NEW.signed_by IS DISTINCT FROM OLD.signed_by
     OR NEW.signed_at IS DISTINCT FROM OLD.signed_at
     OR NEW.amendment_reason IS DISTINCT FROM OLD.amendment_reason
  THEN
    RAISE EXCEPTION
      'clinical.investigation_report_versions: version % is % and immutable. Amend it by writing version % with a reason.',
      OLD.version, OLD.status, OLD.version + 1
      USING ERRCODE = 'restrict_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_investigation_report_versions_immutable ON clinical.investigation_report_versions;
CREATE TRIGGER trg_investigation_report_versions_immutable
  BEFORE UPDATE OR DELETE ON clinical.investigation_report_versions
  FOR EACH ROW EXECUTE FUNCTION clinical.enforce_investigation_report_immutability();

CREATE OR REPLACE FUNCTION clinical.sync_investigation_report_head()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  UPDATE clinical.investigation_reports r
  SET current_version = head.version,
      current_status  = head.status,
      ever_critical   = r.ever_critical OR head.critical,
      updated_at      = now()
  FROM (
    SELECT v.version, v.status, v.critical
    FROM clinical.investigation_report_versions v
    WHERE v.report_id = NEW.report_id
    ORDER BY v.version DESC
    LIMIT 1
  ) AS head
  WHERE r.id = NEW.report_id
    AND (r.current_version IS DISTINCT FROM head.version
         OR r.current_status IS DISTINCT FROM head.status
         OR (head.critical AND NOT r.ever_critical));
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_investigation_report_versions_sync_head ON clinical.investigation_report_versions;
CREATE TRIGGER trg_investigation_report_versions_sync_head
  AFTER INSERT OR UPDATE ON clinical.investigation_report_versions
  FOR EACH ROW EXECUTE FUNCTION clinical.sync_investigation_report_head();

-- `OP-022 §5`: "residents cannot finalise services with `cosign_required`".
CREATE OR REPLACE FUNCTION clinical.enforce_investigation_cosign()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_required boolean;
BEGIN
  IF NEW.status NOT IN ('final', 'amended') THEN RETURN NEW; END IF;

  SELECT cosign_required INTO v_required
  FROM clinical.investigation_reports WHERE id = NEW.report_id;

  IF COALESCE(v_required, false) AND NEW.cosigner_user_id IS NULL THEN
    RAISE EXCEPTION
      'clinical.investigation_report_versions: this service requires a consultant countersignature before the report is final (OP-022 §5). A resident''s draft becomes final when the consultant co-signs it, not before.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.cosigner_user_id IS NOT NULL AND NEW.cosigner_user_id = NEW.author_user_id THEN
    RAISE EXCEPTION
      'clinical.investigation_report_versions: a report cannot be countersigned by its own author — that is a signature, not a countersignature.'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_investigation_report_versions_cosign ON clinical.investigation_report_versions;
CREATE TRIGGER trg_investigation_report_versions_cosign
  BEFORE INSERT OR UPDATE OF status ON clinical.investigation_report_versions
  FOR EACH ROW EXECUTE FUNCTION clinical.enforce_investigation_cosign();

CREATE INDEX IF NOT EXISTS idx_investigation_studies_worklist
  ON clinical.investigation_studies (hospital_id, branch_id, status, priority, tat_due_at)
  WHERE status NOT IN ('reported', 'cancelled');
CREATE INDEX IF NOT EXISTS idx_investigation_media_quarantined
  ON clinical.investigation_media (hospital_id, quarantine_until)
  WHERE is_quarantined;


-- ═════════════════════════════════════════════════════════════════════════════
-- §D. GRANTS AND APPEND-ONLY ENFORCEMENT
--
-- The `ALTER DEFAULT PRIVILEGES` in §B.2 covers everything `hms_migrator`
-- creates in `lab` and `rad` **from that point on** — which is not these tables,
-- because Prisma created them before §B ran. `core`, `mdm`, `clinical` and
-- `integration` were already covered by the Phase-0 and Phase-1 defaults, so
-- most of the other 23 arrived already granted. The loop below is the belt to
-- those braces: it grants only tables that hold no grant yet, for the same
-- reason as before — `GRANT ... ON ALL TABLES` would silently re-grant UPDATE
-- and DELETE on the append-only tables and undo every guarantee below it.
-- ═════════════════════════════════════════════════════════════════════════════
DO $$
DECLARE
  r record;
  v_count int := 0;
BEGIN
  FOR r IN
    SELECT n.nspname AS schema_name, c.relname AS table_name, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname IN ('core', 'mdm', 'patient', 'clinical', 'lab', 'rad', 'queue', 'engage', 'billing', 'integration')
      AND c.relkind IN ('r', 'p')
      AND c.relispartition = false
      AND c.relname NOT LIKE '\_prisma%'
      AND NOT has_table_privilege('hms_app', c.oid, 'SELECT')
  LOOP
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I.%I TO hms_app', r.schema_name, r.table_name);
    EXECUTE format('GRANT SELECT ON %I.%I TO hms_readonly', r.schema_name, r.table_name);
    v_count := v_count + 1;
  END LOOP;
  RAISE NOTICE 'Granted application DML on % previously ungranted table(s)', v_count;
END
$$;

-- ── 1. append-only evidence: INSERT and SELECT only ─────────────────────────
--    Each of these is a statement about something that happened. Editing one is
--    not a correction, it is a falsification — the correction is another row.
--
--    `lab_critical_value_callbacks` is the one that matters most in this phase.
--    It is the NABL record of a critical value having been communicated, and it
--    is the evidence that unlocks authorisation of the result. If it could be
--    edited, the whole D-10 arrangement would reduce to a checkbox somebody
--    ticks after the fact, which is exactly what "documented read-back" exists
--    to prevent.
REVOKE UPDATE, DELETE ON lab.lab_critical_value_callbacks FROM hms_app;
REVOKE UPDATE, DELETE ON rad.rad_critical_callbacks FROM hms_app;
REVOKE UPDATE, DELETE ON lab.lab_order_events FROM hms_app;
REVOKE UPDATE, DELETE ON lab.lab_sample_custody_events FROM hms_app;
REVOKE UPDATE, DELETE ON lab.lab_sample_labels FROM hms_app;
