REVOKE UPDATE, DELETE ON rad.rad_repeat_reject_events FROM hms_app;
REVOKE UPDATE, DELETE ON rad.pacs_corrections FROM hms_app;
REVOKE UPDATE, DELETE ON rad.pacs_view_audit FROM hms_app;
REVOKE UPDATE, DELETE ON rad.pacs_mpps_events FROM hms_app;
REVOKE UPDATE, DELETE ON rad.pacs_media_issues FROM hms_app;
REVOKE UPDATE, DELETE ON integration.lab_if_autoval_decisions FROM hms_app;
REVOKE UPDATE, DELETE ON clinical.investigation_annotations FROM hms_app;

-- `lab.lab_result_versions`, `rad.rad_report_versions` and
-- `clinical.investigation_report_versions` are append-only in the narrower sense
-- `clinical.document_versions` established: the immutability trigger permits
-- exactly the forward stamping of a review trail and a supersession, so UPDATE
-- stays granted and DELETE does not. The trigger is what makes the retained
-- UPDATE safe; the revoke is what makes the DELETE impossible even if the
-- trigger were dropped.
REVOKE DELETE ON lab.lab_result_versions FROM hms_app;
