-- **PC-PNDT Form F is never deleted, and never modified after the declarations
-- are signed.** The Form F register is the record the Appropriate Authority
-- inspects; a facility that can delete an entry has no register. The Rules
-- require it to be preserved for two years (policy here is five), and a
-- destroyed register is itself an offence under Section 29.
REVOKE DELETE ON rad.rad_form_f FROM hms_app;
REVOKE DELETE ON rad.rad_form_f_monthly_returns FROM hms_app;

CREATE OR REPLACE FUNCTION rad.enforce_form_f_immutability()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION
      'PC-PNDT: Form F % cannot be deleted. Section 29 of the Act requires the records to be preserved and produced on inspection; a register an operator can delete from is not a register.',
      OLD.form_serial_no
      USING ERRCODE = 'restrict_violation';
  END IF;

  -- Before both declarations are signed the form is being filled in and may
  -- change. Once signed it is the statutory record.
  IF NOT (OLD.woman_declaration_signed AND OLD.doctor_declaration_signed) THEN
    RETURN NEW;
  END IF;

  IF NEW.patient_name IS DISTINCT FROM OLD.patient_name
     OR NEW.patient_age_years IS DISTINCT FROM OLD.patient_age_years
     OR NEW.husband_or_father_name IS DISTINCT FROM OLD.husband_or_father_name
     OR NEW.full_address IS DISTINCT FROM OLD.full_address
     OR NEW.identity_document_type IS DISTINCT FROM OLD.identity_document_type
     OR NEW.identity_document_ref_masked IS DISTINCT FROM OLD.identity_document_ref_masked
     OR NEW.gravida IS DISTINCT FROM OLD.gravida
     OR NEW.para IS DISTINCT FROM OLD.para
     OR NEW.living_children IS DISTINCT FROM OLD.living_children
     OR NEW.previous_abortions IS DISTINCT FROM OLD.previous_abortions
     OR NEW.gestational_age_weeks IS DISTINCT FROM OLD.gestational_age_weeks
     OR NEW.last_menstrual_period IS DISTINCT FROM OLD.last_menstrual_period
     OR NEW.referring_doctor_name IS DISTINCT FROM OLD.referring_doctor_name
     OR NEW.indication_codes IS DISTINCT FROM OLD.indication_codes
     OR NEW.procedures_performed IS DISTINCT FROM OLD.procedures_performed
     OR NEW.facility_registration_no IS DISTINCT FROM OLD.facility_registration_no
     OR NEW.machine_registration_no IS DISTINCT FROM OLD.machine_registration_no
     OR NEW.performed_by_user_id IS DISTINCT FROM OLD.performed_by_user_id
     OR NEW.performed_by_registration_no IS DISTINCT FROM OLD.performed_by_registration_no
     OR NEW.performed_at IS DISTINCT FROM OLD.performed_at
     OR NEW.woman_declaration_signed IS DISTINCT FROM OLD.woman_declaration_signed
     OR NEW.doctor_declaration_signed IS DISTINCT FROM OLD.doctor_declaration_signed
     OR NEW.woman_declaration_doc_id IS DISTINCT FROM OLD.woman_declaration_doc_id
     OR NEW.doctor_declaration_doc_id IS DISTINCT FROM OLD.doctor_declaration_doc_id
  THEN
    RAISE EXCEPTION
      'PC-PNDT: Form F % is signed and is a statutory record. It cannot be altered — a correction is a matter for the Appropriate Authority, not an UPDATE.',
      OLD.form_serial_no
      USING ERRCODE = 'restrict_violation';
  END IF;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION rad.enforce_form_f_immutability IS
  'The Form F register, once signed, is the statutory record the Appropriate Authority inspects under the PC-PNDT Act. Only the return linkage and the scanned original may be attached afterwards; the substance cannot change and the row cannot be deleted.';

DROP TRIGGER IF EXISTS trg_rad_form_f_immutable ON rad.rad_form_f;
CREATE TRIGGER trg_rad_form_f_immutable
  BEFORE UPDATE OR DELETE ON rad.rad_form_f
  FOR EACH ROW EXECUTE FUNCTION rad.enforce_form_f_immutability();

-- ── 3. masters are retired, never deleted ───────────────────────────────────
-- EN-027 §5: "Masters are never hard-deleted — only retired." Twelve more join
-- the twenty-two already under the rule.
REVOKE DELETE ON mdm.mdm_lab_specimen_types FROM hms_app;
REVOKE DELETE ON mdm.mdm_lab_containers FROM hms_app;
REVOKE DELETE ON mdm.mdm_lab_tests FROM hms_app;
REVOKE DELETE ON mdm.mdm_lab_test_parameters FROM hms_app;
REVOKE DELETE ON mdm.mdm_lab_panel_members FROM hms_app;
REVOKE DELETE ON mdm.mdm_rad_procedures FROM hms_app;
REVOKE DELETE ON mdm.mdm_investigation_services FROM hms_app;
REVOKE DELETE ON lab.lab_rejection_reasons FROM hms_app;
REVOKE DELETE ON lab.lab_tat_targets FROM hms_app;
REVOKE DELETE ON lab.lab_referral_labs FROM hms_app;
REVOKE DELETE ON lab.lab_benches FROM hms_app;
-- `OP-004 §5`: "Reference ranges effective-dated; report prints the range used at
-- that time; changing master does not alter historical reports." A deleted range
-- is a report nobody can reproduce.
REVOKE DELETE ON lab.lab_reference_ranges FROM hms_app;
REVOKE DELETE ON lab.lab_delta_check_rules FROM hms_app;
REVOKE DELETE ON rad.rad_dose_k_factors FROM hms_app;
REVOKE DELETE ON rad.pacs_priors_map FROM hms_app;
REVOKE DELETE ON rad.pacs_routing_rules FROM hms_app;

-- ── 4. the retention role ───────────────────────────────────────────────────
--    Note what is NOT in this list. `lab.lab_results`, `lab.lab_result_versions`
--    and `lab.labq_qc_runs` are partitioned, but a result is a clinical record
--    with a ten-year retention and a QC run is accreditation evidence with a
--    five-year one (`EN-031 §4`), so no scheduled job may remove them. Their
--    partitions are detached by `hms_migrator` under an explicit release
--    procedure (docs/13), never by a sweeper. `rad.pacs_view_audit` is an access
--    log under the EN-024 retention policy and is likewise not swept from here.
--
--    Two tables are genuinely operational. `integration.lab_if_messages` holds
--    the raw HL7/ASTM frames, which `EN-004 §5` gives 90 days — and those frames
--    are PHI, because an ORU carries the patient's name and identifiers in PID,
--    so keeping them longer than the policy allows is itself a defect.
--    `integration.lab_if_worklist_cache` is a cache with an explicit expiry and
--    holds order payloads that exist elsewhere.
GRANT USAGE ON SCHEMA lab, rad TO hms_retention;
GRANT SELECT, UPDATE ON integration.lab_if_messages          TO hms_retention;
GRANT SELECT, DELETE ON integration.lab_if_worklist_cache    TO hms_retention;

DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT * FROM (VALUES
      ('integration', 'lab_if_messages'),
      ('integration', 'lab_if_worklist_cache')
    ) AS t(schema_name, table_name)
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS retention_all_tenants ON %I.%I', r.schema_name, r.table_name);
    EXECUTE format(
      'CREATE POLICY retention_all_tenants ON %I.%I FOR ALL TO hms_retention USING (true) WITH CHECK (true)',
      r.schema_name, r.table_name
    );
  END LOOP;
END
$$;

-- `hms_retention` gets UPDATE and not DELETE on `lab_if_messages` deliberately:
-- `EN-004 §5` retains the *parsed metadata* for two years after the raw bytes go
-- at 90 days, so the 90-day job nulls `raw` and stamps `raw_purged_at` rather
-- than removing the row. A message log that vanishes at 90 days cannot answer
-- "what did the analyzer actually send in March", which is the question a
-- disputed result asks.
COMMENT ON COLUMN integration.lab_if_messages.raw_purged_at IS
  'When the encrypted raw frame was removed under the 90-day policy (EN-004 §5). The parsed metadata survives to two years, so a message log stays reviewable without keeping PHI on disk longer than the policy allows.';

-- ── 5. assert the grants match the intent ───────────────────────────────────
DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s.%s', table_schema, table_name), ', ' ORDER BY table_schema, table_name)
  INTO v_bad
  FROM core.v_grant_coverage
  WHERE readonly_has_write;

  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Phase 3 granted write privileges to hms_readonly on: %', v_bad;
  END IF;

  -- The critical-value evidence must be append-only. This is the assertion the
  -- whole D-10 arrangement turns on: if the callback log were editable, a
  -- read-back could be ticked after the fact and the documentation requirement
  -- would mean nothing.
  IF has_table_privilege('hms_app', 'lab.lab_critical_value_callbacks', 'UPDATE')
     OR has_table_privilege('hms_app', 'lab.lab_critical_value_callbacks', 'DELETE')
     OR has_table_privilege('hms_app', 'rad.rad_critical_callbacks', 'UPDATE')
     OR has_table_privilege('hms_app', 'rad.rad_critical_callbacks', 'DELETE')
  THEN
    RAISE EXCEPTION
      'The critical-value callback log is writable after the fact. docs/DECISIONS.md D-10 requires a *documented* read-back or escalation; a record that can be edited later documents nothing.';
  END IF;

  -- The Form F register must be undeletable.
  IF has_table_privilege('hms_app', 'rad.rad_form_f', 'DELETE') THEN
    RAISE EXCEPTION
      'PC-PNDT: rad.rad_form_f is deletable by hms_app. The Form F register must be preserved and produced on inspection (Section 29).';
  END IF;

  -- No result, report or QC run may be deleted.
  IF has_table_privilege('hms_app', 'lab.lab_result_versions', 'DELETE')
     OR has_table_privilege('hms_app', 'lab.labq_qc_runs', 'DELETE')
     OR has_table_privilege('hms_app', 'rad.rad_report_versions', 'DELETE')
     OR has_table_privilege('hms_app', 'clinical.investigation_report_versions', 'DELETE')
  THEN
    RAISE EXCEPTION
      'A result, report or QC run is deletable by hms_app. CLAUDE.md §4: clinical rows are never hard-deleted; EN-031 §5: a QC point is voided, never removed.';
  END IF;
END
$$;

-- ── 6. table comments: what an assessor reads first ─────────────────────────
COMMENT ON TABLE lab.lab_orders IS
  'OP-004. The LIS''s record of fulfilling one or more CPOE lines, with its own accession number (`LAB_ACC`) and its own status vocabulary. It does not replace `clinical.orders`: Phase 2 left `order_items.fulfilment_module`/`fulfilment_ref` for exactly this, and `lab_order_tests.order_item_id` points back at the line that caused each test.';
COMMENT ON TABLE lab.lab_samples IS
  'OP-004 §3.2. The physical specimen, one row per container. Three constraints carry phase-03 exit gate 3: a rejected sample cannot exist without a coded reason (in both directions), it cannot exist without an attributed rejector, and a recollection must trace back to the order that was rejected — `lab.enforce_recollection_trace()` accepts the two legitimate shapes and refuses everything else. A fourth, in `lab.refuse_result_on_rejected_sample()`, makes it impossible for a rejected specimen to produce a result at all.';
COMMENT ON TABLE lab.lab_results IS
  'The identity of one measurable thing — one analyte of one order line — plus a projection of its head version, maintained by trigger. Partitioned monthly on `created_at`, which is timestamptz(3) so the composite primary key round-trips through a JavaScript Date exactly (D-31). The values are in `lab_result_versions`.';
COMMENT ON TABLE lab.lab_result_versions IS
  'Append-only, hash-chained, and typed. The measured value is frozen from INSERT — not from signature — because a number that changes between entry and authorisation is a different measurement and deserves its own version; the review trail moves forward and is write-once per field. The digest is computed by the database over the measured half only, so stamping a verification does not invalidate the chain. `lab.verify_result_chain(result_id)` re-derives both from scratch.';
COMMENT ON TABLE lab.labq_analyte_qc_state IS
  'The release gate, as a row: one state per analyte × instrument, defaulting to `never_evaluated`. docs/prompts/phase-03 §Non-negotiables 3 — "a QC state that permits release must be distinguishable from one that has never been evaluated; unknown is not passed". `lab.qc_permits_release()` is the single predicate that decides, it is a whitelist, and the migration asserts at apply time that it answers false for `never_evaluated`. Absence of a row means the same as an explicit `never_evaluated`, never permission.';
COMMENT ON TABLE lab.labq_qc_runs IS
  'EN-031 §3.3. Partitioned monthly on `run_at` (timestamptz(3), D-31); retained five years as NABL evidence. Never deleted: a mistaken entry is voided with a reason and stays on the Levey-Jennings chart as a voided point, because a chart you can delete points from is a chart that shows whatever the laboratory wants.';
COMMENT ON TABLE lab.lab_critical_value_alerts IS
  'The obligation to communicate a critical value, raised by a database trigger in the same transaction that stores the value — so storing a critical result and raising its alert cannot come apart, whatever code path wrote it. docs/DECISIONS.md D-10: release is never withheld. The evidence that the obligation was met is `lab_critical_value_callbacks`.';
COMMENT ON TABLE lab.lab_critical_value_callbacks IS
  'One documented communication attempt, append-only. The CHECK is docs/prompts/phase-03 §Non-negotiables 1 in SQL: either a confirmed read-back from a named clinician, or a documented "unreachable — escalated to <tier>". Neither is unstorable; both at once is unstorable. Authorising a critical result requires at least one of these rows — the block is on the signature, never on the number.';
COMMENT ON TABLE lab.lab_reference_ranges IS
  'OP-004 §5: effective-dated, and the interval in force is snapshotted onto the result version so a report reprinted in 2031 shows what was actually used. `low`/`high` bound the NORMAL band and `critical_low`/`critical_high` the panic bounds — the columns Phase 2 got wrong for vitals, which is why `src/seed/lab-ranges.spec.ts` exists.';
COMMENT ON TABLE rad.rad_exams IS
  'OP-008 / EN-035 §4: the technologist''s record of performing an exam. Distinct from `rad.pacs_studies`, which is EN-008''s index of what is in the archive — OP-008 §4 calls both "studies" and one system cannot have two tables of that name meaning different things. Joined by `study_instance_uid` and `accession_no`, both generated by the HMS and never by the modality (EN-035 §5).';
COMMENT ON TABLE rad.rad_form_f IS
  'The PC-PNDT Form F register. Statutory under the Pre-Conception and Pre-Natal Diagnostic Techniques (Prohibition of Sex Selection) Act 1994: an obstetric ultrasound cannot be completed or reported without a complete one, the machine must be registered under the Act, and once both declarations are signed the row is immutable and undeletable. What is deliberately absent — and asserted absent by §C.7, which reads information_schema and fails the migration if it appears — is any column that could hold the sex of a foetus.';
COMMENT ON TABLE rad.pacs_studies IS
  'EN-008''s index of what is in Orthanc — identifiers, counts, sizes and lifecycle, never pixels. `patient_id` is nullable and `reconciliation_status` defaults to `needs_review` on purpose: EN-008 §5 requires that a study which cannot be matched confidently has NO patient rather than a guessed one, the same principle as the analyzer unmatched queue.';
COMMENT ON TABLE rad.pacs_instances IS
  'One row per DICOM object: SOP instance UID, class, size and the Orthanc id. References, not pixels. Partitioned monthly on `stored_at` (timestamptz(3), D-31) because a single CT of the abdomen is one to three thousand rows.';
COMMENT ON TABLE integration.lab_if_error_queue IS
  'docs/prompts/phase-03 §Constraints: "Unmatched analyzer results go to a queue, never auto-assigned by name similarity." `suggested_sample_id` may be computed and shown; `resolved_sample_id` may only be set together with a `resolved_by`, which is what makes "a human decided" a property of the data rather than of whichever service happened to run.';
COMMENT ON TABLE integration.lab_if_messages IS
  'EN-004 §4. Every HL7/ASTM frame, in and out, partitioned monthly on `received_at` (timestamptz(3), D-31). `raw` is bytea and is PHI — an ORU carries the patient''s name and identifiers in PID — so it is purged at 90 days by nulling the column and stamping `raw_purged_at`, while the parsed metadata survives to two years.';
COMMENT ON TABLE clinical.investigation_reports IS
  'OP-022: everything that is neither a lab analyzer nor a DICOM modality — an ECG strip, a PFT trace, an endoscopy image set, an outside report being filed. Same identity/versions split, same hash chain and same immutability rules as the lab and radiology reports, and it files into `clinical.documents` so there is one verifier and one answer to "is this report authentic".';
COMMENT ON TABLE mdm.mdm_lab_tests IS
  'EN-027. OP-004 §4 marks the test catalogue `lab_tests (mdm)` — the only entry in its own data model that is not in schema `lab` — because a catalogue entry is priced by RC-003, ordered by OP-002 and reported on by EN-001, which makes it master data with the effective-dated identity every other master has. `is_nabl_scope` decides whether the NABL logo may lawfully print on a report; `lab.labq_scope_tests` is the evidence behind it.';
COMMENT ON TABLE mdm.mdm_rad_procedures IS
  'EN-027 / EN-035 §4. `is_pcpndt` is the column the whole PC-PNDT machinery hangs off and is snapshotted onto every order item, so a later master edit cannot lift the Form F obligation from a study performed under it. `is_ionising` does the same for the AERB dose obligation.';


-- ─────────────────────────────────────────────────────────────────────────────
-- ROLLBACK:
--   This migration adds two schemas, 100 tables, 49 enums, constraints,
--   triggers, functions, indexes and grants. It seeds no rows: a test
--   catalogue, a rejection list, a Westgard rule set and a diagnostic reference
--   level are all things a laboratory or an imaging department authors under its
--   own accreditation, and shipping a "product default" reference range would be
--   exactly the guessing CLAUDE.md §0.1 forbids.
--
--   It changes three things that existed before it, and each must be put back:
--
--     * `core.v_rls_coverage`, `core.v_rls_open_policies` and
--       `core.v_grant_coverage` were widened from eight schemas to ten. Restore
--       the Phase-1 definitions (which the Phase-1 migration holds verbatim),
--       or the monitors will report on schemas that no longer exist.
--     * `core.ensure_month_partition_writable()` is new and is referenced by the
--       partition-maintenance job. Remove the job's registration first.
--     * `ALTER DEFAULT PRIVILEGES … IN SCHEMA lab, rad` must be reversed with the
--       matching REVOKE form before the schemas are dropped.
--
--   To reverse it on a database with no rows in these tables:
--
--     DROP SCHEMA IF EXISTS lab CASCADE;
--     DROP SCHEMA IF EXISTS rad CASCADE;
--
--     DROP TABLE IF EXISTS
--       clinical.investigation_report_deliveries,
--       clinical.investigation_report_versions, clinical.investigation_reports,
--       clinical.investigation_annotations, clinical.investigation_media,
--       clinical.investigation_studies, clinical.investigation_watch_folder_agents,
--       integration.lab_interface_verifications, integration.lab_instrument_downtime,
--       integration.lab_if_autoval_decisions, integration.lab_if_autoval_rulesets,
--       integration.lab_if_worklist_cache, integration.lab_if_error_queue,
--       integration.lab_if_messages, integration.lab_instrument_test_maps,
--       integration.lab_instruments,
--       mdm.mdm_investigation_services, mdm.mdm_rad_procedures,
--       mdm.mdm_lab_panel_members, mdm.mdm_lab_test_parameters,
--       mdm.mdm_lab_tests, mdm.mdm_lab_containers, mdm.mdm_lab_specimen_types
--       CASCADE;
--
--     DROP FUNCTION IF EXISTS clinical.enforce_investigation_cosign();
--     DROP FUNCTION IF EXISTS clinical.sync_investigation_report_head();
--     DROP FUNCTION IF EXISTS clinical.enforce_investigation_report_immutability();
--     DROP FUNCTION IF EXISTS clinical.seal_investigation_report_version();
--     DROP FUNCTION IF EXISTS core.ensure_month_partition_writable(text, text, date);
--
--     -- then the enum types CASCADE will not remove:
--     --   mdm.LabDiscipline, mdm.LabResultType, mdm.RadModality,
--     --   mdm.InvestigationModalityGroup,
--     --   clinical.InvestigationStudyStatus, clinical.InvestigationReportStatus,
--     --   clinical.InvestigationMediaKind, clinical.InvestigationMediaSource,
--     --   integration.LabIfProtocol, LabIfTransport, LabInstrumentStatus,
--     --   LabIfDirection, LabIfMessageStatus, LabIfErrorType.
--     -- (The `lab.*` and `rad.*` enums go with their schemas.)
--
--     -- and restore the Phase-1 definitions of core.v_rls_coverage,
--     -- core.v_rls_open_policies and core.v_grant_coverage.
--
--   Once a specimen has been collected or a study acquired this is not
--   reversible, and per docs/09 §16 that belongs in the release note. Two things
--   in particular are one-way:
--
--     * `rad.rad_form_f` is a statutory register under the PC-PNDT Act with a
--       preservation obligation (Section 29). Dropping it on a production
--       database that has recorded an obstetric ultrasound is not a rollback,
--       it is an offence.
--     * `lab.lab_result_versions` is the clinical record of what was measured,
--       with a ten-year retention, and `lab.labq_qc_runs` is five years of
--       accreditation evidence. Neither can be recreated from anything else.
--
--   Every release after Phase 0 uses expand/contract (docs/10 §6). Phase 3 is
--   deliberately additive: it does not alter one Phase-2 column, and it attaches
--   to CPOE through the `fulfilment_module` / `fulfilment_ref` pair that
--   `clinical.order_items` has been carrying since Phase 2 for exactly this.
-- ─────────────────────────────────────────────────────────────────────────────
